-- Easy Professions (Forever): guide texts in ptBR (translated from wow-professions.com/forever)
local _, ns = ...
ns.AddTranslation("ptBR", {
  ["This WoW Forever Alchemy leveling guide will show you the fastest and cheapest way to level your Alchemy skill from 1 to 300. You will also find every trainer location and where to train Alchemy past 75, 150 and 225."] = "Este guia de Alquimia do WoW Forever mostra a forma mais rápida e barata de subir sua perícia de Alquimia de 1 a 300. Você também encontra a localização de todos os instrutores e onde treinar Alquimia acima de 75, 150 e 225.",
  ["Below you will find the full shopping list, the Alchemy trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Alchemy is best combined with Herbalism, with these two you can save a lot of gold because you don't have to buy the herbs from the Auction House."] = "Abaixo você encontra a lista de compras completa, os instrutores de Alquimia por zona inicial e capital, e as receitas mais baratas para cada faixa de perícia, de Aprendiz a Artesão. Alquimia combina melhor com Herborismo: com as duas você economiza muito ouro, porque não precisa comprar as ervas na casa de leilões.",
  ["This is based on the Forever beta. Leveling takes a long time, so testing the higher levels on live will take a while. If you find something that's off, send me feedback."] = "Este guia se baseia no beta do Forever. Subir de nível leva bastante tempo, então testar os níveis mais altos no servidor oficial vai demorar um pouco. Se encontrar algo errado, me mande seu feedback.",
  ["Shopping List"] = "Lista de compras",
  ["These numbers are estimates. Once a recipe turns yellow you won't get a skill point from every craft, so you might need a few more or a few less."] = "Estes números são estimativas. Quando uma receita fica amarela, nem toda criação dá um ponto de perícia, então talvez você precise de um pouco mais ou de um pouco menos.",
  ["Alchemy Trainer Locations"] = "Localização dos instrutores de Alquimia",
  ["Apprentice Alchemy has no level requirement in Forever, so you can learn it on a fresh character."] = "No Forever, Alquimia Aprendiz não tem requisito de nível, então você pode aprendê-la com um personagem recém-criado.",
  ["Every capital city has a trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "Toda capital tem um instrutor. Você também pode perguntar a um guarda, e ele será marcado com uma bandeira vermelha no seu mapa.",
  ["Horde"] = "Horda",
  ["Alliance"] = "Aliança",
  ["Capital Cities"] = "Capitais",
  ["Undercity: {n:0:horde:Doctor Martin Felben}"] = "Cidade Baixa: {n:0:horde:Doctor Martin Felben}",
  ["Thunder Bluff: {n:0:horde:Kray}"] = "Penhasco do Trovão: {n:0:horde:Kray}",
  ["Starting Zones"] = "Zonas iniciais",
  ["Not every zone has a trainer, the table shows the closest one for each race."] = "Nem toda zona tem um instrutor; a tabela mostra o mais próximo para cada raça.",
  ["Race"] = "Raça",
  ["Zone"] = "Zona",
  ["Closest trainer"] = "Instrutor mais próximo",
  ["{n:0:horde:Miao'zan} in Sen'jin Village"] = "{n:0:horde:Miao'zan} na Vila Sen'jin",
  ["There is no Alchemy trainer in Mulgore, go to {n:0:horde:Kray} on the middle rise in Thunder Bluff"] = "Não há instrutor de Alquimia em Mulgore; vá até {n:0:horde:Kray} no platô do meio em Penhasco do Trovão",
  ["Undead"] = "Morto-vivo",
  ["Tirisfal Glades"] = "Clareiras de Tirisfal",
  ["{n:0:horde:Carolai Anise} in the small house at the north-west end of Brill"] = "{n:0:horde:Carolai Anise} na casinha no extremo noroeste de Montalvo",
  ["{n:0::Iaadaria Bitterwind} or {n:0::Valiena Swiftgale} in Valanaar, {n:0::Nyassa Swiftdraught} in Shen'dar Village"] = "{n:0::Iaadaria Bitterwind} ou {n:0::Valiena Swiftgale} em Valanaar, {n:0::Nyassa Swiftdraught} em Shen'dar Village",
  ["Stormwind City: {n:0:alliance:Tel'Athir}"] = "Ventobravo: {n:0:alliance:Tel'Athir}",
  ["Ironforge: {n:0:alliance:Vosur Brakthel}"] = "Altaforja: {n:0:alliance:Vosur Brakthel}",
  ["Human"] = "Humano",
  ["Elwynn Forest"] = "Floresta de Elwynn",
  ["{n:0:alliance:Alchemist Mallory} in a cottage in the hills between Stormwind and Northshire"] = "{n:0:alliance:Alchemist Mallory} em uma cabana nas colinas entre Ventobravo e Vila Norte",
  ["Dwarf, Gnome"] = "Anão, Gnomo",
  ["There is no Alchemy trainer in Dun Morogh, go to {n:0:alliance:Vosur Brakthel} in Tinker Town in Ironforge"] = "Não há instrutor de Alquimia em Dun Morogh; vá até {n:0:alliance:Vosur Brakthel} na Cidade da Gambiarra, em Altaforja",
  ["Night Elf"] = "Elfo Noturno",
  ["{n:0:alliance:Cyndra Kindwhisper} in a small house east of the inn in Dolanaar"] = "{n:0:alliance:Cyndra Kindwhisper} em uma casinha a leste da estalagem em Dolanaar",
  ["You can find every Alchemy trainer for Horde and Alliance on my WoW Forever Alchemy Trainers page."] = "Você encontra todos os instrutores de Alquimia da Horda e da Aliança na minha página de instrutores de Alquimia do WoW Forever.",
  ["Apprentice Alchemy (1-55)"] = "Alquimia Aprendiz (1-55)",
  ["9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 9 Silverleaf, 9 Empty Vial"] = "9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 9 Folha-prata, 9 Frasco Vazio",
  ["The vials are sold by Alchemy Supply and Trade Supply vendors, most trainers have one nearby. In Undercity the closest one is {n:0:horde:Algernon}, in Dolanaar it's {n:0:alliance:Narret Shadowgrove}."] = "Os frascos são vendidos pelos vendedores de suprimentos de Alquimia e de mercadorias, e a maioria dos instrutores tem um por perto. Na Cidade Baixa o mais próximo é {n:0:horde:Algernon}; em Dolanaar é {n:0:alliance:Narret Shadowgrove}.",
  ["45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 45 Silverleaf, 45 Peacebloom, 45 Empty Vial"] = "45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 45 Folha-prata, 45 Flor-da-paz, 45 Frasco Vazio",
  ["Journeyman Alchemy (55-150)"] = "Alquimia Artífice (55-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Alchemy. You need {b}Alchemy 50{/b} and {b}level 10{/b}:"] = "Para treinar acima de 75, visite um destes instrutores e aprenda Alquimia Artífice. Você precisa de {b}Alquimia 50{/b} e {b}nível 10{/b}:",
  ["{b}Horde trainers:{/b}"] = "{b}Instrutores da Horda:{/b}",
  ["Undercity: {n:0:horde:Doctor Marsh}"] = "Cidade Baixa: {n:0:horde:Doctor Marsh}",
  ["Thunder Bluff: {n:0:horde:Bena Winterhoof}"] = "Penhasco do Trovão: {n:0:horde:Bena Winterhoof}",
  ["{b}Alliance trainers:{/b}"] = "{b}Instrutores da Aliança:{/b}",
  ["Stormwind City: {n:0:alliance:Lilyssia Nightbreeze}"] = "Ventobravo: {n:0:alliance:Lilyssia Nightbreeze}",
  ["Ironforge: {n:0:alliance:Tally Berryfizz}"] = "Altaforja: {n:0:alliance:Tally Berryfizz}",
  ["10x {s:2331:inv_potion_70:Minor Mana Potion} - 10 Mageroyal, 10 Peacebloom, 10 Empty Vial"] = "10x {s:2331:inv_potion_70:Minor Mana Potion} - 10 Magiroyal, 10 Flor-da-paz, 10 Frasco Vazio",
  ["28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 56 Earthroot, 28 Peacebloom, 28 Empty Vial"] = "28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 56 Raiz-da-terra, 28 Flor-da-paz, 28 Frasco Vazio",
  ["30x {s:3171:inv_potion_06:Elixir of Wisdom} - 30 Mageroyal, 60 Briarthorn, 30 Empty Vial"] = "30x {s:3171:inv_potion_06:Elixir of Wisdom} - 30 Magiroyal, 60 Espinheiro, 30 Frasco Vazio",
  ["Keep the elixirs if you also level Tailoring, you will need them for the Gloves of Meditation."] = "Guarde os elixires se você também estiver subindo Alfaiataria; vai precisar deles para as Luvas da Meditação.",
  ["10x {s:3173:inv_potion_71:Lesser Mana Potion} - 10 Mageroyal, 10 Stranglekelp, 10 Empty Vial"] = "10x {s:3173:inv_potion_71:Lesser Mana Potion} - 10 Magiroyal, 10 Alga-estranguladora, 10 Frasco Vazio",
  ["20x {s:7837:inv_potion_38:Fire Oil} - 40 Firefin Snapper, 20 Empty Vial"] = "20x {s:7837:inv_potion_38:Fire Oil} - 40 Lutjano Barbatana-de-fogo, 20 Frasco Vazio",
  ["You get 2 oils from every craft. Keep 30 of them, you will need them for the Elixir of Fire Power in the next part."] = "Cada criação rende 2 óleos. Guarde 30 deles; você vai precisar deles para o Elixir do Poder do Fogo na próxima parte.",
  ["Expert Alchemy (150-225)"] = "Alquimia Especialista (150-225)",
  ["To train past 150, visit {n:0:horde:Doctor Herbert Halsey} in Undercity (Horde) or {n:0:alliance:Ainethil} in Darnassus (Alliance) and learn Expert Alchemy. You need {b}Alchemy 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Para treinar acima de 150, visite {n:0:horde:Doctor Herbert Halsey} na Cidade Baixa (Horda) ou {n:0:alliance:Ainethil} em Darnassus (Aliança) e aprenda Alquimia Especialista. Você precisa de {b}Alquimia 125{/b} e {b}nível 20{/b}, e custa 50 pratas.",
  ["15x {s:7845:inv_potion_55:Elixir of Fire Power} - 30 Fire Oil, 15 Kingsblood, 15 Leaded Vial"] = "15x {s:7845:inv_potion_55:Elixir of Fire Power} - 30 Óleo de Fogo, 15 Sangue-real, 15 Frasco com Chumbo",
  ["These are the Fire Oils you kept."] = "Estes são os Óleos de Fogo que você guardou.",
  ["36x {s:3452:inv_potion_72:Mana Potion} - 36 Stranglekelp, 36 Kingsblood, 36 Leaded Vial"] = "36x {s:3452:inv_potion_72:Mana Potion} - 36 Alga-estranguladora, 36 Sangue-real, 36 Frasco com Chumbo",
  ["36x {s:7259:inv_potion_06:Nature Protection Potion} - 36 Liferoot, 36 Stranglekelp, 36 Leaded Vial"] = "36x {s:7259:inv_potion_06:Nature Protection Potion} - 36 Raiz-da-vida, 36 Alga-estranguladora, 36 Frasco com Chumbo",
  ["{i:6057:inv_scroll_03:Recipe: Nature Protection Potion} is sold by these vendors, it's bind on pickup, so buy it with the character that levels Alchemy:"] = "{i:6057:inv_scroll_03:Recipe: Nature Protection Potion} é vendida por estes vendedores. Ela é vinculada ao ser coletada, então compre-a com o personagem que está subindo Alquimia:",
  ["{n:0:horde:Bronk} in Feralas"] = "{n:0:horde:Bronk} em Feralas",
  ["{n:0:alliance:Logannas} in Feralas"] = "{n:0:alliance:Logannas} em Feralas",
  ["{n:0::Glyx Brewright} in Stranglethorn Vale"] = "{n:0::Glyx Brewright} na Selva do Espinhaço",
  ["{n:0::Alchemist Pestlezugg} in Tanaris"] = "{n:0::Alchemist Pestlezugg} em Tanaris",
  ["Artisan Alchemy (225-300)"] = "Alquimia Artesão (225-300)",
  ["To train past 225, visit {n:0:horde:Rogvar} in Stonard, Swamp of Sorrows (Horde) or {n:0:alliance:Kylanna Windwhisper} in Feathermoon Stronghold, Feralas (Alliance) and learn Artisan Alchemy. You need {b}Alchemy 200{/b} and {b}level 35{/b}."] = "Para treinar acima de 225, visite {n:0:horde:Rogvar} em Pedregal, no Pântano das Mágoas (Horda) ou {n:0:alliance:Kylanna Windwhisper} na Fortaleza Plumaluna, em Feralas (Aliança) e aprenda Alquimia Artesão. Você precisa de {b}Alquimia 200{/b} e {b}nível 35{/b}.",
  ["26x {s:7259:inv_potion_06:Nature Protection Potion} - 26 Liferoot, 26 Stranglekelp, 26 Leaded Vial"] = "26x {s:7259:inv_potion_06:Nature Protection Potion} - 26 Raiz-da-vida, 26 Alga-estranguladora, 26 Frasco com Chumbo",
  ["15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 15 Blindweed, 15 Khadgar's Whisker, 15 Crystal Vial"] = "15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 15 Erva-cega, 15 Bigode-de-Khadgar, 15 Frasco de Cristal",
  ["47x {s:17551:inv_potion_68:Stonescale Oil} - 47 Stonescale Eel, 47 Leaded Vial"] = "47x {s:17551:inv_potion_68:Stonescale Oil} - 47 Enguia Escamapétrea, 47 Frasco com Chumbo",
  ["{b}Keep all of them{/b}, one craft makes 2 and the elixirs at 265 need all 94."] = "{b}Guarde todos{/b}: cada criação rende 2, e os elixires em 265 precisam de todos os 94.",
  ["Alternative recipe"] = "Receita alternativa",
  ["If {i:13422:inv_misc_fish_11:Stonescale Eel} is expensive, skip this and keep making the Elixir of Greater Intellect until 265 (about 21), then make the Superior Mana Potions under 265-300."] = "Se {i:13422:inv_misc_fish_11:Stonescale Eel} estiver cara, pule esta etapa e continue fazendo o Elixir de Intelecto Maior até 265 (cerca de 21), depois faça as Poções de Mana Superior da etapa 265-300.",
  ["10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 10 Blindweed, 10 Khadgar's Whisker, 10 Crystal Vial"] = "10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 10 Erva-cega, 10 Bigode-de-Khadgar, 10 Frasco de Cristal",
  ["47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 94 Stonescale Oil, 47 Sungrass, 47 Crystal Vial"] = "47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 94 Óleo de Escamapétrea, 47 Capim-do-sol, 47 Frasco de Cristal",
  ["{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense} is sold by {n:0:horde:Kor'geld} in Orgrimmar and {n:0:alliance:Soolie Berryfizz} in Ironforge."] = "{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense} é vendida por {n:0:horde:Kor'geld} em Orgrimmar e por {n:0:alliance:Soolie Berryfizz} em Altaforja.",
  ["If you skipped the Stonescale Oil, make this:"] = "Se você pulou o Óleo de Escamapétrea, faça isto:",
  ["55x {s:17553:inv_potion_74:Superior Mana Potion} - 110 Sungrass, 110 Blindweed, 55 Crystal Vial."] = "55x {s:17553:inv_potion_74:Superior Mana Potion} - 110 Capim-do-sol, 110 Erva-cega, 55 Frasco de Cristal.",
  ["{i:13477:inv_scroll_03:Recipe: Superior Mana Potion} is sold by {n:0:horde:Algernon} in Undercity and {n:0:alliance:Ulthir} in Darnassus."] = "{i:13477:inv_scroll_03:Recipe: Superior Mana Potion} é vendida por {n:0:horde:Algernon} na Cidade Baixa e por {n:0:alliance:Ulthir} em Darnassus.",
  ["This WoW Forever Blacksmithing leveling guide will show you the fastest and cheapest way to level your Blacksmithing skill from 1 to 300. You will also find every trainer location and where to train Blacksmithing past 75, 150 and 225."] = "Este guia de Ferraria do WoW Forever mostra a forma mais rápida e barata de subir sua perícia de Ferraria de 1 a 300. Você também encontra a localização de todos os instrutores e onde treinar Ferraria acima de 75, 150 e 225.",
  ["Below you will find the full shopping list, the Blacksmithing trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Blacksmithing uses a lot of ore, so I recommend leveling it together with Mining, you will need a lot of gold if you want to buy everything from the Auction House."] = "Abaixo você encontra a lista de compras completa, os instrutores de Ferraria por zona inicial e capital, e as receitas mais baratas para cada faixa de perícia, de Aprendiz a Artesão. Ferraria usa muito minério, então recomendo subi-la junto com Mineração; você vai precisar de muito ouro se quiser comprar tudo na casa de leilões.",
  ["The Thorium Bars include the 140 you need for the four quests."] = "As Barras de Tório incluem as 140 que você precisa para as quatro missões.",
  ["Blacksmithing Trainer Locations"] = "Localização dos instrutores de Ferraria",
  ["Apprentice Blacksmithing has no level requirement in Forever, so you can learn it on a fresh character."] = "No Forever, Ferraria Aprendiz não tem requisito de nível, então você pode aprendê-la com um personagem recém-criado.",
  ["Every capital city has a trainer except Darnassus. You can also ask a guard, then it will be marked with a red flag on your map."] = "Toda capital tem um instrutor, exceto Darnassus. Você também pode perguntar a um guarda, e ele será marcado com uma bandeira vermelha no seu mapa.",
  ["Undercity: {n:0:horde:Basil Frye}"] = "Cidade Baixa: {n:0:horde:Basil Frye}",
  ["Thunder Bluff: {n:0:horde:Thrag Stonehoof}"] = "Penhasco do Trovão: {n:0:horde:Thrag Stonehoof}",
  ["{n:0:horde:Dwukk} at the forge in Razor Hill"] = "{n:0:horde:Dwukk} na forja do Monte da Navalha",
  ["There is no Blacksmithing trainer in Mulgore, go to {n:0:horde:Thrag Stonehoof} on the lower rise in Thunder Bluff"] = "Não há instrutor de Ferraria em Mulgore; vá até {n:0:horde:Thrag Stonehoof} no platô de baixo em Penhasco do Trovão",
  ["{n:0:horde:Angus Hammerhand} at Bandarion Keep. Nobody near him sells a {i:5956:inv_hammer_20:Blacksmith Hammer}, {b}buy one before you go{/b} from {n:0:horde:Walter Mason} in Deathknell or {n:0:horde:Abigail Shiel} in Brill."] = "{n:0:horde:Angus Hammerhand} no Bandarion Keep. Ninguém perto dele vende um {i:5956:inv_hammer_20:Blacksmith Hammer}, então {b}compre um antes de ir{/b} com {n:0:horde:Walter Mason} em Plangemortis ou {n:0:horde:Abigail Shiel} em Montalvo.",
  ["{n:0::Daeann Steelwind} in Valanaar, {n:0::Aedi Thriceforged} in Shen'dar Village"] = "{n:0::Daeann Steelwind} em Valanaar, {n:0::Aedi Thriceforged} em Shen'dar Village",
  ["Stormwind City: {n:0:alliance:Dane Lindgren}"] = "Ventobravo: {n:0:alliance:Dane Lindgren}",
  ["Ironforge: {n:0:alliance:Groum Stonebeard}"] = "Altaforja: {n:0:alliance:Groum Stonebeard}",
  ["{n:0:alliance:Smith Argus} in Goldshire, across from the inn"] = "{n:0:alliance:Smith Argus} em Vila d'Ouro, em frente à estalagem",
  ["{n:0:alliance:Tognus Flintfire} in Kharanos, across from the Thunderbrew Distillery"] = "{n:0:alliance:Tognus Flintfire} em Kharanos, em frente à Cervejaria Cervaforte",
  ["There is no Blacksmithing trainer in Teldrassil or Darnassus, the closest one is {n:0:alliance:Delfrum Flintbeard} in Auberdine, Darkshore"] = "Não há instrutor de Ferraria em Teldrassil nem em Darnassus; o mais próximo é {n:0:alliance:Delfrum Flintbeard} em Auberdine, na Costa Negra",
  ["You can find every Blacksmithing trainer for Horde and Alliance on my WoW Forever Blacksmithing Trainers page."] = "Você encontra todos os instrutores de Ferraria da Horda e da Aliança na minha página de instrutores de Ferraria do WoW Forever.",
  ["Apprentice Blacksmithing (1-75)"] = "Ferraria Aprendiz (1-75)",
  ["Buy a {i:5956:inv_hammer_20:Blacksmith Hammer} when you learn Blacksmithing, most recipes need it, so you can craft gear for yourself while you level. It costs a few copper, open your faction below to see who sells it closest to your trainer."] = "Compre um {i:5956:inv_hammer_20:Blacksmith Hammer} quando aprender Ferraria. A maioria das receitas precisa dele, e assim você pode criar equipamentos para si mesmo enquanto sobe a perícia. Custa poucos cobres; abra sua facção abaixo para ver quem o vende mais perto do seu instrutor.",
  ["Horde vendors"] = "Vendedores da Horda",
  ["Vendor"] = "Vendedor",
  ["{n:0:horde:Sumi}, right next to the trainer"] = "{n:0:horde:Sumi}, bem ao lado do instrutor",
  ["Undercity"] = "Cidade Baixa",
  ["{n:0:horde:Samuel Van Brunt}, right next to the trainer"] = "{n:0:horde:Samuel Van Brunt}, bem ao lado do instrutor",
  ["Thunder Bluff"] = "Penhasco do Trovão",
  ["{n:0:horde:Taur Stonehoof}, right next to the trainer"] = "{n:0:horde:Taur Stonehoof}, bem ao lado do instrutor",
  ["{n:0:horde:Flakk} in Razor Hill"] = "{n:0:horde:Flakk} no Monte da Navalha",
  ["{n:0:horde:Walter Mason} in Deathknell {n:0:horde:Abigail Shiel} in Brill"] = "{n:0:horde:Walter Mason} em Plangemortis {n:0:horde:Abigail Shiel} em Montalvo",
  ["{n:0::Halavuul Cragwind}, the Mining trainer in Valanaar {n:0::Aedi Thriceforged} in Shen'dar Village"] = "{n:0::Halavuul Cragwind}, o instrutor de Mineração em Valanaar {n:0::Aedi Thriceforged} em Shen'dar Village",
  ["Alliance vendors"] = "Vendedores da Aliança",
  ["Stormwind City"] = "Ventobravo",
  ["{n:0:alliance:Kaita Deepforge}, right next to the trainer"] = "{n:0:alliance:Kaita Deepforge}, bem ao lado do instrutor",
  ["Ironforge"] = "Altaforja",
  ["{n:0:alliance:Thurgrum Deepforge}, right next to the trainer"] = "{n:0:alliance:Thurgrum Deepforge}, bem ao lado do instrutor",
  ["{n:0:alliance:Tharynn Bouden} in Goldshire"] = "{n:0:alliance:Tharynn Bouden} em Vila d'Ouro",
  ["{n:0:alliance:Thrawn Boltar}, right next to the trainer"] = "{n:0:alliance:Thrawn Boltar}, bem ao lado do instrutor",
  ["Darkshore"] = "Costa Negra",
  ["{n:0:alliance:Elisa Steelhand} in Auberdine, right next to the trainer"] = "{n:0:alliance:Elisa Steelhand} em Auberdine, bem ao lado do instrutor",
  ["30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 30 Rough Stone"] = "30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 30 Pedra Bruta",
  ["30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 60 Rough Stone"] = "30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 60 Pedra Bruta",
  ["Keep 10 of them, you need them for the Silver Rods at 75."] = "Guarde 10 delas; você vai precisar delas para os Bastões de Prata em 75.",
  ["36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 72 Coarse Stone"] = "36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 72 Pedra Grosseira",
  ["Make all 36, you will need them for the bracers at 95 and 112."] = "Faça todas as 36; você vai precisar delas para as braçadeiras em 95 e 112.",
  ["If you are not at 75 after these, make a few more."] = "Se ainda não estiver em 75 depois disso, faça mais algumas.",
