  ["Tirisfal Glades: {n:0:horde:Angus Hammerhand} at Bandarion Keep"] = "Clareiras de Tirisfal: {n:0:horde:Angus Hammerhand} no Bandarion Keep",
  ["Zephras Isle: {n:0::Daeann Steelwind} in Valanaar"] = "Zephras Isle: {n:0::Daeann Steelwind} em Valanaar",
  ["Stormwind City: {n:0:alliance:Therum Deepforge}"] = "Ventobravo: {n:0:alliance:Therum Deepforge}",
  ["Ironforge: {n:0:alliance:Rotgath Stonebeard}"] = "Altaforja: {n:0:alliance:Rotgath Stonebeard}",
  ["5x {s:7818:inv_staff_01:Silver Rod} - 5 Silver Bar, 10 Rough Grinding Stone"] = "5x {s:7818:inv_staff_01:Silver Rod} - 5 Barra de Prata, 10 Pedra de Amolar Bruta",
  ["You need the {i:5956:inv_hammer_20:Blacksmith Hammer} from here on."] = "A partir daqui você precisa do {i:5956:inv_hammer_20:Blacksmith Hammer}.",
  ["Make 5x {s:2666:inv_belt_03:Runed Copper Belt} instead (10 Copper Bar each) if one Silver Bar costs more than 10 Copper Bars."] = "Faça 5x {s:2666:inv_belt_03:Runed Copper Belt} no lugar (10 Barras de Cobre cada) se uma Barra de Prata custar mais que 10 Barras de Cobre.",
  ["18x {s:2666:inv_belt_03:Runed Copper Belt} - 180 Copper Bar"] = "18x {s:2666:inv_belt_03:Runed Copper Belt} - 180 Barra de Cobre",
  ["5x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 25 Bronze Bar, 10 Coarse Grinding Stone"] = "5x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 25 Barra de Bronze, 10 Pedra de Amolar Grosseira",
  ["Use 10 of the Coarse Grinding Stones you made at 50 and keep the other 26 for 112."] = "Use 10 das Pedras de Amolar Grosseiras que você fez em 50 e guarde as outras 26 para 112.",
  ["20x {s:3337:inv_stone_grindingstone_03:Heavy Grinding Stone} - 60 Heavy Stone"] = "20x {s:3337:inv_stone_grindingstone_03:Heavy Grinding Stone} - 60 Pedra Pesada",
  ["Keep them, you need all 20 for the Golden Scale Bracers at 180."] = "Guarde-as; você vai precisar de todas as 20 para as Braçadeiras de Escamas Douradas em 180.",
  ["13x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 65 Bronze Bar, 26 Coarse Grinding Stone"] = "13x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 65 Barra de Bronze, 26 Pedra de Amolar Grosseira",
  ["24x {s:2742:inv_sword_04:Bronze Shortsword} - 120 Bronze Bar, 96 Weak Flux, 48 Medium Leather"] = "24x {s:2742:inv_sword_04:Bronze Shortsword} - 120 Barra de Bronze, 96 Fundente Fraco, 48 Couro Médio",
  ["I recommend these over the Patterned Bronze Bracers because they sell for more than twice as much to a vendor, so they end up cheaper."] = "Recomendo estas em vez das Braçadeiras de Bronze Padronizadas, porque são vendidas por mais do dobro do preço a um vendedor, então acabam saindo mais baratas.",
  ["{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} and the {i:3466:inv_misc_ammo_gunpowder_01:Strong Flux} for the Bronze Warhammers (140-150) are sold by the Blacksmithing Supply vendor right next to the Blacksmithing trainer in every capital city."] = "{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} e o {i:3466:inv_misc_ammo_gunpowder_01:Strong Flux} para os Martelos de Guerra de Bronze (140-150) são vendidos pelo vendedor de suprimentos de Ferraria, bem ao lado do instrutor de Ferraria em todas as capitais.",
  ["If you disenchant your greens:"] = "Se você desencanta seus itens verdes:",
  ["24x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 120 Bronze Bar, 48 Coarse Grinding Stone."] = "24x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 120 Barra de Bronze, 48 Pedra de Amolar Grosseira.",
  ["10x {s:9985:inv_hammer_18:Bronze Warhammer} - 80 Bronze Bar, 10 Strong Flux, 10 Medium Leather"] = "10x {s:9985:inv_hammer_18:Bronze Warhammer} - 80 Barra de Bronze, 10 Fundente Forte, 10 Couro Médio",
  ["Expert Blacksmithing (150-215)"] = "Ferraria Especialista (150-215)",
  ["To train past 150, visit {n:0:horde:Saru Steelfury} in Orgrimmar (Horde) or {n:0:alliance:Bengus Deepforge} in Ironforge (Alliance) and learn Expert Blacksmithing. You need {b}Blacksmithing 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Para treinar acima de 150, visite {n:0:horde:Saru Steelfury} em Orgrimmar (Horda) ou {n:0:alliance:Bengus Deepforge} em Altaforja (Aliança) e aprenda Ferraria Especialista. Você precisa de {b}Ferraria 125{/b} e {b}nível 20{/b}, e custa 50 pratas.",
  ["30x {s:3501:inv_bracer_06:Green Iron Bracers} - 180 Iron Bar, 30 Green Dye"] = "30x {s:3501:inv_bracer_06:Green Iron Bracers} - 180 Barra de Ferro, 30 Tintura Verde",
  ["Green Dye is sold by {n:0:horde:Tamar} in Orgrimmar and {n:0:alliance:Bombus Finespindle} in Ironforge."] = "A Tintura Verde é vendida por {n:0:horde:Tamar} em Orgrimmar e por {n:0:alliance:Bombus Finespindle} em Altaforja.",
  ["8x {s:9920:inv_stone_grindingstone_04:Solid Grinding Stone} - 32 Solid Stone"] = "8x {s:9920:inv_stone_grindingstone_04:Solid Grinding Stone} - 32 Pedra Sólida",
  ["Keep them, you need 6 for the Heavy Mithril Axes at 210."] = "Guarde-as; você vai precisar de 6 para os Machados de Mithril Pesado em 210.",
  ["20x {s:7223:inv_bracer_10:Golden Scale Bracers} - 100 Steel Bar, 40 Heavy Grinding Stone"] = "20x {s:7223:inv_bracer_10:Golden Scale Bracers} - 100 Barra de Aço, 40 Pedra de Amolar Pesada",
  ["Use the 20 Heavy Grinding Stones you made at 100 and make 20 more (60 {i:2838:inv_stone_12:Heavy Stone})."] = "Use as 20 Pedras de Amolar Pesadas que você fez em 100 e faça mais 20 (60 {i:2838:inv_stone_12:Heavy Stone}).",
  ["If you have Mining 165, you can smelt the {i:3859:inv_ingot_steel:Steel Bars} yourself from {i:3575:inv_ingot_iron:Iron Bar} and {i:3857:inv_ore_tin_01:Coal}. Coal is sold by the Blacksmithing Supply vendor next to the Blacksmithing trainer in every capital city."] = "Se você tiver Mineração 165, pode fundir as {i:3859:inv_ingot_steel:Steel Bars} você mesmo a partir de {i:3575:inv_ingot_iron:Iron Bar} e {i:3857:inv_ore_tin_01:Coal}. O Carvão é vendido pelo vendedor de suprimentos de Ferraria ao lado do instrutor de Ferraria em todas as capitais.",
  ["Alliance players should keep 6 of these. You might need them if you choose Armorsmithing."] = "Jogadores da Aliança devem guardar 6 destas. Talvez você precise delas se escolher Armeiro.",
  ["17x {s:9931:inv_pants_04:Mithril Plate Pants} - 204 Mithril Bar"] = "17x {s:9931:inv_pants_04:Mithril Plate Pants} - 204 Barra de Mithril",
  ["I recommend these over the Heavy Mithril Gauntlets because they sell for more than three times as much to a vendor, so they end up cheaper."] = "Recomendo estas em vez das Manoplas de Mithril Pesado, porque são vendidas por mais do triplo do preço a um vendedor, então acabam saindo mais baratas.",
  ["6x {s:9993:inv_axe_14:Heavy Mithril Axe} - 72 Mithril Bar, 12 Citrine, 6 Solid Grinding Stone, 24 Heavy Leather"] = "6x {s:9993:inv_axe_14:Heavy Mithril Axe} - 72 Barra de Mithril, 12 Citrino, 6 Pedra de Amolar Sólida, 24 Couro Pesado",
  ["Keep 2 of these. You might need them if you choose Weaponsmithing."] = "Guarde 2 destes. Talvez você precise deles se escolher Forjador de Armas.",
  ["Blacksmithing Specializations"] = "Especializações de Ferraria",
  ["At {b}Blacksmithing 200{/b} and {b}level 40{/b}, you can specialize in Armorsmithing or Weaponsmithing to craft powerful armor or weapons. Choosing one is optional, you don't need it to level Blacksmithing, and you can choose later too."] = "Com {b}Ferraria 200{/b} e {b}nível 40{/b}, você pode se especializar em Armeiro ou Forjador de Armas para criar armaduras ou armas poderosas. Escolher uma é opcional: você não precisa dela para subir Ferraria e também pode escolher mais tarde.",
  ["For information on how to become an Armorsmith or a Weaponsmith, please see my separate guides:"] = "Para saber como se tornar Armeiro ou Forjador de Armas, veja meus guias separados:",
  ["Artisan Blacksmithing (215-300)"] = "Ferraria Artesão (215-300)",
  ["To train past 225, visit {n:0::Brikk Keencraft} in Booty Bay, Stranglethorn Vale and learn Artisan Blacksmithing. You need {b}Blacksmithing 200{/b} and {b}level 35{/b}, and both factions learn it there."] = "Para treinar acima de 225, visite {n:0::Brikk Keencraft} na Angra do Butim, na Selva do Espinhaço, e aprenda Ferraria Artesão. Você precisa de {b}Ferraria 200{/b} e {b}nível 35{/b}, e as duas facções aprendem lá.",
  ["{i:7989:inv_scroll_06:Plans: Mithril Spurs} is a world drop. If you already have it, you can use the {b}Mithril Spurs{/b} tab instead."] = "{i:7989:inv_scroll_06:Plans: Mithril Spurs} é um drop do mundo. Se você já tiver, pode usar a aba {b}Esporas de Mithril{/b} no lugar.",
  ["Heavy Mithril"] = "Mithril Pesado",
  ["Mithril Spurs"] = "Esporas de Mithril",
  ["10x {s:9959:inv_chest_plate10:Heavy Mithril Breastplate} - 160 Mithril Bar"] = "10x {s:9959:inv_chest_plate10:Heavy Mithril Breastplate} - 160 Barra de Mithril",
  ["Keep 2 of these. You might need them if you choose Armorsmithing."] = "Guarde 2 destas. Talvez você precise delas se escolher Armeiro.",
  ["5x {s:16641:inv_stone_sharpeningstone_05:Dense Sharpening Stone} - 5 Dense Stone"] = "5x {s:16641:inv_stone_sharpeningstone_05:Dense Sharpening Stone} - 5 Pedra Densa",
  ["16x {s:9968:inv_boots_plate_01:Heavy Mithril Boots} - 224 Mithril Bar, 64 Thick Leather"] = "16x {s:9968:inv_boots_plate_01:Heavy Mithril Boots} - 224 Barra de Mithril, 64 Couro Grosso",
  ["5x {s:16647:inv_belt_01:Imperial Plate Belt} - 110 Thorium Bar, 30 Rugged Leather, 5 Aquamarine"] = "5x {s:16647:inv_belt_01:Imperial Plate Belt} - 110 Barra de Tório, 30 Couro Rústico, 5 Água-marinha",
  ["You can get the recipe from the {q:7653::Imperial Plate Belt} quest (Requires {b}level 50{/b}) in Tanaris from {n:14567::Derotain Mudsipper}. You will need 20 Thorium Bar to complete it. Do his {q:7652::A Blue Light Bargain} quest first, it unlocks the Imperial Plate quests."] = "Você consegue a receita com a missão {q:7653::Imperial Plate Belt} (requer {b}nível 50{/b}) em Tanaris, com {n:14567::Derotain Mudsipper}. Você vai precisar de 20 Barras de Tório para completá-la. Faça antes a missão dele {q:7652::A Blue Light Bargain}, que libera as missões de Placas Imperiais.",
  ["{b}The next three recipes are also from the same NPC{/b}, so make sure to bring at least 140 Thorium Bar with you to get all 4 recipes."] = "{b}As próximas três receitas também vêm do mesmo PNJ{/b}, então leve pelo menos 140 Barras de Tório para conseguir as 4 receitas.",
  ["If you have the plans for one of these world drops, you can make it from 240 instead:"] = "Se você tiver os planos de um destes drops do mundo, pode fazê-lo a partir de 240:",
  ["240-255: 27x {s:10005:inv_sword_30:Dazzling Mithril Rapier} - 378 Mithril Bar, 27 Aquamarine, 54 Lesser Moonstone, 54 Moss Agate, 27 Solid Grinding Stone, 54 Mageweave Cloth"] = "240-255: 27x {s:10005:inv_sword_30:Dazzling Mithril Rapier} - 378 Barra de Mithril, 27 Água-marinha, 54 Pedra-da-lua Menor, 54 Ágata Musgo, 27 Pedra de Amolar Sólida, 54 Tecido Mágico",
  ["240-255: 20x {s:10009:inv_hammer_17:Runed Mithril Hammer} - 360 Mithril Bar, 40 Core of Earth, 20 Solid Grinding Stone, 80 Thick Leather"] = "240-255: 20x {s:10009:inv_hammer_17:Runed Mithril Hammer} - 360 Barra de Mithril, 40 Núcleo de Terra, 20 Pedra de Amolar Sólida, 80 Couro Grosso",
  ["240-255: 17x {s:16644:inv_bracer_13:Thorium Bracers} - 204 Thorium Bar, 68 Blue Power Crystal"] = "240-255: 17x {s:16644:inv_bracer_13:Thorium Bracers} - 204 Barra de Tório, 68 Cristal de Poder Azul",
  ["10x {s:9964:ability_rogue_sprint:Mithril Spurs} - 40 Mithril Bar, 30 Solid Grinding Stone (120 Solid Stone)"] = "10x {s:9964:ability_rogue_sprint:Mithril Spurs} - 40 Barra de Mithril, 30 Pedra de Amolar Sólida (120 Pedra Sólida)",
  ["33x {s:9964:ability_rogue_sprint:Mithril Spurs} - 132 Mithril Bar, 99 Solid Grinding Stone (396 Solid Stone)"] = "33x {s:9964:ability_rogue_sprint:Mithril Spurs} - 132 Barra de Mithril, 99 Pedra de Amolar Sólida (396 Pedra Sólida)",
  ["{b}The next three recipes all come from one NPC in Tanaris{/b}, so make sure to bring at least 120 Thorium Bar with you to get all 3 recipes."] = "{b}As próximas três receitas vêm todas de um PNJ em Tanaris{/b}, então leve pelo menos 120 Barras de Tório para conseguir as 3 receitas.",
  ["27x {s:16649:inv_bracer_19:Imperial Plate Bracers} - 540 Thorium Bar, 27 Star Ruby"] = "27x {s:16649:inv_bracer_19:Imperial Plate Bracers} - 540 Barra de Tório, 27 Rubi Estrela",
  ["You get the recipe from the {q:7655::Imperial Plate Bracer} quest (Requires {b}level 50{/b}) in Tanaris from {n:14567::Derotain Mudsipper}. You will need 20 Thorium Bar to complete it."] = "Você consegue a receita com a missão {q:7655::Imperial Plate Bracer} (requer {b}nível 50{/b}) em Tanaris, com {n:14567::Derotain Mudsipper}. Você vai precisar de 20 Barras de Tório para completá-la.",
  ["20x {s:16657:inv_boots_plate_01:Imperial Plate Boots} - 680 Thorium Bar, 20 Star Ruby, 20 Aquamarine"] = "20x {s:16657:inv_boots_plate_01:Imperial Plate Boots} - 680 Barra de Tório, 20 Rubi Estrela, 20 Água-marinha",
  ["You get the recipe from the {q:7654::Imperial Plate Boots} quest, it needs 40 Thorium Bar."] = "Você consegue a receita com a missão {q:7654::Imperial Plate Boots}, que exige 40 Barras de Tório.",
  ["{b}Note:{/b} It wasn't possible to level this far on the beta, so this part only relies on the data I found in the game files. There might be more recipes we haven't discovered yet, but if there is nothing else, these are the only recipes you can use to level until 300."] = "{b}Observação:{/b} Não foi possível subir tanto no beta, então esta parte se baseia apenas nos dados que encontrei nos arquivos do jogo. Pode haver mais receitas que ainda não descobrimos, mas se não houver mais nada, estas são as únicas receitas que você pode usar para subir até 300.",
  ["10x {s:16730:inv_pants_04:Imperial Plate Leggings} - 440 Thorium Bar, 20 Star Ruby"] = "10x {s:16730:inv_pants_04:Imperial Plate Leggings} - 440 Barra de Tório, 20 Rubi Estrela",
  ["You get the recipe from the {q:7658::Imperial Plate Leggings} quest, it needs 60 Thorium Bar."] = "Você consegue a receita com a missão {q:7658::Imperial Plate Leggings}, que exige 60 Barras de Tório.",
  ["This WoW Forever Enchanting leveling guide will show you the fastest and cheapest way to level your Enchanting skill from 1 to 300. You will also find every trainer location and where to train Enchanting past 75, 150 and 225."] = "Este guia de Encantamento do WoW Forever mostra a forma mais rápida e barata de subir sua perícia de Encantamento de 1 a 300. Você também encontra a localização de todos os instrutores e onde treinar Encantamento acima de 75, 150 e 225.",
  ["Enchanting goes well with Tailoring because you don't need a gathering profession for either of them, and you can disenchant the items you made with Tailoring. Below you will find the shopping list, the Enchanting trainers by starting zone and capital city, and the cheapest enchants for every skill range. Forever added a few new low level recipes, so the first 70 points are cheaper than in Classic."] = "Encantamento combina bem com Alfaiataria, porque nenhuma das duas precisa de uma profissão de coleta, e você pode desencantar os itens que fez com Alfaiataria. Abaixo você encontra a lista de compras, os instrutores de Encantamento por zona inicial e capital, e os encantamentos mais baratos para cada faixa de perícia. O Forever adicionou algumas receitas novas de nível baixo, então os primeiros 70 pontos são mais baratos que no Classic.",
  ["An alternative replaces the whole row, so buy the one that is cheaper."] = "Uma alternativa substitui a linha inteira, então compre a que for mais barata.",
  ["Enchanting Trainer Locations"] = "Localização dos instrutores de Encantamento",
  ["Apprentice Enchanting has no level requirement in Forever, so you can learn it on a fresh character."] = "No Forever, Encantamento Aprendiz não tem requisito de nível, então você pode aprendê-lo com um personagem recém-criado.",
  ["Undercity: {n:0:horde:Malcomb Wynn}"] = "Cidade Baixa: {n:0:horde:Malcomb Wynn}",
  ["Thunder Bluff: {n:0:horde:Mot Dawnstrider}"] = "Penhasco do Trovão: {n:0:horde:Mot Dawnstrider}",
  ["{n:0:horde:Pa'zula} in Sen'jin Village"] = "{n:0:horde:Pa'zula} na Vila Sen'jin",
  ["There is no Enchanting trainer in Mulgore, go to {n:0:horde:Mot Dawnstrider} on the middle rise in Thunder Bluff"] = "Não há instrutor de Encantamento em Mulgore; vá até {n:0:horde:Mot Dawnstrider} no platô do meio em Penhasco do Trovão",
  ["{n:0:horde:Vance Undergloom} upstairs in the inn in Brill"] = "{n:0:horde:Vance Undergloom} no andar de cima da estalagem de Montalvo",
  ["{n:0::Eaysaa Brightgust} in Valanaar, {n:0::Nasalanna Windsinger} in Shen'dar Village"] = "{n:0::Eaysaa Brightgust} em Valanaar, {n:0::Nasalanna Windsinger} em Shen'dar Village",
  ["Stormwind City: {n:0:alliance:Betty Quin}"] = "Ventobravo: {n:0:alliance:Betty Quin}",
  ["Ironforge: {n:0:alliance:Thonys Pillarstone}"] = "Altaforja: {n:0:alliance:Thonys Pillarstone}",
  ["There is no Enchanting trainer in Elwynn Forest, go to {n:0:alliance:Betty Quin} in the Mage Quarter in Stormwind City"] = "Não há instrutor de Encantamento na Floresta de Elwynn; vá até {n:0:alliance:Betty Quin} no Distrito dos Magos, em Ventobravo",
  ["There is no Enchanting trainer in Dun Morogh, go to {n:0:alliance:Thonys Pillarstone} at the Great Forge in Ironforge"] = "Não há instrutor de Encantamento em Dun Morogh; vá até {n:0:alliance:Thonys Pillarstone} na Grande Forja, em Altaforja",
  ["{n:0:alliance:Alanna Raveneye} at the Oracle Glade, in the north-west of Teldrassil"] = "{n:0:alliance:Alanna Raveneye} na Clareira do Oráculo, no noroeste de Teldrassil",
  ["You can find every Enchanting trainer for Horde and Alliance on my WoW Forever Enchanting Trainers page."] = "Você encontra todos os instrutores de Encantamento da Horda e da Aliança na minha página de instrutores de Encantamento do WoW Forever.",
  ["Enchanting Macro for Faster Leveling"] = "Macro de Encantamento para subir mais rápido",
  ["I highly recommend using this macro to speed up the leveling process."] = "Recomendo muito usar esta macro para acelerar o processo.",
  ["This macro presses the Create button for you and confirms the prompt that asks if you want to replace the enchant already on the item, without any extra clicks."] = "Esta macro aperta o botão Criar para você e confirma a janela que pergunta se você quer substituir o encantamento que já está no item, sem nenhum clique extra.",
  ["If you have never made a macro, type /m in the chat and press Enter, click New, give it a name and paste these two lines into it."] = "Se você nunca fez uma macro, digite /m no chat e pressione Enter, clique em Nova, dê um nome a ela e cole estas duas linhas.",
  ["How to Use"] = "Como usar",
  ["Place the macro on your action bar"] = "Coloque a macro na sua barra de ações",
  ["Open your Enchanting profession window"] = "Abra a janela da profissão Encantamento",
  ["Select the enchant you want to craft (make sure it's the right one)"] = "Selecione o encantamento que quer criar (verifique se é o correto)",
  ["Put the item you want to enchant into the optional target slot"] = "Coloque o item que quer encantar no espaço de alvo opcional",
  ["Press the macro repeatedly"] = "Aperte a macro repetidamente",
  ["Disenchanting"] = "Desencantar",
  ["You get {s:13262:inv_enchant_disenchant:Disenchant} together with Apprentice Enchanting. In WoW Forever {b}Disenchant is not in your spellbook{/b}, it's in the Enchanting box of the Professions window."] = "Você recebe {s:13262:inv_enchant_disenchant:Disenchant} junto com Encantamento Aprendiz. No WoW Forever, {b}Desencantar não fica no seu grimório{/b}, e sim no quadro de Encantamento da janela de Profissões.",
  ["If you are looking for the disenchanting table, it's in my disenchanting guide, and if you can't find the Disenchant button, the guide shows it with pictures:"] = "Se você procura a tabela de desencantamento, ela está no meu guia de desencantamento, e se não encontrar o botão Desencantar, o guia mostra com imagens:",
  ["Apprentice Enchanting (1-70)"] = "Encantamento Aprendiz (1-70)",
  ["1x {s:7421:inv_staff_goldfeathered_01:Runed Copper Rod} - 1 Copper Rod, 1 Mote of Magic"] = "1x {s:7421:inv_staff_goldfeathered_01:Runed Copper Rod} - 1 Bastão de Cobre, 1 Partícula de Magia",
  ["The {i:6217:inv_misc_flute_01:Copper Rod} and the {i:247786:inv_elemental_mote_mana:Mote of Magic} are sold by the Enchanting Supply vendor near your trainer, don't buy them from the Auction House."] = "O {i:6217:inv_misc_flute_01:Copper Rod} e a {i:247786:inv_elemental_mote_mana:Mote of Magic} são vendidos pelo vendedor de suprimentos de Encantamento perto do seu instrutor; não os compre na casa de leilões.",
  ["{b}If you are leveling in a starting zone with a low level character{/b}, you can buy the Copper Rod from a trade vendor there, but the Mote of Magic is only sold by Enchanting vendors. In the starting zones only the trainers on {b}Zephras Isle{/b} and in {b}Tirisfal Glades{/b} (Brill) sell it, everyone else has to visit the trainer in the capital city, the vendor stands right next to them."] = "{b}Se você estiver subindo em uma zona inicial com um personagem de nível baixo{/b}, pode comprar o Bastão de Cobre com um vendedor de mercadorias de lá, mas a Partícula de Magia só é vendida por vendedores de Encantamento. Nas zonas iniciais, só os instrutores de {b}Zephras Isle{/b} e das {b}Clareiras de Tirisfal{/b} (Montalvo) a vendem; todos os outros precisam visitar o instrutor na capital, o vendedor fica bem ao lado dele.",
  ["18x {s:7418:spell_holy_greaterheal:Enchant Bracer - Inferior Stamina} - 18 Mote of Magic"] = "18x {s:7418:spell_holy_greaterheal:Enchant Bracer - Inferior Stamina} - 18 Partícula de Magia",
  ["Make one of these:"] = "Faça uma destas:",
  ["50x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 50 Strange Dust"] = "50x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 50 Pó Estranho",
  ["50x {s:7428:spell_holy_greaterheal:Enchant Bracer - Minor Deflect} - 50 Lesser Magic Essence"] = "50x {s:7428:spell_holy_greaterheal:Enchant Bracer - Minor Deflect} - 50 Essência Mágica Menor",
  ["A {i:10939:inv_enchant_essencemagiclarge:Greater Magic Essence} turns into 3 Lesser Magic Essence when you right-click it in your bags, so you can buy those too."] = "Uma {i:10939:inv_enchant_essencemagiclarge:Greater Magic Essence} vira 3 Essências Mágicas Menores quando você clica nela com o botão direito nas bolsas, então você também pode comprá-las.",
  ["Journeyman Enchanting (70-150)"] = "Encantamento Artífice (70-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Enchanting. You need {b}Enchanting 50{/b} and {b}level 10{/b}:"] = "Para treinar acima de 75, visite um destes instrutores e aprenda Encantamento Artífice. Você precisa de {b}Encantamento 50{/b} e {b}nível 10{/b}:",
  ["Undercity: {n:0:horde:Lavinia Crowe}"] = "Cidade Baixa: {n:0:horde:Lavinia Crowe}",
  ["Thunder Bluff: {n:0:horde:Teg Dawnstrider}"] = "Penhasco do Trovão: {n:0:horde:Teg Dawnstrider}",
  ["Stormwind City: {n:0:alliance:Lucan Cordell}"] = "Ventobravo: {n:0:alliance:Lucan Cordell}",
  ["Ironforge: {n:0:alliance:Gimble Thistlefuzz}"] = "Altaforja: {n:0:alliance:Gimble Thistlefuzz}",
  ["If you bought Strange Dust pick the {b}Strange Dust{/b} tab, if you bought Lesser Magic Essence pick the {b}Lesser Magic Essence{/b} tab."] = "Se você comprou Pó Estranho, escolha a aba {b}Pó Estranho{/b}; se comprou Essência Mágica Menor, escolha a aba {b}Essência Mágica Menor{/b}.",
  ["Strange Dust"] = "Pó Estranho",
  ["Lesser Magic Essence"] = "Essência Mágica Menor",
  ["49x {s:7426:spell_holy_greaterheal:Enchant Chest - Minor Absorption} - 49 Lesser Magic Essence"] = "49x {s:7426:spell_holy_greaterheal:Enchant Chest - Minor Absorption} - 49 Essência Mágica Menor",
  ["1x {s:7795:inv_staff_01:Runed Silver Rod} - 1 Silver Rod, 3 Strange Dust, 4 Lesser Magic Essence, 1 Shadowgem"] = "1x {s:7795:inv_staff_01:Runed Silver Rod} - 1 Bastão de Prata, 3 Pó Estranho, 4 Essência Mágica Menor, 1 Gema Sombria",
  ["{i:6338:inv_staff_01:Silver Rod} and every other rod in this guide (Golden, Truesilver, Arcanite) is made by Blacksmiths, you can buy them from the Auction House."] = "O {i:6338:inv_staff_01:Silver Rod} e todos os outros bastões deste guia (Dourado, de Veraprata, de Arcanita) são feitos por ferreiros; você pode comprá-los na casa de leilões.",
  ["23x {s:14807:inv_staff_07:Greater Magic Wand} - 23 Simple Wood, 46 Lesser Magic Essence"] = "23x {s:14807:inv_staff_07:Greater Magic Wand} - 23 Madeira Simples, 46 Essência Mágica Menor",
  ["37x {s:7793:spell_holy_greaterheal:Enchant 2H Weapon - Lesser Intellect} - 148 Lesser Magic Essence"] = "37x {s:7793:spell_holy_greaterheal:Enchant 2H Weapon - Lesser Intellect} - 148 Essência Mágica Menor",
  ["{i:6349:inv_misc_note_01:Formula: Enchant 2H Weapon - Lesser Intellect} is sold by these vendors:"] = "{i:6349:inv_misc_note_01:Formula: Enchant 2H Weapon - Lesser Intellect} é vendida por estes vendedores:",
  ["{n:0:horde:Kithas} in Orgrimmar"] = "{n:0:horde:Kithas} em Orgrimmar",
  ["{n:0:horde:Nata Dawnstrider} in Thunder Bluff"] = "{n:0:horde:Nata Dawnstrider} em Penhasco do Trovão",
  ["{n:0:horde:Leo Sarn} in Silverpine Forest"] = "{n:0:horde:Leo Sarn} na Floresta de Pinhaprata",
  ["{n:0:alliance:Tilli Thistlefuzz} in Ironforge"] = "{n:0:alliance:Tilli Thistlefuzz} em Altaforja",
  ["Buy {i:20752:inv_misc_note_01:Formula: Minor Mana Oil} and {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} from them too, you will need them at 150 and 200."] = "Compre também {i:20752:inv_misc_note_01:Formula: Minor Mana Oil} e {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} com eles; você vai precisar delas em 150 e 200.",
  ["If you don't want to get the formula, make this:"] = "Se não quiser pegar a fórmula, faça isto:",
  ["25x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 100 Strange Dust"] = "25x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 100 Pó Estranho",
  ["23x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 23 Strange Dust"] = "23x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 23 Pó Estranho",
  ["15x {s:7457:spell_holy_greaterheal:Enchant Bracer - Minor Stamina} - 30 Strange Dust"] = "15x {s:7457:spell_holy_greaterheal:Enchant Bracer - Minor Stamina} - 30 Pó Estranho",
  ["9x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 18 Strange Dust"] = "9x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 18 Pó Estranho",
  ["32x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 64 Strange Dust"] = "32x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 64 Pó Estranho",
  ["20x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 80 Strange Dust"] = "20x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 80 Pó Estranho",
  ["If 20 Soul Dust cost less than 80 Strange Dust, make this:"] = "Se 20 Pós de Alma custarem menos que 80 Pós Estranhos, faça isto:",
  ["20x {s:13501:spell_holy_greaterheal:Enchant Bracer - Lesser Stamina} - 20 Soul Dust."] = "20x {s:13501:spell_holy_greaterheal:Enchant Bracer - Lesser Stamina} - 20 Pó de Alma.",
  ["Expert Enchanting (150-225)"] = "Encantamento Especialista (150-225)",
  ["To train past 150, visit one of these trainers and learn Expert Enchanting. You need {b}Enchanting 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Para treinar acima de 150, visite um destes instrutores e aprenda Encantamento Especialista. Você precisa de {b}Encantamento 125{/b} e {b}nível 20{/b}, e custa 50 pratas.",
  ["There is only one Expert Enchanting trainer for each faction. {n:0:horde:Hgarth} in Stonetalon Mountains at Sun Rock Retreat is the Horde trainer, he is up on the hill above the village. {n:0:alliance:Kitta Firewind} in Elwynn Forest is the Alliance trainer, she is at the top of the Tower of Azora."] = "Há apenas um instrutor de Encantamento Especialista por facção. {n:0:horde:Hgarth}, no Retiro da Rocha do Sol na Cordilheira das Torres de Pedra, é o instrutor da Horda; ele fica no alto da colina acima da vila. {n:0:alliance:Kitta Firewind}, na Floresta de Elwynn, é a instrutora da Aliança; ela fica no topo da Torre de Azora.",
  ["1x {s:13628:inv_staff_10:Runed Golden Rod} - 1 Golden Rod, 1 Iridescent Pearl, 1 Greater Astral Essence, 1 Soul Dust"] = "1x {s:13628:inv_staff_10:Runed Golden Rod} - 1 Bastão Dourado, 1 Pérola Iridescente, 1 Essência Astral Maior, 1 Pó de Alma",
  ["16x {s:25125:inv_potion_98:Minor Mana Oil} - 16 Soul Dust, 32 Maple Seed, 16 Leaded Vial"] = "16x {s:25125:inv_potion_98:Minor Mana Oil} - 16 Pó de Alma, 32 Semente de Bordo, 16 Frasco com Chumbo",
  ["{i:20752:inv_misc_note_01:Formula: Minor Mana Oil} is sold by these vendors:"] = "{i:20752:inv_misc_note_01:Formula: Minor Mana Oil} é vendida por estes vendedores:",
  ["{n:0:horde:Thaddeus Webb} in Undercity"] = "{n:0:horde:Thaddeus Webb} na Cidade Baixa",
  ["{n:0:alliance:Vaean} in Darnassus"] = "{n:0:alliance:Vaean} em Darnassus",
  ["{n:0:alliance:Jessara Cordell} in Stormwind City"] = "{n:0:alliance:Jessara Cordell} em Ventobravo",
  ["Buy {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} from them too, you will need it at 200."] = "Compre também {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} com eles; você vai precisar dela em 200.",
  ["{i:17034:inv_misc_food_02:Maple Seed} is sold by Reagent vendors and {i:3372:inv_potion_85:Leaded Vial} by Alchemy Supply vendors."] = "{i:17034:inv_misc_food_02:Maple Seed} é vendida pelos vendedores de reagentes e {i:3372:inv_potion_85:Leaded Vial} pelos vendedores de suprimentos de Alquimia.",
  ["47x {s:13637:spell_holy_greaterheal:Enchant Boots - Lesser Agility} - 47 Soul Dust"] = "47x {s:13637:spell_holy_greaterheal:Enchant Boots - Lesser Agility} - 47 Pó de Alma",
  ["If 2 Vision Dust cost less than 3 Soul Dust, stop the boots at 185 and make this until 200:"] = "Se 2 Pós de Visão custarem menos que 3 Pós de Alma, pare as botas em 185 e faça isto até 200:",
  ["15x {s:13661:spell_holy_greaterheal:Enchant Bracer - Strength} - 15 Vision Dust."] = "15x {s:13661:spell_holy_greaterheal:Enchant Bracer - Strength} - 15 Pó de Visão.",
  ["1x {s:13702:inv_staff_11:Runed Truesilver Rod} - 1 Truesilver Rod, 1 Black Pearl, 1 Greater Mystic Essence, 1 Vision Dust"] = "1x {s:13702:inv_staff_11:Runed Truesilver Rod} - 1 Bastão de Veraprata, 1 Pérola Negra, 1 Essência Mística Maior, 1 Pó de Visão",
  ["25x {s:25126:inv_potion_103:Lesser Wizard Oil} - 25 Vision Dust, 50 Stranglethorn Seed, 25 Leaded Vial"] = "25x {s:25126:inv_potion_103:Lesser Wizard Oil} - 25 Pó de Visão, 50 Semente do Espinhaço, 25 Frasco com Chumbo",
  ["If you didn't buy {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} yet, the vendors are listed at the 151-165 step above."] = "Se você ainda não comprou {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}, os vendedores estão listados na etapa 151-165 acima.",
  ["{i:17035:inv_misc_food_02:Stranglethorn Seed} is sold by Reagent vendors and {i:3372:inv_potion_85:Leaded Vial} by Alchemy Supply vendors."] = "{i:17035:inv_misc_food_02:Stranglethorn Seed} é vendida pelos vendedores de reagentes e {i:3372:inv_potion_85:Leaded Vial} pelos vendedores de suprimentos de Alquimia.",
  ["5x {s:13746:spell_holy_greaterheal:Enchant Cloak - Greater Defense} - 5 Vision Dust"] = "5x {s:13746:spell_holy_greaterheal:Enchant Cloak - Greater Defense} - 5 Pó de Visão",
  ["Artisan Enchanting (225-300)"] = "Encantamento Artesão (225-300)",
  ["The Expert Enchanting trainers only teach you up to 225. To train Enchanting past 225 you need {b}level 35{/b} and {b}Enchanting 200{/b}, then learn Artisan Enchanting from Annora in Uldaman (I explain below how to find her). {b}She is the only trainer who teaches Artisan Enchanting.{/b}"] = "Os instrutores de Encantamento Especialista só ensinam até 225. Para treinar Encantamento acima de 225 você precisa de {b}nível 35{/b} e {b}Encantamento 200{/b}; depois aprenda Encantamento Artesão com Annora em Uldaman (explico abaixo como encontrá-la). {b}Ela é a única instrutora que ensina Encantamento Artesão.{/b}",
  ["There are a few recipes only Annora teaches, {b}so bring enough gold to learn every recipe and enough materials to reach Enchanting 250{/b}, otherwise you have to go back to Uldaman for the higher recipes. Around 50 {i:11137:inv_enchant_dustvision:Vision Dust} gets you to 250."] = "Há algumas receitas que só Annora ensina, {b}então leve ouro suficiente para aprender todas as receitas e materiais suficientes para chegar a Encantamento 250{/b}; caso contrário, você terá que voltar a Uldaman para as receitas mais altas. Cerca de 50 {i:11137:inv_enchant_dustvision:Vision Dust} levam você até 250.",
  ["How to enter Uldaman"] = "Como entrar em Uldaman",
  ["Uldaman is in the Badlands and it has two entrances, use the back entrance. You can't solo it at level 35, so go with a party or ask a level 60 to help."] = "Uldaman fica nos Ermos e tem duas entradas; use a entrada dos fundos. Não dá para fazer sozinho no nível 35, então vá com um grupo ou peça ajuda a alguém de nível 60.",
  ["How to find Annora"] = "Como encontrar Annora",
  ["Annora only spawns once you {b}kill every mob in the area she is in!{/b}"] = "Annora só aparece depois que você {b}mata todos os monstros da área em que ela está!{/b}",
  ["{b}Don't forget to learn everything from Annora before you leave Uldaman!{/b} The recipes from 230 up are taught nowhere else."] = "{b}Não se esqueça de aprender tudo com Annora antes de sair de Uldaman!{/b} As receitas a partir de 230 não são ensinadas em nenhum outro lugar.",
  ["Recipe"] = "Receita",
  ["Skill"] = "Perícia",
  ["Cost"] = "Custo",
  ["{b}Artisan Enchanting{/b}"] = "{b}Encantamento Artesão{/b}",
  ["37x {s:13815:spell_holy_greaterheal:Enchant Gloves - Agility} - 37 Vision Dust"] = "37x {s:13815:spell_holy_greaterheal:Enchant Gloves - Agility} - 37 Pó de Visão",
  ["20x {s:25127:inv_potion_99:Lesser Mana Oil} - 20 Dream Dust, 20 Purple Lotus, 20 Crystal Vial"] = "20x {s:25127:inv_potion_99:Lesser Mana Oil} - 20 Pó Onírico, 20 Lótus Roxo, 20 Frasco de Cristal",
  ["{i:20754:inv_misc_note_01:Formula: Lesser Mana Oil} is sold by {n:0::Kania} in Silithus, she is upstairs in the inn. {i:8925:inv_potion_86:Crystal Vial} is sold by {n:0::Mishta} in Silithus or any Alchemy Supply vendor."] = "{i:20754:inv_misc_note_01:Formula: Lesser Mana Oil} é vendida por {n:0::Kania} em Silithus, no andar de cima da estalagem. {i:8925:inv_potion_86:Crystal Vial} é vendido por {n:0::Mishta} em Silithus ou por qualquer vendedor de suprimentos de Alquimia.",
  ["If you don't have Purple Lotus, make {s:13939:spell_holy_greaterheal:Enchant Bracer - Greater Strength} instead (1 Dream Dust, 2 Lesser Nether Essence each), Annora teaches it."] = "Se você não tiver Lótus Roxo, faça {s:13939:spell_holy_greaterheal:Enchant Bracer - Greater Strength} no lugar (1 Pó Onírico e 2 Essências Etéreas Menores cada); Annora ensina essa receita.",
  ["40x {s:20017:spell_holy_greaterheal:Enchant Shield - Greater Stamina} - 240 Dream Dust"] = "40x {s:20017:spell_holy_greaterheal:Enchant Shield - Greater Stamina} - 240 Pó Onírico",
  ["{i:16217:inv_misc_note_01:Formula: Enchant Shield - Greater Stamina} is sold by {n:0:horde:Daniel Bartlett} in Undercity and {n:0:alliance:Mythrin'dir} in Darnassus. It's bind on pickup, so don't buy it on an alt."] = "{i:16217:inv_misc_note_01:Formula: Enchant Shield - Greater Stamina} é vendida por {n:0:horde:Daniel Bartlett} na Cidade Baixa e por {n:0:alliance:Mythrin'dir} em Darnassus. É vinculada ao ser coletada, então não a compre com um alter.",
  ["From 290 you can make the Runed Arcanite Rod, see the next step."] = "A partir de 290 você pode fazer o Bastão de Arcanita Rúnico; veja a próxima etapa.",
  ["1x {s:20051:inv_wand_09:Runed Arcanite Rod} - 1 Arcanite Rod, 1 Golden Pearl, 10 Illusion Dust, 4 Greater Eternal Essence, 4 Small Brilliant Shard, 2 Large Brilliant Shard"] = "1x {s:20051:inv_wand_09:Runed Arcanite Rod} - 1 Bastão de Arcanita, 1 Pérola Dourada, 10 Pó de Ilusão, 4 Essência Eterna Maior, 4 Estilhaço Brilhante Pequeno, 2 Estilhaço Brilhante Grande",
  ["{i:16243:inv_misc_note_01:Formula: Runed Arcanite Rod} is sold by {n:0::Lorelae Wintersong} in Moonglade at Nighthaven."] = "{i:16243:inv_misc_note_01:Formula: Runed Arcanite Rod} é vendida por {n:0::Lorelae Wintersong} na Clareira da Lua, em Refúgio Noturno.",
  ["{b}You need this rod for some recipes from 290 and for most recipes at 300{/b}, Crusader for example. You can make it from 290, but if you don't need it yet, you can make it later and make one more Shield for the last point instead."] = "{b}Você precisa deste bastão para algumas receitas a partir de 290 e para a maioria das receitas em 300{/b}, Cruzado por exemplo. Você pode fazê-lo a partir de 290, mas se ainda não precisar dele, pode fazê-lo depois e criar mais um Escudo para o último ponto.",
  ["This WoW Forever Engineering leveling guide will show you the fastest and cheapest way to level your Engineering skill from 1 to 300. You will also find every trainer location and where to train Engineering past 75, 150 and 225."] = "Este guia de Engenharia do WoW Forever mostra a forma mais rápida e barata de subir sua perícia de Engenharia de 1 a 300. Você também encontra a localização de todos os instrutores e onde treinar Engenharia acima de 75, 150 e 225.",
  ["Engineering is best combined with Mining, because almost everything you make needs stone and bars, and you can mine both. If you don't have Mining, you have to buy everything from the Auction House. Below you will find the shopping list, the Engineering trainers by starting zone and capital city, and the cheapest recipes for every skill range."] = "Engenharia combina melhor com Mineração, porque quase tudo o que você faz precisa de pedras e barras, e você pode minerar as duas coisas. Se não tiver Mineração, vai ter que comprar tudo na casa de leilões. Abaixo você encontra a lista de compras, os instrutores de Engenharia por zona inicial e capital, e as receitas mais baratas para cada faixa de perícia.",
  ["Engineering Trainer Locations"] = "Localização dos instrutores de Engenharia",
  ["Apprentice Engineering has no level requirement in Forever, so you can learn it on a fresh character."] = "No Forever, Engenharia Aprendiz não tem requisito de nível, então você pode aprendê-la com um personagem recém-criado.",
  ["There is no Engineering trainer in Thunder Bluff and Darnassus, the other four capitals have one. You can also ask a guard, then it will be marked with a red flag on your map."] = "Não há instrutor de Engenharia em Penhasco do Trovão nem em Darnassus; as outras quatro capitais têm um. Você também pode perguntar a um guarda, e ele será marcado com uma bandeira vermelha no seu mapa.",
  ["Undercity: {n:0:horde:Graham Van Talen}"] = "Cidade Baixa: {n:0:horde:Graham Van Talen}",
  ["{n:0:horde:Mukdrak} in Razor Hill, near the forge next to the road to Orgrimmar"] = "{n:0:horde:Mukdrak} no Monte da Navalha, perto da forja ao lado da estrada para Orgrimmar",
  ["{n:0::Twizwick Sprocketgrind} on the plateau above the Venture Co. Mine, hard to reach at low level. There is no anvil near him and nobody there sells the Blacksmith Hammer, so it's probably best to go to {n:0:horde:Thund} in Orgrimmar instead."] = "{n:0::Twizwick Sprocketgrind} no platô acima da Mina da Empreendimentos S.A., difícil de alcançar em nível baixo. Não há bigorna perto dele e ninguém ali vende o Martelo de Ferreiro, então provavelmente é melhor ir até {n:0:horde:Thund} em Orgrimmar.",
  ["There is no Engineering trainer in Tirisfal Glades, go to {n:0:horde:Graham Van Talen} in the Rogues' Quarter in Undercity"] = "Não há instrutor de Engenharia nas Clareiras de Tirisfal; vá até {n:0:horde:Graham Van Talen} no Bairro dos Gatunos, na Cidade Baixa",
  ["{n:0::Strange Hermit} in Shadowgale Forest"] = "{n:0::Strange Hermit} em Shadowgale Forest",
  ["Stormwind City: {n:0:alliance:Sprite Jumpsprocket}"] = "Ventobravo: {n:0:alliance:Sprite Jumpsprocket}",
  ["Ironforge: {n:0:alliance:Jemma Quikswitch}"] = "Altaforja: {n:0:alliance:Jemma Quikswitch}",
  ["There is no Engineering trainer in Elwynn Forest, go to {n:0:alliance:Sprite Jumpsprocket} in the Dwarven District in Stormwind City"] = "Não há instrutor de Engenharia na Floresta de Elwynn; vá até {n:0:alliance:Sprite Jumpsprocket} no Distrito dos Anões, em Ventobravo",
  ["{n:0:alliance:Bronk Guzzlegear} at Steelgrill's Depot"] = "{n:0:alliance:Bronk Guzzlegear} no Depósito do Grelhaço",
  ["There is no Engineering trainer in Teldrassil or Darnassus, the closest one is {n:0:alliance:Jenna Lemkenilli} in Auberdine in Darkshore"] = "Não há instrutor de Engenharia em Teldrassil nem em Darnassus; o mais próximo é {n:0:alliance:Jenna Lemkenilli} em Auberdine, na Costa Negra",
  ["You can find every Engineering trainer for Horde and Alliance on my WoW Forever Engineering Trainers page."] = "Você encontra todos os instrutores de Engenharia da Horda e da Aliança na minha página de instrutores de Engenharia do WoW Forever.",
  ["Apprentice Engineering (1-50)"] = "Engenharia Aprendiz (1-50)",
  ["Buy a {i:5956:inv_hammer_20:Blacksmith Hammer}, most recipes need it. {b}Most trainers{/b} have a Blacksmithing or Engineering Supply vendor nearby that sells it, {b}except{/b} the trainers in Dun Morogh and on Zephras Isle. In Dun Morogh buy it in Kharanos from {n:0:alliance:Thrawn Boltar}, on Zephras Isle in Shen'dar Village from {n:0::Aedi Thriceforged}."] = "Compre um {i:5956:inv_hammer_20:Blacksmith Hammer}; a maioria das receitas precisa dele. {b}A maioria dos instrutores{/b} tem por perto um vendedor de suprimentos de Ferraria ou de Engenharia que o vende, {b}exceto{/b} os instrutores de Dun Morogh e de Zephras Isle. Em Dun Morogh, compre-o em Kharanos com {n:0:alliance:Thrawn Boltar}; em Zephras Isle, em Shen'dar Village com {n:0::Aedi Thriceforged}.",
  ["The {b}Gnome{/b} racial changed in Forever. Instead of +15 Engineering skill, Engineering Specialization now makes your devices fail or backfire 20% less often, so Gnomes level Engineering exactly like everyone else."] = "O racial dos {b}Gnomos{/b} mudou no Forever. Em vez de +15 na perícia de Engenharia, Especialização em Engenharia agora faz seus dispositivos falharem ou saírem pela culatra 20% menos vezes, então os Gnomos sobem Engenharia exatamente como todo mundo.",
  ["66x {s:3918:inv_misc_dust_01:Rough Blasting Powder} - 66 Rough Stone"] = "66x {s:3918:inv_misc_dust_01:Rough Blasting Powder} - 66 Pedra Bruta",
  ["Keep all of them, you need 66 for the bombs at 51."] = "Guarde todas; você vai precisar de 66 para as bombas em 51.",
  ["33x {s:3922:inv_misc_gear_06:Handful of Copper Bolts} - 33 Copper Bar"] = "33x {s:3922:inv_misc_gear_06:Handful of Copper Bolts} - 33 Barra de Cobre",
  ["Keep these too, you will need all 33 for the bombs."] = "Guarde estes também; você vai precisar de todos os 33 para as bombas.",
  ["1x {s:7430:inv_misc_wrench_01:Arclight Spanner} - 6 Copper Bar"] = "1x {s:7430:inv_misc_wrench_01:Arclight Spanner} - 6 Barra de Cobre",
  ["You will use this to craft Engineering recipes, so keep it."] = "Você vai usar isto para criar receitas de Engenharia, então guarde.",
  ["Journeyman Engineering (50-150)"] = "Engenharia Artífice (50-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Engineering. You need {b}Engineering 50{/b} and {b}level 10{/b}:"] = "Para treinar acima de 75, visite um destes instrutores e aprenda Engenharia Artífice. Você precisa de {b}Engenharia 50{/b} e {b}nível 10{/b}:",
  ["Undercity: {n:0:horde:Franklin Lloyd}"] = "Cidade Baixa: {n:0:horde:Franklin Lloyd}",
  ["Stormwind City: {n:0:alliance:Lilliam Sparkspindle}"] = "Ventobravo: {n:0:alliance:Lilliam Sparkspindle}",
  ["Ironforge: {n:0:alliance:Trixie Quikswitch}"] = "Altaforja: {n:0:alliance:Trixie Quikswitch}",
  ["Duskwood: {n:0:alliance:Finbus Geargrind}"] = "Bosque do Corvo: {n:0:alliance:Finbus Geargrind}",
  ["33x {s:3923:inv_misc_bomb_09:Rough Copper Bomb} - 33 Copper Bar, 33 Handful of Copper Bolts, 66 Rough Blasting Powder, 33 Linen Cloth"] = "33x {s:3923:inv_misc_bomb_09:Rough Copper Bomb} - 33 Barra de Cobre, 33 Punhado de Parafusos de Cobre, 66 Pólvora Bruta, 33 Tecido de Linho",
  ["{b}It's possible that you reach further than 75 with these{/b}, so it's best not to afk craft them unless you already learned Journeyman Engineering. Either make sure you learn it first, or just don't afk craft them. (Depends on luck, sometimes you don't even reach 75.)"] = "{b}É possível que você passe de 75 com estas{/b}, então é melhor não criá-las em modo AFK, a menos que já tenha aprendido Engenharia Artífice. Garanta que aprendeu antes, ou simplesmente não crie em modo AFK. (Depende da sorte; às vezes você nem chega a 75.)",
  ["60x {s:3929:inv_misc_dust_02:Coarse Blasting Powder} - 60 Coarse Stone"] = "60x {s:3929:inv_misc_dust_02:Coarse Blasting Powder} - 60 Pedra Grosseira",
  ["Keep them, you will need all 60 for the dynamite at 90."] = "Guarde-as; você vai precisar de todas as 60 para a dinamite em 90.",
  ["20x {s:3931:inv_misc_bomb_06:Coarse Dynamite} - 60 Coarse Blasting Powder, 20 Linen Cloth"] = "20x {s:3931:inv_misc_bomb_06:Coarse Dynamite} - 60 Pólvora Grosseira, 20 Tecido de Linho",
  ["5x {s:3973:inv_ingot_04:Silver Contact} - 5 Silver Bar"] = "5x {s:3973:inv_ingot_04:Silver Contact} - 5 Barra de Prata",
  ["If Silver Bar is expensive, make this instead:"] = "Se a Barra de Prata estiver cara, faça isto no lugar:",
  ["5x {s:3934:inv_helmet_47:Flying Tiger Goggles} - 30 Light Leather, 10 Tigerseye."] = "5x {s:3934:inv_helmet_47:Flying Tiger Goggles} - 30 Couro Leve, 10 Olho-de-tigre.",
  ["25x {s:3938:inv_gizmo_pipe_01:Bronze Tube} - 50 Bronze Bar, 25 Weak Flux"] = "25x {s:3938:inv_gizmo_pipe_01:Bronze Tube} - 50 Barra de Bronze, 25 Fundente Fraco",
  ["Keep 10 of them, you will need them at 125."] = "Guarde 10 deles; você vai precisar deles em 125.",
  ["{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} is sold by Engineering Supply vendors near your trainer."] = "{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} é vendido pelos vendedores de suprimentos de Engenharia perto do seu instrutor.",
  ["If you end up a few points short of 125, don't make more tubes, just start the scopes."] = "Se ficar alguns pontos abaixo de 125, não faça mais tubos; comece logo as lunetas.",
  ["10x {s:3978:inv_misc_spyglass_02:Standard Scope} - 10 Bronze Tube, 10 Moss Agate"] = "10x {s:3978:inv_misc_spyglass_02:Standard Scope} - 10 Tubo de Bronze, 10 Ágata Musgo",
  ["Start making {s:3945:inv_misc_dust_06:Heavy Blasting Powder} instead if you don't have any Moss Agate, or it's really expensive."] = "Comece a fazer {s:3945:inv_misc_dust_06:Heavy Blasting Powder} no lugar se não tiver nenhuma Ágata Musgo ou se ela estiver muito cara.",
  ["Make both of these:"] = "Faça os dois:",
  ["30x {s:3945:inv_misc_dust_06:Heavy Blasting Powder} - 30 Heavy Stone"] = "30x {s:3945:inv_misc_dust_06:Heavy Blasting Powder} - 30 Pedra Pesada",
  ["15x {s:3942:inv_gizmo_02:Whirring Bronze Gizmo} - 30 Bronze Bar, 15 Wool Cloth"] = "15x {s:3942:inv_gizmo_02:Whirring Bronze Gizmo} - 30 Barra de Bronze, 15 Tecido de Lã",
  ["{b}Make sure to make them in the same order.{/b} You need both for the sheep at 160, so make them now and you should reach 150 with them."] = "{b}Faça-os nesta mesma ordem.{/b} Você precisa dos dois para as ovelhas em 160, então faça-os agora; você deve chegar a 150 com eles.",
  ["Expert Engineering (150-200)"] = "Engenharia Especialista (150-200)",
  ["To train past 150, visit {n:0:horde:Roxxik} in Orgrimmar (Horde) or {n:0:alliance:Springspindle Fizzlegear} in Ironforge (Alliance) and learn Expert Engineering. You need {b}Engineering 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Para treinar acima de 150, visite {n:0:horde:Roxxik} em Orgrimmar (Horda) ou {n:0:alliance:Springspindle Fizzlegear} em Altaforja (Aliança) e aprenda Engenharia Especialista. Você precisa de {b}Engenharia 125{/b} e {b}nível 20{/b}, e custa 50 pratas.",
  ["15x {s:3953:inv_gizmo_bronzeframework_01:Bronze Framework} - 30 Bronze Bar, 15 Medium Leather, 15 Wool Cloth"] = "15x {s:3953:inv_gizmo_bronzeframework_01:Bronze Framework} - 30 Barra de Bronze, 15 Couro Médio, 15 Tecido de Lã",
  ["Keep these too, you will need all 15 for the sheep."] = "Guarde estas também; você vai precisar de todas as 15 para as ovelhas.",
  ["The 15 will probably take you past 160, that's fine."] = "As 15 provavelmente vão levar você além de 160, não tem problema.",
  ["15x {s:3955:spell_nature_polymorph:Explosive Sheep} - 30 Heavy Blasting Powder, 15 Whirring Bronze Gizmo, 15 Bronze Framework, 30 Wool Cloth"] = "15x {s:3955:spell_nature_polymorph:Explosive Sheep} - 30 Pólvora Pesada, 15 Engenhoca de Bronze Zumbidora, 15 Estrutura de Bronze, 30 Tecido de Lã",
  ["Keep 5 of them, you might need them if you choose Goblin Engineering at 200."] = "Guarde 5 delas; talvez você precise delas se escolher Engenharia Goblin em 200.",
  ["60x {s:12585:inv_misc_powder_black:Solid Blasting Powder} - 120 Solid Stone"] = "60x {s:12585:inv_misc_powder_black:Solid Blasting Powder} - 120 Pedra Sólida",
  ["Save these, you will need them later."] = "Guarde-as; você vai precisar delas mais tarde.",
  ["1x {s:12590:inv_misc_screwdriver_02:Gyromatic Micro-Adjustor} - 4 Steel Bar"] = "1x {s:12590:inv_misc_screwdriver_02:Gyromatic Micro-Adjustor} - 4 Barra de Aço",
  ["Keep this, you will need it to craft some of the Engineering recipes."] = "Guarde isto; você vai precisar dele para criar algumas receitas de Engenharia.",
  ["If you were unlucky with the skill points and didn't reach 195, craft a few {s:3962:inv_misc_bomb_08:Iron Grenade} or any other recipe that gives skill points."] = "Se você teve azar com os pontos de perícia e não chegou a 195, crie algumas {s:3962:inv_misc_bomb_08:Iron Grenade} ou qualquer outra receita que dê pontos de perícia.",
  ["6x {s:12589:inv_musket_01:Mithril Tube} - 18 Mithril Bar"] = "6x {s:12589:inv_musket_01:Mithril Tube} - 18 Barra de Mithril",
  ["Keep all 6, you might need them if you choose Gnomish Engineering at 200."] = "Guarde os 6; talvez você precise deles se escolher Engenharia Gnômica em 200.",
  ["Engineering Specializations"] = "Especializações de Engenharia",
  ["At {b}Engineering 200{/b} and {b}level 30{/b}, you can specialize in Gnomish or Goblin Engineering. Some items require a specific specialization to use, while other items are crafted by one specialization but are usable by any engineer. Fortunately, most recipes that are crafted by one specialization can be used by both."] = "Com {b}Engenharia 200{/b} e {b}nível 30{/b}, você pode se especializar em Engenharia Gnômica ou Goblin. Alguns itens exigem uma especialização específica para serem usados, enquanto outros são criados por uma especialização mas podem ser usados por qualquer engenheiro. Felizmente, a maioria das receitas criadas por uma especialização pode ser usada pelas duas.",
  ["For information on how to choose a specialization, please see my separate guide:"] = "Para saber como escolher uma especialização, veja meu guia separado:",
  ["Artisan Engineering (200-300)"] = "Engenharia Artesão (200-300)",
  ["To train Engineering past 225 you need {b}Engineering 200{/b} and {b}level 35{/b}, then learn Artisan Engineering from {n:0::Buzzek Bracketswing} in Tanaris at Gadgetzan, he is right outside the inn near the mailbox. He also teaches the recipes above 200, so go there as soon as you reach 200."] = "Para treinar Engenharia acima de 225 você precisa de {b}Engenharia 200{/b} e {b}nível 35{/b}; depois aprenda Engenharia Artesão com {n:0::Buzzek Bracketswing} em Geringontzan, em Tanaris. Ele fica logo do lado de fora da estalagem, perto da caixa de correio. Ele também ensina as receitas acima de 200, então vá até lá assim que chegar a 200.",
  ["20x {s:12591:inv_battery_01:Unstable Trigger} - 20 Mithril Bar, 20 Mageweave Cloth, 20 Solid Blasting Powder"] = "20x {s:12591:inv_battery_01:Unstable Trigger} - 20 Barra de Mithril, 20 Tecido Mágico, 20 Pólvora Sólida",
  ["Keep them, you will need all 20 for the bombs at 238."] = "Guarde-os; você vai precisar de todos os 20 para as bombas em 238.",
  ["40x {s:12599:inv_gizmo_mithrilcasing_01:Mithril Casing} - 120 Mithril Bar"] = "40x {s:12599:inv_gizmo_mithrilcasing_01:Mithril Casing} - 120 Barra de Mithril",
  ["Keep these too, you will need 40 for the bombs."] = "Guarde estes também; você vai precisar de 40 para as bombas.",
  ["20x {s:12619:inv_misc_bomb_07:Hi-Explosive Bomb} - 40 Mithril Casing, 20 Unstable Trigger, 40 Solid Blasting Powder"] = "20x {s:12619:inv_misc_bomb_07:Hi-Explosive Bomb} - 40 Invólucro de Mithril, 20 Gatilho Instável, 40 Pólvora Sólida",
  ["44x {s:19788:inv_misc_ammo_gunpowder_01:Dense Blasting Powder} - 88 Dense Stone"] = "44x {s:19788:inv_misc_ammo_gunpowder_01:Dense Blasting Powder} - 88 Pedra Densa",
  ["35x {s:19791:inv_gizmo_04:Thorium Widget} - 105 Thorium Bar, 35 Runecloth"] = "35x {s:19791:inv_gizmo_04:Thorium Widget} - 105 Barra de Tório, 35 Tecido Rúnico",
  ["{i:16042:inv_scroll_03:Schematic: Thorium Widget} is sold by {n:0:horde:Sovik} in Orgrimmar and {n:0:alliance:Gearcutter Cogspinner} in Ironforge."] = "{i:16042:inv_scroll_03:Schematic: Thorium Widget} é vendido por {n:0:horde:Sovik} em Orgrimmar e por {n:0:alliance:Gearcutter Cogspinner} em Altaforja.",
  ["20x {s:19795:inv_gizmo_pipe_04:Thorium Tube} - 120 Thorium Bar"] = "20x {s:19795:inv_gizmo_pipe_04:Thorium Tube} - 120 Barra de Tório",
  ["{i:16047:inv_scroll_03:Schematic: Thorium Tube} is sold by {n:0::Xizzer Fizzbolt} in Winterspring at Everlook, in the first building on the right after the gate. It's bind on pickup in Forever, so buy it with the character that levels Engineering."] = "{i:16047:inv_scroll_03:Schematic: Thorium Tube} é vendido por {n:0::Xizzer Fizzbolt} em Visteterna, em Hibérnia, no primeiro prédio à direita depois do portão. No Forever ele é vinculado ao ser coletado, então compre-o com o personagem que está subindo Engenharia.",
  ["This WoW Forever Leatherworking leveling guide will show you the fastest and cheapest way to level your Leatherworking skill from 1 to 300. You will also find every trainer location and where to train Leatherworking past 75, 150 and 225."] = "Este guia de Couraria do WoW Forever mostra a forma mais rápida e barata de subir sua perícia de Couraria de 1 a 300. Você também encontra a localização de todos os instrutores e onde treinar Couraria acima de 75, 150 e 225.",
  ["Below you will find the full shopping list, the Leatherworking trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Leatherworking is best combined with Skinning because leather is most of the cost, but you can also buy everything in the guide from the Auction House."] = "Abaixo você encontra a lista de compras completa, os instrutores de Couraria por zona inicial e capital, e as receitas mais baratas para cada faixa de perícia, de Aprendiz a Artesão. Couraria combina melhor com Esfolamento, porque o couro é a maior parte do custo, mas você também pode comprar tudo do guia na casa de leilões.",
  ["When a recipe is yellow or green, a craft doesn't always give you a skill point, so nobody can tell exactly how many materials you will need. That's why the counts that depend a lot on luck are a range. {b}With the bigger number 9 out of 10 players have enough, with the smaller one it's 50/50.{/b} If you buy the smaller number, be ready to buy more later."] = "Quando uma receita está amarela ou verde, nem toda criação dá um ponto de perícia, então ninguém sabe dizer exatamente quantos materiais você vai precisar. Por isso as quantidades que dependem muito da sorte aparecem como uma faixa. {b}Com o número maior, 9 em cada 10 jogadores têm o suficiente; com o menor, a chance é de 50%.{/b} Se comprar o número menor, esteja pronto para comprar mais depois.",
  ["Leatherworking Trainer Locations"] = "Localização dos instrutores de Couraria",
  ["Apprentice Leatherworking has no level requirement in Forever, so you can learn it on a fresh character."] = "No Forever, Couraria Aprendiz não tem requisito de nível, então você pode aprendê-la com um personagem recém-criado.",
  ["Undercity: {n:0:horde:Dan Golthas}"] = "Cidade Baixa: {n:0:horde:Dan Golthas}",
  ["Thunder Bluff: {n:0:horde:Mak}"] = "Penhasco do Trovão: {n:0:horde:Mak}",
  ["There is no Leatherworking trainer in Durotar, go to {n:0:horde:Kamari} in the Drag in Orgrimmar"] = "Não há instrutor de Couraria em Durotar; vá até {n:0:horde:Kamari} na Ladeira, em Orgrimmar",
  ["{n:0:horde:Chaw Stronghide} in Bloodhoof Village"] = "{n:0:horde:Chaw Stronghide} na Aldeia Casco Sangrento",
  ["{n:0:horde:Shelene Rhobart} at the road junction southeast of Brill"] = "{n:0:horde:Shelene Rhobart} no cruzamento a sudeste de Montalvo",
  ["{n:0::Emerii Tallgust} in Valanaar, {n:0::Indari Sunseam} in Shen'dar Village"] = "{n:0::Emerii Tallgust} em Valanaar, {n:0::Indari Sunseam} em Shen'dar Village",
  ["Stormwind City: {n:0:alliance:Randal Worth}"] = "Ventobravo: {n:0:alliance:Randal Worth}",
  ["Ironforge: {n:0:alliance:Gretta Finespindle}"] = "Altaforja: {n:0:alliance:Gretta Finespindle}",
  ["{n:0:alliance:Adele Fielder} in the small house by Crystal Lake, northeast of Goldshire"] = "{n:0:alliance:Adele Fielder} na casinha à beira do Lago de Cristal, a nordeste de Vila d'Ouro",
  ["There is no Leatherworking trainer in Dun Morogh, go to {n:0:alliance:Gretta Finespindle} at the Great Forge in Ironforge"] = "Não há instrutor de Couraria em Dun Morogh; vá até {n:0:alliance:Gretta Finespindle} na Grande Forja, em Altaforja",
  ["{n:0:alliance:Nadyia Maneweaver} in the small house near the road to Darnassus"] = "{n:0:alliance:Nadyia Maneweaver} na casinha perto da estrada para Darnassus",
  ["You can find every Leatherworking trainer for Horde and Alliance on my WoW Forever Leatherworking Trainers page."] = "Você encontra todos os instrutores de Couraria da Horda e da Aliança na minha página de instrutores de Couraria do WoW Forever.",
  ["Apprentice Leatherworking (1-55)"] = "Couraria Aprendiz (1-55)",
  ["35x {s:2881:inv_misc_leatherscrap_03:Light Leather} - 105 Ruined Leather Scraps"] = "35x {s:2881:inv_misc_leatherscrap_03:Light Leather} - 105 Retalho de Couro Arruinado",
  ["27x {s:3816:inv_misc_pelt_wolf_01:Cured Light Hide} - 27 Light Hide, 27 Salt"] = "27x {s:3816:inv_misc_pelt_wolf_01:Cured Light Hide} - 27 Pele Leve, 27 Sal",
  ["{b}NOTE:{/b} {b}Most trainers{/b} have a Leatherworking Supply vendor nearby that sells the threads, dyes, and salt, {b}except{/b} the trainers in Elwynn Forest and Tirisfal Glades. For those, buy the Salt and Coarse Thread in Goldshire from {n:0:alliance:Tharynn Bouden} or in Brill from {n:0:horde:Abigail Shiel}."] = "{b}OBSERVAÇÃO:{/b} {b}A maioria dos instrutores{/b} tem por perto um vendedor de suprimentos de Couraria que vende as linhas, as tinturas e o sal, {b}exceto{/b} os instrutores da Floresta de Elwynn e das Clareiras de Tirisfal. Para esses, compre o Sal e a Linha Grossa em Vila d'Ouro com {n:0:alliance:Tharynn Bouden} ou em Montalvo com {n:0:horde:Abigail Shiel}.",
  ["Keep 24 of the hides, you will need them for the Light Leather Pants at 100."] = "Guarde 24 das peles; você vai precisar delas para as Calças de Couro Leve em 100.",
  ["Alternative recipes"] = "Receitas alternativas",
  ["If you farm your own leather and don't have 27 Light Hides, make Light Armor Kits until 45, then Embossed Leather Gloves until 55:"] = "Se você coleta seu próprio couro e não tem 27 Peles Leves, faça Kits de Armadura Leve até 45 e depois Luvas de Couro em Relevo até 55:",
  ["24x {s:2152:inv_misc_armorkit_17:Light Armor Kit} - 24 Light Leather"] = "24x {s:2152:inv_misc_armorkit_17:Light Armor Kit} - 24 Couro Leve",
  ["10x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 30 Light Leather, 20 Coarse Thread"] = "10x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 30 Couro Leve, 20 Linha Grossa",
  ["You still need 24 Cured Light Hide for the Light Leather Pants at 100, so keep the Light Hides you skin until then."] = "Você ainda precisa de 24 Peles Leves Curtidas para as Calças de Couro Leve em 100, então guarde as Peles Leves que esfolar até lá.",
  ["Journeyman Leatherworking (55-130)"] = "Couraria Artífice (55-130)",
  ["To train past 75, visit one of these trainers and learn Journeyman Leatherworking. You need {b}Leatherworking 50{/b} and {b}level 10{/b}:"] = "Para treinar acima de 75, visite um destes instrutores e aprenda Couraria Artífice. Você precisa de {b}Couraria 50{/b} e {b}nível 10{/b}:",
  ["Undercity: {n:0:horde:Arthur Moore}"] = "Cidade Baixa: {n:0:horde:Arthur Moore}",
  ["Thunder Bluff: {n:0:horde:Tarn}"] = "Penhasco do Trovão: {n:0:horde:Tarn}",
  ["Stormwind City: {n:0:alliance:Simon Tanner}"] = "Ventobravo: {n:0:alliance:Simon Tanner}",
  ["Ironforge: {n:0:alliance:Fimble Finespindle}"] = "Altaforja: {n:0:alliance:Fimble Finespindle}",
  ["21x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 63 Light Leather, 42 Coarse Thread"] = "21x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 63 Couro Leve, 42 Linha Grossa",
  ["8x {s:20648:inv_misc_leatherscrap_05:Medium Leather} - 32 Light Leather"] = "8x {s:20648:inv_misc_leatherscrap_05:Medium Leather} - 32 Couro Leve",
  ["10x {s:3817:inv_misc_pelt_bear_02:Cured Medium Hide} - 10 Medium Hide, 10 Salt"] = "10x {s:3817:inv_misc_pelt_bear_02:Cured Medium Hide} - 10 Pele Média, 10 Sal",
  ["Keep the Cured Medium Hides, you will need them for the Dark Leather Belts at 115."] = "Guarde as Peles Médias Curtidas; você vai precisar delas para os Cintos de Couro Escuro em 115.",
  ["19x {s:3763:inv_belt_04:Fine Leather Belt} - 114 Light Leather, 38 Coarse Thread"] = "19x {s:3763:inv_belt_04:Fine Leather Belt} - 114 Couro Leve, 38 Linha Grossa",
  ["Keep 10 of the belts for the Dark Leather Belts at 115."] = "Guarde 10 dos cintos para os Cintos de Couro Escuro em 115.",
  ["24x {s:9068:inv_pants_02:Light Leather Pants} - 240 Light Leather, 24 Cured Light Hide, 24 Fine Thread"] = "24x {s:9068:inv_pants_02:Light Leather Pants} - 240 Couro Leve, 24 Pele Leve Curtida, 24 Linha Fina",
  ["10x {s:3766:inv_belt_03:Dark Leather Belt} - 10 Fine Leather Belt, 10 Cured Medium Hide, 20 Fine Thread, 10 Gray Dye"] = "10x {s:3766:inv_belt_03:Dark Leather Belt} - 10 Cinto de Couro Fino, 10 Pele Média Curtida, 20 Linha Fina, 10 Tintura Cinza",
  ["7x {s:20649:inv_misc_leatherscrap_07:Heavy Leather} - 35 Medium Leather"] = "7x {s:20649:inv_misc_leatherscrap_07:Heavy Leather} - 35 Couro Médio",
  ["Expert Leatherworking (130-205)"] = "Couraria Especialista (130-205)",
  ["To train past 150, visit {n:0:horde:Una} in Thunder Bluff (Horde) or {n:0:alliance:Telonis} in Darnassus (Alliance) and learn Expert Leatherworking. You need {b}Leatherworking 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Para treinar acima de 150, visite {n:0:horde:Una} em Penhasco do Trovão (Horda) ou {n:0:alliance:Telonis} em Darnassus (Aliança) e aprenda Couraria Especialista. Você precisa de {b}Couraria 125{/b} e {b}nível 20{/b}, e custa 50 pratas.",
  ["30x {s:3818:inv_misc_pelt_wolf_02:Cured Heavy Hide} - 30 Heavy Hide, 90 Salt"] = "30x {s:3818:inv_misc_pelt_wolf_02:Cured Heavy Hide} - 30 Pele Pesada, 90 Sal",
  ["Keep the Cured Heavy Hides, you will need 10 for the Barbaric Shoulders at 155 and 20 for the Guardian Gloves at 165."] = "Guarde as Peles Pesadas Curtidas; você vai precisar de 10 para as Ombreiras Bárbaras em 155 e de 20 para as Luvas do Guardião em 165.",
  ["17x {s:3764:inv_gauntlets_05:Hillman's Leather Gloves} - 238 Medium Leather, 68 Fine Thread"] = "17x {s:3764:inv_gauntlets_05:Hillman's Leather Gloves} - 238 Couro Médio, 68 Linha Fina",
  ["10x {s:7151:inv_shoulder_08:Barbaric Shoulders} - 80 Heavy Leather, 10 Cured Heavy Hide, 20 Fine Thread"] = "10x {s:7151:inv_shoulder_08:Barbaric Shoulders} - 80 Couro Pesado, 10 Pele Pesada Curtida, 20 Linha Fina",
  ["20x {s:7156:inv_gauntlets_05:Guardian Gloves} - 80 Heavy Leather, 20 Cured Heavy Hide, 20 Silken Thread"] = "20x {s:7156:inv_gauntlets_05:Guardian Gloves} - 80 Couro Pesado, 20 Pele Pesada Curtida, 20 Linha de Seda",
  ["22x {s:10507:inv_belt_24:Nightscape Headband} - 110 Thick Leather, 44 Silken Thread"] = "22x {s:10507:inv_belt_24:Nightscape Headband} - 110 Couro Grosso, 44 Linha de Seda",
  ["Leatherworking Specializations"] = "Especializações de Couraria",
  ["Once you reach {b}Leatherworking 225{/b} and {b}level 40{/b}, you can choose one of the three Leatherworking specializations: Dragonscale, Elemental, or Tribal. Each specialization gives access to a specific set of patterns."] = "Quando chegar a {b}Couraria 225{/b} e {b}nível 40{/b}, você pode escolher uma das três especializações de Couraria: Escamas de Dragão, Elemental ou Tribal. Cada especialização dá acesso a um conjunto específico de moldes.",
  ["Dragonscale - Mail-type gear"] = "Escamas de Dragão - equipamentos de malha",
  ["Elemental - elemental resistance and Leather-type agility gear"] = "Elemental - equipamentos de resistência elemental e de couro com agilidade",
  ["Tribal - Leather-type intellect & agility gear and the Devilsaur Armor set"] = "Tribal - equipamentos de couro com intelecto e agilidade e o conjunto Armadura de Demossauro",
  ["For information on how to become a Dragonscale, Elemental, or Tribal Leatherworker, please see my separate guides:"] = "Para saber como se tornar um Coureiro de Escamas de Dragão, Elemental ou Tribal, veja meus guias separados:",
  ["Artisan Leatherworking (205-300)"] = "Couraria Artesão (205-300)",
  ["To train past 225, visit {n:0:horde:Hahrana Ironhide} in Camp Mojache, Feralas (Horde) or {n:0:alliance:Drakk Stonehand} in Aerie Peak, The Hinterlands (Alliance) and learn Artisan Leatherworking. You need {b}Leatherworking 200{/b} and {b}level 35{/b}."] = "Para treinar acima de 225, visite {n:0:horde:Hahrana Ironhide} no Acampamento Mojache, em Feralas (Horda) ou {n:0:alliance:Drakk Stonehand} no Ninho da Águia, nas Terras Agrestes (Aliança) e aprenda Couraria Artesão. Você precisa de {b}Couraria 200{/b} e {b}nível 35{/b}.",
  ["36x {s:10548:inv_pants_11:Nightscape Pants} - 504 Thick Leather, 144 Silken Thread"] = "36x {s:10548:inv_pants_11:Nightscape Pants} - 504 Couro Grosso, 144 Linha de Seda",
  ["{b}The Expert trainers in Thunder Bluff and Darnassus don't teach this recipe{/b}, you can only learn it from the two trainers above."] = "{b}Os instrutores Especialistas em Penhasco do Trovão e Darnassus não ensinam esta receita{/b}; você só pode aprendê-la com os dois instrutores acima.",
  ["I recommend these over the Nightscape Boots because they sell for more to a vendor, so they end up cheaper."] = "Recomendo estas em vez das Botas da Paisagem Noturna, porque são vendidas por mais a um vendedor, então acabam saindo mais baratas.",
  ["36x {s:19049:inv_gauntlets_31:Wicked Leather Gauntlets} - 288 Rugged Leather, 36 Black Dye, 36 Rune Thread"] = "36x {s:19049:inv_gauntlets_31:Wicked Leather Gauntlets} - 288 Couro Rústico, 36 Tintura Preta, 36 Linha Rúnica",
  ["The pattern is sold by {n:0:horde:Werg Thickblade} in Tirisfal Glades (Horde) and {n:0:alliance:Leonard Porter} in Western Plaguelands (Alliance)."] = "O molde é vendido por {n:0:horde:Werg Thickblade} nas Clareiras de Tirisfal (Horda) e por {n:0:alliance:Leonard Porter} nas Terras Pestilentas Ocidentais (Aliança).",
  ["Blue Suede Shoes use the same leather but sell for more to a vendor, so they save you about 13 gold on this step. If the pattern costs less than that on the Auction House, make these instead:"] = "Os Sapatos de Camurça Azul usam o mesmo couro, mas são vendidos por mais a um vendedor, então economizam cerca de 13 ouros nesta etapa. Se o molde custar menos que isso na casa de leilões, faça estes no lugar:",
  ["36x {s:1255048:inv_boots_leather_12:Blue Suede Shoes} - 288 Rugged Leather, 36 Blue Dye, 36 Rune Thread."] = "36x {s:1255048:inv_boots_leather_12:Blue Suede Shoes} - 288 Couro Rústico, 36 Tintura Azul, 36 Linha Rúnica.",
  ["53x {s:19082:inv_misc_bandage_11:Runic Leather Headband} - 742 Rugged Leather, 530 Runecloth, 53 Rune Thread"] = "53x {s:19082:inv_misc_bandage_11:Runic Leather Headband} - 742 Couro Rústico, 530 Tecido Rúnico, 53 Linha Rúnica",
  ["The pattern is sold by {n:0::Jase Farlane} at Light's Hope Chapel in Eastern Plaguelands."] = "O molde é vendido por {n:0::Jase Farlane} na Capela Esperança da Luz, nas Terras Pestilentas Orientais.",
  ["If you have the pattern, make these from 275 instead:"] = "Se você tiver o molde, faça estes a partir de 275:",
  ["27x {s:1255019:inv_bracer_22a:Blue Suede Bracers} - 270 Rugged Leather, 27 Blue Dye, 27 Rune Thread."] = "27x {s:1255019:inv_bracer_22a:Blue Suede Bracers} - 270 Couro Rústico, 27 Tintura Azul, 27 Linha Rúnica.",
  ["Blue Suede Hat"] = "Chapéu de Camurça Azul",
  ["{b}Someone with Leatherworking 300 has to place the Sewing Machine for you.{/b} You can't place a Sewing Machine yourself before 300, even if you buy one. I'm not sure if this is an oversight by Blizzard, so they might change it."] = "{b}Alguém com Couraria 300 precisa colocar a Máquina de Costura para você.{/b} Você não consegue colocar uma Máquina de Costura antes de 300, mesmo comprando uma. Não sei se é um descuido da Blizzard, então isso pode mudar.",
  ["If you can use one and have the pattern, you can make these from 280:"] = "Se você puder usar uma e tiver o molde, pode fazer estes a partir de 280:",
  ["20x {s:1255017:inv_helm_armor_buckledhat_b_01_blue:Blue Suede Hat} - 320 Rugged Leather, 80 Blue Dye, 20 Rune Thread."] = "20x {s:1255017:inv_helm_armor_buckledhat_b_01_blue:Blue Suede Hat} - 320 Couro Rústico, 80 Tintura Azul, 20 Linha Rúnica.",
  ["This WoW Forever Tailoring leveling guide will show you the fastest and cheapest way to level your Tailoring skill from 1 to 300. You will also find every trainer location and where to train Tailoring past 75, 150 and 225."] = "Este guia de Alfaiataria do WoW Forever mostra a forma mais rápida e barata de subir sua perícia de Alfaiataria de 1 a 300. Você também encontra a localização de todos os instrutores e onde treinar Alfaiataria acima de 75, 150 e 225.",
  ["Below you will find the full shopping list, the Tailoring trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Tailoring uses cloth as its main material, but cloth drops from humanoids, so you don't need a gathering profession and you can combine Tailoring with anything. Enchanting is a popular choice because you can disenchant the things you make while leveling and use the dust to level Enchanting."] = "Abaixo você encontra a lista de compras completa, os instrutores de Alfaiataria por zona inicial e capital, e as receitas mais baratas para cada faixa de perícia, de Aprendiz a Artesão. Alfaiataria usa tecido como material principal, e o tecido cai de humanoides, então você não precisa de uma profissão de coleta e pode combinar Alfaiataria com qualquer coisa. Encantamento é uma escolha popular, porque você pode desencantar o que fizer enquanto sobe a perícia e usar o pó para subir Encantamento.",
  ["{b}NOTE:{/b} {b}Most trainers{/b} have a Tailoring Supply vendor nearby that sells the threads and dyes, {b}except{/b} the trainer in Tirisfal Glades. For that one, buy the Coarse Thread in Brill from {n:0:horde:Abigail Shiel}."] = "{b}OBSERVAÇÃO:{/b} {b}A maioria dos instrutores{/b} tem por perto um vendedor de suprimentos de Alfaiataria que vende as linhas e as tinturas, {b}exceto{/b} o instrutor das Clareiras de Tirisfal. Para esse, compre a Linha Grossa em Montalvo com {n:0:horde:Abigail Shiel}.",
  ["Alternative (if cheaper)"] = "Alternativa (se for mais barata)",
  ["This list is not final yet, but the skill ranges come from the game data, so it should be pretty close. The 280-300 part is not included here yet."] = "Esta lista ainda não é definitiva, mas as faixas de perícia vêm dos dados do jogo, então deve estar bem próxima. A parte 280-300 ainda não está incluída aqui.",
  ["Tailoring Trainer Locations"] = "Localização dos instrutores de Alfaiataria",
  ["Apprentice Tailoring has no level requirement in Forever, so you can learn it on a fresh character."] = "No Forever, Alfaiataria Aprendiz não tem requisito de nível, então você pode aprendê-la com um personagem recém-criado.",
  ["Undercity: {n:0:horde:Victor Ward}"] = "Cidade Baixa: {n:0:horde:Victor Ward}",
  ["Thunder Bluff: {n:0:horde:Vhan}"] = "Penhasco do Trovão: {n:0:horde:Vhan}",
  ["There is no Tailoring trainer in Durotar, go to {n:0:horde:Snang} in the Drag in Orgrimmar"] = "Não há instrutor de Alfaiataria em Durotar; vá até {n:0:horde:Snang} na Ladeira, em Orgrimmar",
  ["There is no Tailoring trainer in Mulgore, go to {n:0:horde:Vhan} on the middle rise in Thunder Bluff"] = "Não há instrutor de Alfaiataria em Mulgore; vá até {n:0:horde:Vhan} no platô do meio em Penhasco do Trovão",
  ["{n:0:horde:Bowen Brisboise} in the small house at Cold Hearth Manor, southwest of Brill"] = "{n:0:horde:Bowen Brisboise} na casinha do Solar Coração Frio, a sudoeste de Montalvo",
  ["{n:0::Othesia Evengale} in Valanaar, {n:0::Taleen Shimmerthread} in Shen'dar Village"] = "{n:0::Othesia Evengale} em Valanaar, {n:0::Taleen Shimmerthread} em Shen'dar Village",
  ["Stormwind City: {n:0:alliance:Lawrence Schneider}"] = "Ventobravo: {n:0:alliance:Lawrence Schneider}",
  ["Ironforge: {n:0:alliance:Uthrar Threx}"] = "Altaforja: {n:0:alliance:Uthrar Threx}",
  ["{n:0:alliance:Eldrin} in a house at the Eastvale Logging Camp"] = "{n:0:alliance:Eldrin} em uma casa na Madeireira do Vale Leste",
  ["There is no Tailoring trainer in Dun Morogh, go to {n:0:alliance:Uthrar Threx} at the Great Forge in Ironforge"] = "Não há instrutor de Alfaiataria em Dun Morogh; vá até {n:0:alliance:Uthrar Threx} na Grande Forja, em Altaforja",
  ["There is no Tailoring trainer in Teldrassil, go to {n:0:alliance:Trianna} at the Craftsmen's Terrace in Darnassus"] = "Não há instrutor de Alfaiataria em Teldrassil; vá até {n:0:alliance:Trianna} no Terraço dos Artesãos, em Darnassus",
  ["You can find every Tailoring trainer for Horde and Alliance on my WoW Forever Tailoring Trainers page."] = "Você encontra todos os instrutores de Alfaiataria da Horda e da Aliança na minha página de instrutores de Alfaiataria do WoW Forever.",
  ["Apprentice Tailoring (1-55)"] = "Alfaiataria Aprendiz (1-55)",
  ["30x {s:2963:inv_fabric_linen_02:Bolt of Linen Cloth} - 60 Linen Cloth"] = "30x {s:2963:inv_fabric_linen_02:Bolt of Linen Cloth} - 60 Tecido de Linho",
  ["Keep the bolts, you need all of them for the belts."] = "Guarde as peças; você precisa de todas elas para os cintos.",
  ["28x {s:8776:inv_belt_05:Linen Belt} - 28 Bolt of Linen Cloth, 28 Coarse Thread"] = "28x {s:8776:inv_belt_05:Linen Belt} - 28 Peça de Tecido de Linho, 28 Linha Grossa",
  ["Journeyman Tailoring (55-140)"] = "Alfaiataria Artífice (55-140)",
  ["To train past 75, visit one of these trainers and learn Journeyman Tailoring. You need {b}Tailoring 50{/b} and {b}level 10{/b}:"] = "Para treinar acima de 75, visite um destes instrutores e aprenda Alfaiataria Artífice. Você precisa de {b}Alfaiataria 50{/b} e {b}nível 10{/b}:",
  ["Undercity: {n:0:horde:Rhiannon Davis}"] = "Cidade Baixa: {n:0:horde:Rhiannon Davis}",
  ["Thunder Bluff: {n:0:horde:Tepa}"] = "Penhasco do Trovão: {n:0:horde:Tepa}",
  ["Stormwind City: {n:0:alliance:Sellandus}"] = "Ventobravo: {n:0:alliance:Sellandus}",
  ["Ironforge: {n:0:alliance:Jormund Stonebrow}"] = "Altaforja: {n:0:alliance:Jormund Stonebrow}",
  ["{b}Learn Journeyman Tailoring before you make these.{/b} You can reach past 75 with them, but you won't get any skill points above 75 until you learn it, so don't go AFK while crafting before you have it."] = "{b}Aprenda Alfaiataria Artífice antes de fazer estas.{/b} Você pode passar de 75 com elas, mas não vai ganhar nenhum ponto de perícia acima de 75 até aprendê-la, então não fique AFK criando antes de tê-la.",
  ["45x {s:2964:inv_fabric_wool_03:Bolt of Woolen Cloth} - 135 Wool Cloth"] = "45x {s:2964:inv_fabric_wool_03:Bolt of Woolen Cloth} - 135 Tecido de Lã",
  ["Keep the bolts, you will need them later. In total you will need 153 {i:2997:inv_fabric_wool_03:Bolt of Woolen Cloth} (459 {i:2592:inv_fabric_wool_01:Wool Cloth}) until 140, so you can also make all of them now."] = "Guarde as peças; você vai precisar delas mais tarde. No total você vai precisar de 153 {i:2997:inv_fabric_wool_03:Bolt of Woolen Cloth} (459 {i:2592:inv_fabric_wool_01:Wool Cloth}) até 140, então também pode fazer todas agora.",
  ["22x {s:2402:inv_misc_cape_10:Woolen Cape} - 22 Bolt of Woolen Cloth, 22 Fine Thread"] = "22x {s:2402:inv_misc_cape_10:Woolen Cape} - 22 Peça de Tecido de Lã, 22 Linha Fina",
  ["If the bolts already took you past 80, just make capes until 95."] = "Se as peças já levaram você além de 80, faça capas até 95.",
  ["5x {s:3848:inv_shoulder_06:Double-stitched Woolen Shoulders} - 15 Bolt of Woolen Cloth, 10 Fine Thread"] = "5x {s:3848:inv_shoulder_06:Double-stitched Woolen Shoulders} - 15 Peça de Tecido de Lã, 10 Linha Fina",
  ["54x {s:3839:inv_fabric_silk_03:Bolt of Silk Cloth} - 216 Silk Cloth"] = "54x {s:3839:inv_fabric_silk_03:Bolt of Silk Cloth} - 216 Tecido de Seda",
  ["Keep the bolts, you will need them later. In total you will need 184 {i:4305:inv_fabric_silk_03:Bolt of Silk Cloth} (736 {i:4306:inv_fabric_silk_01:Silk Cloth}) until 190, so you can also make all of them now."] = "Guarde as peças; você vai precisar delas mais tarde. No total você vai precisar de 184 {i:4305:inv_fabric_silk_03:Bolt of Silk Cloth} (736 {i:4306:inv_fabric_silk_01:Silk Cloth}) até 190, então também pode fazer todas agora.",
  ["29x {s:3852:inv_gauntlets_05:Gloves of Meditation} - 116 Bolt of Woolen Cloth, 87 Fine Thread, 29 Elixir of Wisdom"] = "29x {s:3852:inv_gauntlets_05:Gloves of Meditation} - 116 Peça de Tecido de Lã, 87 Linha Fina, 29 Elixir da Sabedoria",
  ["You can buy {i:3383:inv_potion_06:Elixir of Wisdom} from the Auction House or ask an Alchemist."] = "Você pode comprar {i:3383:inv_potion_06:Elixir of Wisdom} na casa de leilões ou pedir a um alquimista.",
  ["Expert Tailoring (140-200)"] = "Alfaiataria Especialista (140-200)",
  ["To train past 150, visit {n:0:horde:Josef Gregorian} in Undercity (Horde) or {n:0:alliance:Georgio Bolero} in Stormwind City (Alliance) and learn Expert Tailoring. You need {b}Tailoring 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Para treinar acima de 150, visite {n:0:horde:Josef Gregorian} na Cidade Baixa (Horda) ou {n:0:alliance:Georgio Bolero} em Ventobravo (Aliança) e aprenda Alfaiataria Especialista. Você precisa de {b}Alfaiataria 125{/b} e {b}nível 20{/b}, e custa 50 pratas.",
  ["23x {s:3865:inv_fabric_mageweave_03:Bolt of Mageweave} - 115 Mageweave Cloth"] = "23x {s:3865:inv_fabric_mageweave_03:Bolt of Mageweave} - 115 Tecido Mágico",
  ["Keep the bolts, you will need them later. In total you will need 157 {i:4339:inv_fabric_mageweave_03:Bolt of Mageweave} (785 {i:4338:inv_fabric_mageweave_01:Mageweave Cloth}) until 225, so you can also make all of them now."] = "Guarde as peças; você vai precisar delas mais tarde. No total você vai precisar de 157 {i:4339:inv_fabric_mageweave_03:Bolt of Mageweave} (785 {i:4338:inv_fabric_mageweave_01:Mageweave Cloth}) até 225, então também pode fazer todas agora.",
  ["20x {s:8791:inv_shirt_04:Crimson Silk Vest} - 80 Bolt of Silk Cloth, 40 Red Dye, 40 Fine Thread"] = "20x {s:8791:inv_shirt_04:Crimson Silk Vest} - 80 Peça de Seda, 40 Tintura Vermelha, 40 Linha Fina",
  ["26x {s:8799:inv_pants_06:Crimson Silk Pantaloons} - 104 Bolt of Silk Cloth, 52 Red Dye, 52 Silken Thread"] = "26x {s:8799:inv_pants_06:Crimson Silk Pantaloons} - 104 Peça de Seda, 52 Tintura Vermelha, 52 Linha de Seda",
  ["19x {s:12049:inv_pants_09:Black Mageweave Leggings} - 38 Bolt of Mageweave, 57 Silken Thread"] = "19x {s:12049:inv_pants_09:Black Mageweave Leggings} - 38 Peça de Tecido Mágico, 57 Linha de Seda",
  ["Artisan Tailoring (200-300)"] = "Alfaiataria Artesão (200-300)",
  ["To train past 225, visit {n:0:horde:Daryl Stack} in Tarren Mill, Hillsbrad Foothills (Horde) or {n:0:alliance:Timothy Worthington} in Theramore Isle, Dustwallow Marsh (Alliance) and learn Artisan Tailoring. You need {b}Tailoring 200{/b} and {b}level 35{/b}."] = "Para treinar acima de 225, visite {n:0:horde:Daryl Stack} na Serraria Tarren, no Contraforte de Eira dos Montes (Horda) ou {n:0:alliance:Timothy Worthington} na Ilha Theramore, no Pântano Vadeoso (Aliança) e aprenda Alfaiataria Artesão. Você precisa de {b}Alfaiataria 200{/b} e {b}nível 35{/b}.",
  ["5x {s:12074:inv_shoulder_25:Black Mageweave Shoulders} - 15 Bolt of Mageweave, 10 Heavy Silken Thread"] = "5x {s:12074:inv_shoulder_25:Black Mageweave Shoulders} - 15 Peça de Tecido Mágico, 10 Linha de Seda Pesada",
  ["{b}The Expert trainers in Undercity and Stormwind don't teach this recipe{/b}, you can only learn it from the two trainers above."] = "{b}Os instrutores Especialistas na Cidade Baixa e em Ventobravo não ensinam esta receita{/b}; você só pode aprendê-la com os dois instrutores acima.",
  ["23x {s:18401:inv_fabric_purplefire_02:Bolt of Runecloth} - 115 Runecloth"] = "23x {s:18401:inv_fabric_purplefire_02:Bolt of Runecloth} - 115 Tecido Rúnico",
  ["Keep the bolts, you will need them later. In total you will need 311 {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth} (1555 {i:14047:inv_fabric_purplefire_01:Runecloth}) until 280, so you can also make all of them now."] = "Guarde as peças; você vai precisar delas mais tarde. No total você vai precisar de 311 {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth} (1555 {i:14047:inv_fabric_purplefire_01:Runecloth}) até 280, então também pode fazer todas agora.",
  ["26x {s:12065:inv_misc_bag_10_black:Mageweave Bag} - 104 Bolt of Mageweave, 52 Silken Thread"] = "26x {s:12065:inv_misc_bag_10_black:Mageweave Bag} - 104 Peça de Tecido Mágico, 52 Linha de Seda",
  ["I recommend the bags right now simply because they are more useful. You can use them yourself, sell some, give them to friends or use them in your bank."] = "Recomendo as bolsas agora simplesmente porque são mais úteis. Você pode usá-las, vender algumas, dar para amigos ou usá-las no banco.",
  ["If you don't need the bags and don't want to sell them, make these instead."] = "Se não precisar das bolsas e não quiser vendê-las, faça estes no lugar.",
  ["10x {s:18402:inv_belt_15:Runecloth Belt} - 30 Bolt of Runecloth, 10 Rune Thread."] = "10x {s:18402:inv_belt_15:Runecloth Belt} - 30 Peça de Tecido Rúnico, 10 Linha Rúnica.",
  ["24x {s:18402:inv_belt_15:Runecloth Belt} - 72 Bolt of Runecloth, 24 Rune Thread"] = "24x {s:18402:inv_belt_15:Runecloth Belt} - 72 Peça de Tecido Rúnico, 24 Linha Rúnica",
  ["11x {s:18417:inv_gauntlets_25:Runecloth Gloves} - 44 Bolt of Runecloth, 44 Rugged Leather, 11 Rune Thread"] = "11x {s:18417:inv_gauntlets_25:Runecloth Gloves} - 44 Peça de Tecido Rúnico, 44 Couro Rústico, 11 Linha Rúnica",
  ["The pattern is sold by {n:0::Qia} in Winterspring."] = "O molde é vendido por {n:0::Qia} em Hibérnia.",
  ["39x {s:1257487:inv_bracer_13:Runecloth Cuffs} - 195 Bolt of Runecloth, 39 Ironweb Spider Silk, 39 Rune Thread"] = "39x {s:1257487:inv_bracer_13:Runecloth Cuffs} - 195 Peça de Tecido Rúnico, 39 Seda de Aranha Teiaférrea, 39 Linha Rúnica",
  ["The pattern is sold by {n:0::Pexmit} in Mount Hyjal. It's bind on pickup, so buy it with the character that levels Tailoring."] = "O molde é vendido por {n:0::Pexmit} no Monte Hyjal. É vinculado ao ser coletado, então compre-o com o personagem que está subindo Alfaiataria.",
  ["Horde players can also get it as the reward for {q:95769::Threading a Solution}, a quest from {n:265788::Kal'tinzan} in Elderwild, Mount Hyjal. It needs level 54 and 6 Bolt of Runecloth. It's probably a Tailoring quest, but I don't know yet what skill it needs."] = "Jogadores da Horda também podem obtê-lo como recompensa de {q:95769::Threading a Solution}, uma missão de {n:265788::Kal'tinzan} em Elderwild, no Monte Hyjal. Ela exige nível 54 e 6 Peças de Tecido Rúnico. Provavelmente é uma missão de Alfaiataria, mas ainda não sei qual perícia ela exige.",
  ["Make the {s:18449:inv_shoulder_21:Runecloth Shoulders} if you can get the pattern. These are all the recipes I found so far that still give points after 280. I left out the ones that aren't worth it for leveling, and there might be new ones that nobody has found yet."] = "Faça as {s:18449:inv_shoulder_21:Runecloth Shoulders} se conseguir o molde. Estas são todas as receitas que encontrei até agora que ainda dão pontos depois de 280. Deixei de fora as que não valem a pena para subir, e pode haver receitas novas que ninguém encontrou ainda.",
  ["Range"] = "Faixa",
  ["Materials"] = "Materiais",
  ["Pattern"] = "Molde",
  ["World drop, on the Auction House"] = "Drop do mundo, na casa de leilões",
  ["Rare, grab it if you see it on the Auction House"] = "Raro, pegue se vir na casa de leilões",
  ["You can get a few more points with these, but they stop giving skill points before 300, so you can't reach 300 with them:"] = "Você consegue mais alguns pontos com estas, mas elas param de dar pontos de perícia antes de 300, então não dá para chegar a 300 com elas:",
  ["{n:0::Pexmit} in Mount Hyjal"] = "{n:0::Pexmit} no Monte Hyjal",
  ["Recipes that need a Loom"] = "Receitas que precisam de um Tear",
  ["{b}These recipes need a Loom, and you can only make a Loom at Tailoring 300.{/b} They could be used for leveling, but for now you would need a camp where another tailor already placed a Loom. I'm not sure if this is an oversight by Blizzard, so they might change it."] = "{b}Estas receitas precisam de um Tear, e você só pode fazer um Tear com Alfaiataria 300.{/b} Elas poderiam ser usadas para subir, mas por enquanto você precisaria de um acampamento onde outro alfaiate já tenha colocado um Tear. Não sei se é um descuido da Blizzard, então isso pode mudar.",
  ["These are the Cenarion Circle patterns from {n:0::Mishta} in Silithus:"] = "Estes são os moldes do Círculo Cenariano vendidos por {n:0::Mishta} em Silithus:",
  ["Requires"] = "Requer",
  ["5x {s:1297123:inv_gauntlets_17:Swarmtender's Gloves} or {s:1297120:inv_gauntlets_18:Venomspew Gloves}"] = "5x {s:1297123:inv_gauntlets_17:Swarmtender's Gloves} ou {s:1297120:inv_gauntlets_18:Venomspew Gloves}",
  ["20x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "20x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} ou {i:7082:spell_nature_earthbind:Essence of Air}",
  ["Cenarion Circle Friendly"] = "Círculo Cenariano Amigável",
  ["5x {s:1297124:inv_belt_03:Swarmtender's Cord} or {s:1297121:inv_belt_25:Venomspew Cord}"] = "5x {s:1297124:inv_belt_03:Swarmtender's Cord} ou {s:1297121:inv_belt_25:Venomspew Cord}",
  ["30x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "30x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} ou {i:7082:spell_nature_earthbind:Essence of Air}",
  ["Cenarion Circle Honored"] = "Círculo Cenariano Honrado",
  ["18x {s:1297125:inv_boots_cloth_01:Swarmtender's Footpads} or {s:1297122:inv_boots_cloth_04:Venomspew Footpads}"] = "18x {s:1297125:inv_boots_cloth_01:Swarmtender's Footpads} ou {s:1297122:inv_boots_cloth_04:Venomspew Footpads}",
  ["90x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 18x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 54x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "90x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 18x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 54x {i:7080:spell_nature_acid_01:Essence of Water} ou {i:7082:spell_nature_earthbind:Essence of Air}",
  ["This WoW Forever Mining leveling guide will show you the fastest way to level Mining from 1 to 300. You will also find every trainer location and where to train Mining past 75, 150 and 225."] = "Este guia de Mineração do WoW Forever mostra a forma mais rápida de subir Mineração de 1 a 300. Você também encontra a localização de todos os instrutores e onde treinar Mineração acima de 75, 150 e 225.",
  ["Below you will find the Mining trainers by starting zone and capital city, and the best zones to mine in for every skill range. Mining serves two professions, Blacksmithing and Engineering, so it's really good combined with these two. Check out my Forever Blacksmithing leveling guide or my Forever Engineering leveling guide if you want to level one of them."] = "Abaixo você encontra os instrutores de Mineração por zona inicial e capital, e as melhores zonas para minerar em cada faixa de perícia. Mineração atende duas profissões, Ferraria e Engenharia, então combina muito bem com elas. Confira meu guia de Ferraria do Forever ou meu guia de Engenharia do Forever se quiser subir uma delas.",
  ["WoW Forever added a couple of new ores, bars and recipes. You can check them out here:"] = "O WoW Forever adicionou alguns minérios, barras e receitas novos. Você pode conferi-los aqui:",
  ["Mining Trainer Locations"] = "Localização dos instrutores de Mineração",
  ["Every capital city except Darnassus has a Mining trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "Toda capital, exceto Darnassus, tem um instrutor de Mineração. Você também pode perguntar a um guarda, e ele será marcado com uma bandeira vermelha no seu mapa.",
  ["{b}Capital cities:{/b}"] = "{b}Capitais:{/b}",
  ["Undercity: {n:0:horde:Brom Killian}"] = "Cidade Baixa: {n:0:horde:Brom Killian}",
  ["Thunder Bluff: {n:0:horde:Brek Stonehoof}"] = "Penhasco do Trovão: {n:0:horde:Brek Stonehoof}",
  ["{b}Starting zones:{/b}"] = "{b}Zonas iniciais:{/b}",
  ["{n:0:horde:Norzsh} in the Valley of Trials (only up to 75) {n:0:horde:Krunn} in Razor Hill"] = "{n:0:horde:Norzsh} no Vale das Provações (só até 75) {n:0:horde:Krunn} no Monte da Navalha",
  ["{n:0:horde:Vartha Rockmane} in Camp Narache (only up to 75) {n:0:horde:Brek Stonehoof} in Thunder Bluff"] = "{n:0:horde:Vartha Rockmane} no Acampamento Narache (só até 75) {n:0:horde:Brek Stonehoof} em Penhasco do Trovão",
  ["{n:0:horde:Walter Mason} in Deathknell (only up to 75) {n:0:horde:Brom Killian} in Undercity"] = "{n:0:horde:Walter Mason} em Plangemortis (só até 75) {n:0:horde:Brom Killian} na Cidade Baixa",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} as your reward, it teaches you Mining. The trainers on the island are {n:0::Halavuul Cragwind} in Valanaar and {n:0::Messana Crestwind} in Shen'dar Village."] = "Não há instrutor em Thendal Village, onde você começa, mas você não precisa de um. {q:93552::Harvesting Windstones} é uma das primeiras missões que você recebe em Thendal Village. Escolha {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} como recompensa; ele ensina Mineração. Os instrutores da ilha são {n:0::Halavuul Cragwind} em Valanaar e {n:0::Messana Crestwind} em Shen'dar Village.",
  ["Stormwind City: {n:0:alliance:Gelman Stonehand}"] = "Ventobravo: {n:0:alliance:Gelman Stonehand}",
  ["Ironforge: {n:0:alliance:Geofram Bouldertoe}"] = "Altaforja: {n:0:alliance:Geofram Bouldertoe}",
  ["Darnassus: no trainer, the closest one is {n:0:alliance:Kurdram Stonehammer} in Auberdine, Darkshore"] = "Darnassus: não há instrutor; o mais próximo é {n:0:alliance:Kurdram Stonehammer} em Auberdine, na Costa Negra",
  ["{n:0:alliance:Kelsey Fargo} (only up to 75) {n:0:alliance:Gelman Stonehand} in Stormwind City"] = "{n:0:alliance:Kelsey Fargo} (só até 75) {n:0:alliance:Gelman Stonehand} em Ventobravo",
  ["{n:0:alliance:Sally Swiftwrench} (only up to 75) {n:0:alliance:Yarr Hammerstone} at Steelgrill's Depot {n:0:alliance:Dank Drizzlecut} at Gol'Bolar Quarry"] = "{n:0:alliance:Sally Swiftwrench} (só até 75) {n:0:alliance:Yarr Hammerstone} no Depósito do Grelhaço {n:0:alliance:Dank Drizzlecut} na Pedreira Gol'Bolar",
  ["{n:0:alliance:Fanorran Stilloak} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Kurdram Stonehammer} in Auberdine, Darkshore"] = "{n:0:alliance:Fanorran Stilloak} em Aldrassil, no Vale Umbroso (só até 75) {n:0:alliance:Kurdram Stonehammer} em Auberdine, na Costa Negra",
  ["You can find every Mining trainer for Horde and Alliance on my WoW Forever Mining Trainers page."] = "Você encontra todos os instrutores de Mineração da Horda e da Aliança na minha página de instrutores de Mineração do WoW Forever.",
  ["Track Ore on Your Minimap"] = "Rastreie minérios no minimapa",
  ["You can only track one thing at a time, so {b}you can't track minerals and herbs together{/b}."] = "Você só pode rastrear uma coisa por vez, então {b}não dá para rastrear minérios e ervas ao mesmo tempo{/b}.",
  ["You learn {s:2580:spell_nature_earthquake:Find Minerals} together with Mining, but it's not turned on by default:"] = "Você aprende {s:2580:spell_nature_earthquake:Find Minerals} junto com Mineração, mas não vem ativado por padrão:",
  ["Open the Professions window with the hammer and pick button, the 2nd button in the menu at the bottom of your screen."] = "Abra a janela de Profissões com o botão de martelo e picareta, o 2º botão do menu na parte de baixo da tela.",
  ["Click Find Minerals in the Mining box. {b}I recommend dragging it to your action bar, close to the buffs you use after you die.{/b} This way you make a habit out of it and you are less likely to forget it."] = "Clique em Encontrar Minerais no quadro de Mineração. {b}Recomendo arrastá-lo para a sua barra de ações, perto dos bônus que você usa depois de morrer.{/b} Assim você cria o hábito e tem menos chance de esquecer.",
  ["The Find Minerals buff shows up next to your minimap. {b}Your tracking turns off every time you die, so don't forget to turn it back on!{/b}"] = "O bônus Encontrar Minerais aparece ao lado do minimapa. {b}O rastreamento desliga toda vez que você morre, então não se esqueça de ligá-lo de novo!{/b}",
  ["The Find Minerals button in the WoW Forever Professions window"] = "O botão Encontrar Minerais na janela de Profissões do WoW Forever",
  ["Mining Skill Bonuses"] = "Bônus de perícia de Mineração",
  ["You don't need these, but they help when you are stuck between two ores. With +5 you can mine Iron Deposits from 120 instead of 125, so you can skip the last few slow points of Tin."] = "Você não precisa deles, mas ajudam quando você está preso entre dois minérios. Com +5 você pode minerar Depósitos de Ferro a partir de 120 em vez de 125, então pode pular os últimos pontos lentos do Estanho.",
  ["Mining"] = "Mineração",
  ["How to get it"] = "Como conseguir",
  ["An enchanter"] = "Um encantador",
  ["Made by Engineers, you need Engineering 205 to wear it"] = "Feito por engenheiros; você precisa de Engenharia 205 para usá-lo",
  ["Reward of A Miner Problem, an Alliance quest in the Riverglades"] = "Recompensa de A Miner Problem, uma missão da Aliança em Riverglades",
  ["Drops from Miner Johnson in The Deadmines"] = "Cai do Mineiro Johnson nas Minas Mortas",
  ["Smelting to 105"] = "Fundição até 105",
  ["You can skip the first 105 skill points by buying ores on the Auction House and smelting them. If you prefer leveling Mining the normal way, scroll down to the mining routes. But I would recommend smelting if you have the gold, as it saves a lot of time. Sometimes the bars even sell for more than the ores or they are very close in price, so it's not like you are losing much by doing this."] = "Você pode pular os primeiros 105 pontos de perícia comprando minérios na casa de leilões e fundindo-os. Se preferir subir Mineração do jeito normal, desça até as rotas de mineração. Mas eu recomendo a fundição se você tiver o ouro, porque economiza muito tempo. Às vezes as barras são vendidas até por mais que os minérios, ou por um preço bem parecido, então você não perde muito fazendo isso.",
  ["Buy around 140 {i:2770:inv_ore_copper_01:Copper Ore} and 70 {i:2771:inv_ore_tin_01:Tin Ore}. Smelting is mostly yellow and green, so you might need a few more if you are unlucky."] = "Compre cerca de 140 {i:2770:inv_ore_copper_01:Copper Ore} e 70 {i:2771:inv_ore_tin_01:Tin Ore}. A fundição fica quase sempre amarela e verde, então talvez você precise de um pouco mais se tiver azar.",
  ["Notes"] = "Observações",
  ["120-140x {s:2657:inv_ingot_02:Smelt Copper} until you reach 65. Keep 70 Copper Bars, you will need them for Bronze."] = "120-140x {s:2657:inv_ingot_02:Smelt Copper} até chegar a 65. Guarde 70 Barras de Cobre; você vai precisar delas para o Bronze.",
  ["Learn Journeyman Mining, Smelt Tin and Smelt Bronze from your trainer. Make 70x {s:3304:inv_ingot_05:Smelt Tin}. It turns grey at 75, but you need all 70 Tin Bars for Bronze anyway."] = "Aprenda Mineração Artífice, Fundir Estanho e Fundir Bronze com seu instrutor. Faça 70x {s:3304:inv_ingot_05:Smelt Tin}. Fica cinza em 75, mas você precisa das 70 Barras de Estanho para o Bronze de qualquer forma.",
  ["Make 70x {s:2659:inv_ingot_bronze:Smelt Bronze} from the Copper Bars and Tin Bars you made. You will end up somewhere between 100 and 110, so you might need a few more."] = "Faça 70x {s:2659:inv_ingot_bronze:Smelt Bronze} com as Barras de Cobre e de Estanho que você fez. Você vai terminar em algum ponto entre 100 e 110, então talvez precise de mais algumas.",
  ["Learn Smelt Silver from your trainer. Check the price of Silver Ore and Silver Bar first, because this part can get expensive. If you don't mind the cost, make 35-45x {s:2658:inv_ingot_01:Smelt Silver} until you reach 120. The last 5 points to 125 could take around 50 more Silver Ore, so I recommend mining from 120. (or keep smelting if you have the gold) Iron Deposits need Mining 125, but with +5 from the Mining Skill Bonuses above you can mine them from 120, so you can skip Tin and go straight to Iron."] = "Aprenda Fundir Prata com seu instrutor. Confira antes o preço do Minério de Prata e da Barra de Prata, porque esta parte pode ficar cara. Se não se importar com o custo, faça 35-45x {s:2658:inv_ingot_01:Smelt Silver} até chegar a 120. Os últimos 5 pontos até 125 podem exigir cerca de 50 Minérios de Prata a mais, então recomendo minerar a partir de 120. (ou continue fundindo se tiver o ouro) Depósitos de Ferro exigem Mineração 125, mas com +5 dos bônus de perícia de Mineração acima você pode minerá-los a partir de 120, então pode pular o Estanho e ir direto para o Ferro.",
  ["{b}Don't forget to buy{/b} a {i:2901:inv_pick_02:Mining Pick} from the Mining Supplier near your trainer or from the trainer!"] = "{b}Não se esqueça de comprar{/b} uma {i:2901:inv_pick_02:Mining Pick} com o fornecedor de Mineração perto do seu instrutor ou com o próprio instrutor!",
  ["You can buy one from these vendors:"] = "Você pode comprar uma com estes vendedores:",
  ["{n:0:horde:Norzsh} in the Valley of Trials, {n:0:horde:Flakk} in Razor Hill"] = "{n:0:horde:Norzsh} no Vale das Provações, {n:0:horde:Flakk} no Monte da Navalha",
  ["{n:0:horde:Vartha Rockmane} in Camp Narache, {n:0:horde:Wunna Darkmane} in Bloodhoof Village"] = "{n:0:horde:Vartha Rockmane} no Acampamento Narache, {n:0:horde:Wunna Darkmane} na Aldeia Casco Sangrento",
  ["{n:0:horde:Walter Mason} in Deathknell, {n:0:horde:Abigail Shiel} in Brill"] = "{n:0:horde:Walter Mason} em Plangemortis, {n:0:horde:Abigail Shiel} em Montalvo",
  ["{n:0::Uualia Suncrest} in Thendal Village, {n:0::Belandiel Farflight} in Shen'dar Village"] = "{n:0::Uualia Suncrest} em Thendal Village, {n:0::Belandiel Farflight} em Shen'dar Village",
  ["{n:0:horde:Gorina} in the Valley of Honor"] = "{n:0:horde:Gorina} no Vale da Honra",
  ["{n:0:horde:Elizabeth Van Talen} in the Rogues' Quarter"] = "{n:0:horde:Elizabeth Van Talen} no Bairro dos Gatunos",
  ["{n:0:alliance:Brother Danil} in Northshire Valley, {n:0:alliance:Tharynn Bouden} in Goldshire"] = "{n:0:alliance:Brother Danil} no Vale de Vila Norte, {n:0:alliance:Tharynn Bouden} em Vila d'Ouro",
  ["{n:0:alliance:Thrawn Boltar} in Kharanos"] = "{n:0:alliance:Thrawn Boltar} em Kharanos",
  ["{n:0:alliance:Fanorran Stilloak} at Aldrassil in Shadowglen, {n:0:alliance:Narret Shadowgrove} in Dolanaar"] = "{n:0:alliance:Fanorran Stilloak} em Aldrassil, no Vale Umbroso, {n:0:alliance:Narret Shadowgrove} em Dolanaar",
  ["{n:0:alliance:Brooke Stonebraid} in the Dwarven District"] = "{n:0:alliance:Brooke Stonebraid} no Distrito dos Anões",
  ["{n:0:alliance:Thurgrum Deepforge} in The Great Forge"] = "{n:0:alliance:Thurgrum Deepforge} na Grande Forja",
  ["Like I said above, for most high level players I think it's best to skip this part and smelt your way up to at least 105. But if you prefer mining and you can choose your zone, I think {b}Durotar{/b} is the best for Horde and {b}Elwynn Forest{/b} for Alliance."] = "Como eu disse acima, para a maioria dos jogadores de nível alto acho melhor pular esta parte e subir fundindo até pelo menos 105. Mas se você preferir minerar e puder escolher a zona, acho que {b}Durotar{/b} é a melhor para a Horda e a {b}Floresta de Elwynn{/b} para a Aliança.",
  ["One or two laps around the zone will get you enough Copper Ore to reach 65 with smelting."] = "Uma ou duas voltas pela zona rendem Minério de Cobre suficiente para chegar a 65 com a fundição.",
  ["After you do one lap, {b}stop at Razor Hill and smelt your Copper Ore{/b} into Copper Bars."] = "Depois de dar uma volta, {b}pare no Monte da Navalha e funda seu Minério de Cobre{/b} em Barras de Cobre.",
  ["Mining route in Durotar"] = "Rota de mineração em Durotar",
  ["The cave marked with the red circle has 5 Copper Veins inside, {b}the respawn rate is so fast that you can basically stay inside the cave and level there{/b}. The cave layout is also very good because there is a drop down at the end, so you can quickly return to the start and continue mining. If the respawn rate is not enough for you or there is competition, just run outside, mine a couple of Copper Veins and go back to the cave."] = "A caverna marcada com o círculo vermelho tem 5 Veios de Cobre lá dentro, e {b}o reaparecimento é tão rápido que você pode basicamente ficar dentro da caverna e subir ali{/b}. O formato da caverna também é ótimo, porque há uma descida no final, então você volta rápido ao início e continua minerando. Se o reaparecimento não for suficiente ou houver concorrência, saia, minere alguns Veios de Cobre e volte para a caverna.",
  ["You can also just do a full lap in Mulgore, the route is very easy to follow, it's basically a loop around the edge of the zone. But I found the cave to be better without a mount."] = "Você também pode simplesmente dar uma volta completa em Mulgore; a rota é muito fácil de seguir, basicamente um circuito pela borda da zona. Mas achei a caverna melhor sem montaria.",
  ["{b}You can smelt your ore at the Bael'dun Digsite{/b}, the dwarf camp just north of the cave has a forge and an anvil. (marked on the map) The dwarves there are hostile."] = "{b}Você pode fundir seu minério no Sítio de Escavação Bael'dun{/b}: o acampamento dos anões logo ao norte da caverna tem uma forja e uma bigorna. (marcadas no mapa) Os anões ali são hostis.",
  ["Mining route in Mulgore with the forge and anvil at the Bael'dun Digsite"] = "Rota de mineração em Mulgore com a forja e a bigorna no Sítio de Escavação Bael'dun",
  ["Both routes are good. The route on the east side of the zone will probably have fewer people, because there are fewer quest hubs there."] = "As duas rotas são boas. A rota no lado leste da zona provavelmente terá menos gente, porque há menos centros de missões ali.",
  ["{b}Stop at Brill after one lap{/b} to smelt your Copper Ore."] = "{b}Pare em Montalvo depois de uma volta{/b} para fundir seu Minério de Cobre.",
  ["Mining route in Tirisfal Glades"] = "Rota de mineração nas Clareiras de Tirisfal",
  ["{q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} as your reward, it teaches you Mining."] = "{q:93552::Harvesting Windstones} é uma das primeiras missões que você recebe em Thendal Village. Escolha {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} como recompensa; ele ensina Mineração.",
  ["The respawn rate is very fast around this area, sometimes the veins spawned right on top of me. You can do a larger route, but without a mount and with the fast respawn rate I found it wasn't needed."] = "O reaparecimento é muito rápido nesta área; às vezes os veios surgiam bem em cima de mim. Você pode fazer uma rota maior, mas sem montaria e com o reaparecimento rápido, achei que não era necessário.",
  ["{b}Stop at Shen'dar Village after one lap{/b} to smelt your Copper Ore."] = "{b}Pare em Shen'dar Village depois de uma volta{/b} para fundir seu Minério de Cobre.",
  ["Mining route on Zephras Isle"] = "Rota de mineração em Zephras Isle",
  ["Just move back and forth along the marked route, and clear the cave if you are high enough level. The respawn rate is quite fast inside the cave, so you might not even have to leave it, it depends on your level. You can also just skip the cave, the respawn rate seems to be fast enough on the route, but then do the small detour to the north too."] = "Vá e volte pela rota marcada e limpe a caverna se tiver nível suficiente. O reaparecimento é bem rápido dentro da caverna, então talvez você nem precise sair dela; depende do seu nível. Você também pode pular a caverna, o reaparecimento parece rápido o bastante na rota, mas nesse caso faça também o pequeno desvio para o norte.",
  ["{b}Stop at Goldshire after one lap{/b} to smelt your Copper Ore."] = "{b}Pare em Vila d'Ouro depois de uma volta{/b} para fundir seu Minério de Cobre.",
  ["Mining route in Elwynn Forest"] = "Rota de mineração na Floresta de Elwynn",
  ["Not much to say about this one, just do loops around this area. You don't have to go inside the cave, it's optional and the respawn rate outside is quite fast."] = "Não há muito o que dizer sobre esta: dê voltas por esta área. Você não precisa entrar na caverna, é opcional, e o reaparecimento do lado de fora é bem rápido.",
  ["{b}Stop at Kharanos after one lap{/b} to smelt your Copper Ore."] = "{b}Pare em Kharanos depois de uma volta{/b} para fundir seu Minério de Cobre.",
  ["Mining route in Dun Morogh"] = "Rota de mineração em Dun Morogh",
  ["These two caves have an insanely fast respawn rate. I don't know if it stays like this, but right now you can just stay inside the caves and level there."] = "Estas duas cavernas têm um reaparecimento absurdamente rápido. Não sei se vai continuar assim, mas por enquanto você pode simplesmente ficar dentro das cavernas e subir ali.",
  ["There is no forge in Teldrassil, {b}the closest one is at the Warrior's Terrace in Darnassus{/b}."] = "Não há forja em Teldrassil; {b}a mais próxima fica no Terraço dos Guerreiros, em Darnassus{/b}.",
  ["Mining route in Teldrassil"] = "Rota de mineração em Teldrassil",
  ["Visit your trainer and learn Journeyman Mining, it requires Mining 50. The new Junior Mining Trainers in the starting areas won't teach you Journeyman Mining."] = "Visite seu instrutor e aprenda Mineração Artífice; exige Mineração 50. Os novos Instrutores Júnior de Mineração nas áreas iniciais não ensinam Mineração Artífice.",
  ["If you have any Copper Ore or Tin Ore at this point, smelt them and make Bronze Bars before you head out, because Bronze stops giving skill points around 105."] = "Se você tiver Minério de Cobre ou de Estanho a esta altura, funda-os e faça Barras de Bronze antes de sair, porque o Bronze para de dar pontos de perícia por volta de 105.",
  ["For Alliance, the {b}Wetlands{/b} is the best one by far if you can manage the cave. For Horde it's the {b}Silverpine Forest{/b} cave or {b}Hillsbrad Foothills{/b}. The rest are pretty even, hard to judge."] = "Para a Aliança, o {b}Pantanal{/b} é de longe o melhor se você der conta da caverna. Para a Horda, é a caverna da {b}Floresta de Pinhaprata{/b} ou o {b}Contraforte de Eira dos Montes{/b}. O resto é bem equilibrado, difícil de avaliar.",
  ["Ores in these zones: {i:2771:inv_ore_tin_01:Tin Ore}, {i:2770:inv_ore_copper_01:Copper Ore}, {i:2775:inv_stone_16:Silver Ore}"] = "Minérios nestas zonas: {i:2771:inv_ore_tin_01:Tin Ore}, {i:2770:inv_ore_copper_01:Copper Ore}, {i:2775:inv_stone_16:Silver Ore}",
  ["Tin Veins need Mining 65 and Silver Veins 75."] = "Veios de Estanho exigem Mineração 65 e Veios de Prata, 75.",
  ["Wetlands"] = "Pantanal",
  ["Silverpine Forest"] = "Floresta de Pinhaprata",
  ["Westfall"] = "Cerro Oeste",
  ["Hillsbrad Foothills"] = "Contraforte de Eira dos Montes",
  ["The Barrens"] = "Sertões",
  ["Ashenvale"] = "Vale Gris",
  ["Stonetalon Mountains"] = "Cordilheira das Torres de Pedra",
  ["This cave in the Wetlands is the best place for Alliance players to level Mining. The cave is full of Tin Veins and Incendicite Mineral Veins with a very fast respawn time."] = "Esta caverna no Pantanal é o melhor lugar para jogadores da Aliança subirem Mineração. A caverna está cheia de Veios de Estanho e de Veios de Mineral Incendicita, com reaparecimento muito rápido.",
  ["The mobs are around level 20 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "Os monstros são de nível 20, mais ou menos, e {b}no Forever eles reaparecem muito mais rápido, então você precisa estar bem acima do nível deles{/b}, senão eles vão continuar reaparecendo bem em cima de você.",
  ["Mining route in the Wetlands"] = "Rota de mineração no Pantanal",
  ["This cave has 3 vein spawn points with a very fast respawn time, just mine the veins and wait for the respawn. (around 2 minutes)"] = "Esta caverna tem 3 pontos de surgimento de veios com reaparecimento muito rápido; é só minerar os veios e esperar que reapareçam. (cerca de 2 minutos)",
  ["The mobs are around level 21-22 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "Os monstros são de nível 21-22, mais ou menos, e {b}no Forever eles reaparecem muito mais rápido, então você precisa estar bem acima do nível deles{/b}, senão eles vão continuar reaparecendo bem em cima de você.",
  ["Mining route in Silverpine Forest"] = "Rota de mineração na Floresta de Pinhaprata",
  ["This cave has several Tin Veins that respawn very fast. There are also veins outside, so if you clear it too fast you can just run outside and mine a few there too."] = "Esta caverna tem vários Veios de Estanho que reaparecem muito rápido. Também há veios do lado de fora, então se você limpar a caverna rápido demais, pode sair e minerar alguns lá também.",
  ["The mobs are around level 13-15 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "Os monstros são de nível 13-15, mais ou menos, e {b}no Forever eles reaparecem muito mais rápido, então você precisa estar bem acima do nível deles{/b}, senão eles vão continuar reaparecendo bem em cima de você.",
  ["Mining route in Westfall"] = "Rota de mineração no Cerro Oeste",
  ["This is the best if you prefer mining the normal way, but you might have more competition from other players because this is a popular area. The route goes around a Horde town, so I'm not sure how it works for Alliance. I think you can probably avoid the guards, but I only tested this one with a Horde character."] = "Esta é a melhor se você preferir minerar do jeito normal, mas pode haver mais concorrência de outros jogadores, porque é uma área popular. A rota contorna uma cidade da Horda, então não sei como funciona para a Aliança. Acho que provavelmente dá para evitar os guardas, mas só testei esta com um personagem da Horda.",
  ["Mining route in Hillsbrad Foothills"] = "Rota de mineração no Contraforte de Eira dos Montes",
  ["The mobs are around level 22-26 here, so it's best to farm here if you are above those levels. But the respawn rate is fast."] = "Os monstros aqui são de nível 22-26, então é melhor coletar aqui se você estiver acima desses níveis. Mas o reaparecimento é rápido.",
  ["Mining route in The Barrens"] = "Rota de mineração nos Sertões",
  ["A very straightforward route that is easy to follow. This is the best if you prefer mining the normal way, but you might have more competition from other players because this is a popular area."] = "Uma rota bem direta e fácil de seguir. Esta é a melhor se você preferir minerar do jeito normal, mas pode haver mais concorrência de outros jogadores, porque é uma área popular.",
  ["Mining route in Ashenvale"] = "Rota de mineração no Vale Gris",
  ["This route might not work if more than one player is leveling Mining there, because when I tested it there were very few people around. But this place usually has fewer people, so I think it's a good alternative if you don't want to level in caves. The only downside is that sometimes an Iron Deposit spawns instead of a Tin Vein, and you can't mine it yet."] = "Esta rota pode não funcionar se mais de um jogador estiver subindo Mineração ali, porque quando a testei havia pouquíssima gente por perto. Mas este lugar costuma ter menos gente, então acho uma boa alternativa se você não quiser subir em cavernas. A única desvantagem é que às vezes surge um Depósito de Ferro no lugar de um Veio de Estanho, e você ainda não pode minerá-lo.",
  ["Mining route in Stonetalon Mountains"] = "Rota de mineração na Cordilheira das Torres de Pedra",
  ["From this point the guide follows the standard Classic Mining routes. The beta cap was 30, so I couldn't properly test Arathi and Desolace. I'll revise this section once I level my character higher on live, but the main change is the ore respawn rate, so most routes should work and you can probably take shorter routes in most zones."] = "A partir daqui o guia segue as rotas padrão de Mineração do Classic. O nível máximo do beta era 30, então não consegui testar direito Arathi e Desolação. Vou revisar esta seção quando subir meu personagem no servidor oficial, mas a principal mudança é a velocidade de reaparecimento dos minérios, então a maioria das rotas deve funcionar e provavelmente dá para fazer rotas mais curtas na maioria das zonas.",
  ["{b}Visit your trainer and learn Expert Mining{/b}, it requires Mining 125."] = "{b}Visite seu instrutor e aprenda Mineração Especialista{/b}; exige Mineração 125.",
  ["Smelting Iron and Gold (optional)"] = "Fundindo Ferro e Ouro (opcional)",
  ["If you want to save some time and have the gold, buy around 20 {i:2772:inv_ore_iron_01:Iron Ore} and make {s:3307:inv_ingot_iron:Smelt Iron} until 135 before you head out mining. After 135 it rarely gives a point, so don't count on reaching 140."] = "Se quiser economizar tempo e tiver o ouro, compre cerca de 20 {i:2772:inv_ore_iron_01:Iron Ore} e faça {s:3307:inv_ingot_iron:Smelt Iron} até 135 antes de sair para minerar. Depois de 135 raramente dá ponto, então não conte com chegar a 140.",
  ["At 155 you can learn {s:3308:inv_ingot_03:Smelt Gold} from your trainer. It gives a point every time until 170, so around 22 Gold Ore takes you from 155 to 175 and you can start on Mithril right away. I recommend checking the price of Gold Ore and Gold Bar first."] = "Em 155 você pode aprender {s:3308:inv_ingot_03:Smelt Gold} com seu instrutor. Dá ponto toda vez até 170, então cerca de 22 Minérios de Ouro levam você de 155 a 175 e você pode começar o Mithril logo em seguida. Recomendo conferir antes o preço do Minério de Ouro e da Barra de Ouro.",
  ["If you have a {b}lower level character{/b} around level 30, stick to the {b}Thousand Needles{/b} route, that's the safest. If you have a {b}higher level character or a mount{/b} already, I recommend {b}Arathi Highlands{/b}."] = "Se você tiver um {b}personagem de nível mais baixo{/b}, por volta do nível 30, fique na rota de {b}Mil Agulhas{/b}, que é a mais segura. Se já tiver um {b}personagem de nível mais alto ou uma montaria{/b}, recomendo o {b}Planalto Arathi{/b}.",
  ["Ores in these zones: {i:2772:inv_ore_iron_01:Iron Ore}, {i:2771:inv_ore_tin_01:Tin Ore}, {i:2776:inv_ore_gold_01:Gold Ore}"] = "Minérios nestas zonas: {i:2772:inv_ore_iron_01:Iron Ore}, {i:2771:inv_ore_tin_01:Tin Ore}, {i:2776:inv_ore_gold_01:Gold Ore}",
  ["Iron Deposits need Mining 125 and Gold Veins 155."] = "Depósitos de Ferro exigem Mineração 125 e Veios de Ouro, 155.",
  ["Arathi Highlands"] = "Planalto Arathi",
  ["Thousand Needles"] = "Mil Agulhas",
  ["Desolace"] = "Desolação",
  ["There are 4 caves marked with red circles on the map. Make sure to go all the way to the end of each cave because you won't see all the mining veins from the entrance."] = "Há 4 cavernas marcadas com círculos vermelhos no mapa. Vá até o fim de cada caverna, porque da entrada você não vê todos os veios.",
  ["Low level players should skip all 4 caves, and low level Alliance players should take a detour and go south of Hammerfall!"] = "Jogadores de nível baixo devem pular as 4 cavernas, e jogadores da Aliança de nível baixo devem fazer um desvio e passar ao sul de Queda do Martelo!",
  ["Mining route in Arathi Highlands"] = "Rota de mineração no Planalto Arathi",
  ["Mining route in Thousand Needles"] = "Rota de mineração em Mil Agulhas",
  ["Mining route in Desolace"] = "Rota de mineração em Desolação",
  ["To train past 225, visit your trainer and learn Artisan Mining, it requires Mining 200."] = "Para treinar acima de 225, visite seu instrutor e aprenda Mineração Artesão; exige Mineração 200.",
  ["Ores in these zones: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}"] = "Minérios nestas zonas: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}",
  ["Mithril Deposits need Mining 175 and Truesilver Deposits 230."] = "Depósitos de Mithril exigem Mineração 175 e Depósitos de Veraprata, 230.",
  ["The Hinterlands"] = "Terras Agrestes",
  ["The red route should be skipped by lower level players because the area is filled with level 62 elites. Lower level players might also want to consider skipping the cave marked with a red circle on the map. (depends on your gear/class)"] = "Jogadores de nível mais baixo devem pular a rota vermelha, porque a área está cheia de elites de nível 62. Jogadores de nível mais baixo também podem pensar em pular a caverna marcada com um círculo vermelho no mapa. (depende do seu equipamento/classe)",
  ["Mining route in The Hinterlands"] = "Rota de mineração nas Terras Agrestes",
  ["Players below level 60 should skip the 4 caves marked with red circles."] = "Jogadores abaixo do nível 60 devem pular as 4 cavernas marcadas com círculos vermelhos.",
  ["Mining route in Tanaris"] = "Rota de mineração em Tanaris",
  ["Ores in these zones: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}, {i:10620:inv_ore_thorium_02:Thorium Ore}"] = "Minérios nestas zonas: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}, {i:10620:inv_ore_thorium_02:Thorium Ore}",
  ["Small Thorium Veins need Mining 245."] = "Veios Pequenos de Tório exigem Mineração 245.",
  ["Un'Goro Crater"] = "Cratera Un'Goro",
  ["Blasted Lands"] = "Barreira do Inferno",
  ["Felwood"] = "Selva Maleva",
  ["You will find 2-3 veins in the two caves marked with red circles on the map."] = "Você encontra 2-3 veios nas duas cavernas marcadas com círculos vermelhos no mapa.",
  ["Lower level players should probably skip the cave to the south. It really depends on your level, gear and class."] = "Jogadores de nível mais baixo provavelmente devem pular a caverna ao sul. Depende muito do seu nível, equipamento e classe.",
  ["Mining route in Un'Goro Crater"] = "Rota de mineração na Cratera Un'Goro",
  ["Both caves marked with red circles have a lot of mobs inside, so I only recommend this zone to level 60 players with good gear, or to Druids and Rogues with stealth."] = "As duas cavernas marcadas com círculos vermelhos têm muitos monstros lá dentro, então só recomendo esta zona para jogadores de nível 60 com bom equipamento, ou para Druidas e Ladinos com furtividade.",
  ["It's really hard to navigate inside the Garrison Armory mine, so I included a small map. {b}Alliance{/b} players can't mine inside the Garrison Armory!"] = "É bem difícil se orientar dentro da mina do Arsenal da Guarnição, então incluí um pequeno mapa. Jogadores da {b}Aliança{/b} não podem minerar dentro do Arsenal da Guarnição!",
  ["Mining route in the Blasted Lands"] = "Rota de mineração na Barreira do Inferno",
  ["There are usually 2 veins inside the cave marked with a red circle. It's worth going in because the cave is small and there aren't many mobs inside, and if you are high level, you can pass some of them without aggro."] = "Normalmente há 2 veios dentro da caverna marcada com um círculo vermelho. Vale a pena entrar, porque a caverna é pequena e não tem muitos monstros, e se você tiver nível alto, pode passar por alguns deles sem chamar atenção.",
  ["I recommend skipping the other two caves at Jaedenar, especially Shadow Hold. (if you have stealth, they might be worth going into)"] = "Recomendo pular as outras duas cavernas em Jaedenar, principalmente o Bastião das Sombras. (se você tiver furtividade, talvez valha a pena entrar)",
  ["Mining route in Felwood"] = "Rota de mineração na Selva Maleva",
  ["Ores in these zones: {i:10620:inv_ore_thorium_02:Thorium Ore}, {i:3858:inv_ore_mithril_02:Mithril Ore}"] = "Minérios nestas zonas: {i:10620:inv_ore_thorium_02:Thorium Ore}, {i:3858:inv_ore_mithril_02:Mithril Ore}",
  ["At 275 you can mine Rich Thorium Veins too."] = "Em 275 você também pode minerar Veios Abundantes de Tório.",
  ["Eastern Plaguelands"] = "Terras Pestilentas Orientais",
  ["Winterspring"] = "Hibérnia",
  ["Burning Steppes"] = "Estepes Ardentes",
  ["Almost the same as the previous Un'Goro route, but now it includes Rich Thorium Veins."] = "Quase igual à rota anterior de Un'Goro, mas agora inclui Veios Abundantes de Tório.",
  ["Mining route with Rich Thorium Veins in Un'Goro Crater"] = "Rota de mineração com Veios Abundantes de Tório na Cratera Un'Goro",
  ["The red line is full of level 57-58 elites, so if your gear is bad, you should probably skip that part unless you have stealth. With some practice you can usually get through and only pull a few of them."] = "A linha vermelha está cheia de elites de nível 57-58, então se seu equipamento for fraco, provavelmente é melhor pular essa parte, a menos que tenha furtividade. Com um pouco de prática, normalmente dá para passar puxando só alguns deles.",
  ["Mining route in the Eastern Plaguelands"] = "Rota de mineração nas Terras Pestilentas Orientais",
  ["The mobs in this cave are not that hard, so most classes can clear it. (depends on your gear)"] = "Os monstros desta caverna não são tão difíceis, então a maioria das classes consegue limpá-la. (depende do seu equipamento)",
  ["Most classes can get into at least the first part of the cave without pulling aggro. You can try going deeper depending on your gear."] = "A maioria das classes consegue entrar pelo menos na primeira parte da caverna sem chamar atenção. Você pode tentar ir mais fundo, dependendo do seu equipamento.",
  ["A lot of elites patrol this gorge, but you can usually pass most of them without pulling aggro. Sometimes you have to kill 1 or 2."] = "Muitos elites patrulham este desfiladeiro, mas normalmente dá para passar pela maioria deles sem chamar atenção. Às vezes você precisa matar 1 ou 2.",
  ["I don't recommend this area for most players because it's hard to farm here without dying. It really depends on your class and how good you are at avoiding mobs."] = "Não recomendo esta área para a maioria dos jogadores, porque é difícil coletar aqui sem morrer. Depende muito da sua classe e de quão bom você é em evitar monstros.",
  ["Mining route in Winterspring"] = "Rota de mineração em Hibérnia",
  ["The two caves marked with red circles are full of level 50 mobs, so lower level players might want to skip them. (depends on your gear and level)"] = "As duas cavernas marcadas com círculos vermelhos estão cheias de monstros de nível 50, então jogadores de nível mais baixo podem querer pulá-las. (depende do seu equipamento e nível)",
  ["Mining route in the Burning Steppes"] = "Rota de mineração nas Estepes Ardentes",
  ["This WoW Forever Herbalism leveling guide will show you the fastest way to level Herbalism from 1 to 300. You will also find a route map for every zone, every trainer location and where to train Herbalism past 75, 150 and 225."] = "Este guia de Herborismo do WoW Forever mostra a forma mais rápida de subir Herborismo de 1 a 300. Você também encontra um mapa de rota para cada zona, a localização de todos os instrutores e onde treinar Herborismo acima de 75, 150 e 225.",
  ["Below you will find the Herbalism trainers by starting zone and capital city, and the best zones to pick herbs in for every skill range. Herbalism goes well with Alchemy because you can use the herbs you pick to make potions and elixirs, so check out my Forever Alchemy leveling guide if you want to level Alchemy. But keep in mind, this guide is made to level Herbalism as fast as possible, so sometimes the herbs you pick are not the best ones for Alchemy."] = "Abaixo você encontra os instrutores de Herborismo por zona inicial e capital, e as melhores zonas para colher ervas em cada faixa de perícia. Herborismo combina bem com Alquimia, porque você pode usar as ervas que colhe para fazer poções e elixires, então confira meu guia de Alquimia do Forever se quiser subir Alquimia. Mas lembre-se: este guia foi feito para subir Herborismo o mais rápido possível, então às vezes as ervas que você colhe não são as melhores para Alquimia.",
  ["WoW Forever added a couple of new herbs, seeds and recipes. You can check them out here:"] = "O WoW Forever adicionou algumas ervas, sementes e receitas novas. Você pode conferi-las aqui:",
  ["Herbalism Trainer Locations"] = "Localização dos instrutores de Herborismo",
  ["Every capital city has a Herbalism trainer. You can also ask a guard where the herbalist is, then it will be marked with a red flag on your map."] = "Toda capital tem um instrutor de Herborismo. Você também pode perguntar a um guarda onde fica o herborista, e ele será marcado com uma bandeira vermelha no seu mapa.",
  ["Undercity: {n:0:horde:Martha Alliestar}"] = "Cidade Baixa: {n:0:horde:Martha Alliestar}",
  ["Thunder Bluff: {n:0:horde:Komin Winterhoof}"] = "Penhasco do Trovão: {n:0:horde:Komin Winterhoof}",
  ["{n:0:horde:Zor'la} in the Valley of Trials (only up to 75) {n:0:horde:Mishiki} in Sen'jin Village"] = "{n:0:horde:Zor'la} no Vale das Provações (só até 75) {n:0:horde:Mishiki} na Vila Sen'jin",
  ["{n:0:horde:Garan Sunstrider} in Camp Narache (only up to 75) {n:0:horde:Komin Winterhoof} in Thunder Bluff"] = "{n:0:horde:Garan Sunstrider} no Acampamento Narache (só até 75) {n:0:horde:Komin Winterhoof} em Penhasco do Trovão",
  ["{n:0:horde:Florence Nightshade} in Deathknell (only up to 75) {n:0:horde:Faruza} in Brill"] = "{n:0:horde:Florence Nightshade} em Plangemortis (só até 75) {n:0:horde:Faruza} em Montalvo",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} as your reward, it teaches you Herbalism. The trainers on the island are {n:0::Syriel Nightrain} in Valanaar and {n:0::Halassa Fernbreeze} in Shen'dar Village."] = "Não há instrutor em Thendal Village, onde você começa, mas você não precisa de um. {q:93552::Harvesting Windstones} é uma das primeiras missões que você recebe em Thendal Village. Escolha {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} como recompensa; ele ensina Herborismo. Os instrutores da ilha são {n:0::Syriel Nightrain} em Valanaar e {n:0::Halassa Fernbreeze} em Shen'dar Village.",
  ["Stormwind City: {n:0:alliance:Tannysa}"] = "Ventobravo: {n:0:alliance:Tannysa}",
  ["Ironforge: {n:0:alliance:Reyna Stonebranch}"] = "Altaforja: {n:0:alliance:Reyna Stonebranch}",
  ["{n:0:alliance:Nancy Songflower} (only up to 75) {n:0:alliance:Herbalist Pomeroy}"] = "{n:0:alliance:Nancy Songflower} (só até 75) {n:0:alliance:Herbalist Pomeroy}",
  ["{n:0:alliance:Emrys Flintbeard} (only up to 75) {n:0:alliance:Reyna Stonebranch} in Ironforge"] = "{n:0:alliance:Emrys Flintbeard} (só até 75) {n:0:alliance:Reyna Stonebranch} em Altaforja",
  ["{n:0:alliance:Eleyna Duskbreeze} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Malorne Bladeleaf} in Dolanaar"] = "{n:0:alliance:Eleyna Duskbreeze} em Aldrassil, no Vale Umbroso (só até 75) {n:0:alliance:Malorne Bladeleaf} em Dolanaar",
  ["You can find every Herbalism trainer for Horde and Alliance on my WoW Forever Herbalism Trainers page."] = "Você encontra todos os instrutores de Herborismo da Horda e da Aliança na minha página de instrutores de Herborismo do WoW Forever.",
  ["Track Herbs on Your Minimap"] = "Rastreie ervas no minimapa",
  ["You can only track one thing at a time, so {b}you can't track herbs and minerals together{/b}."] = "Você só pode rastrear uma coisa por vez, então {b}não dá para rastrear ervas e minérios ao mesmo tempo{/b}.",
  ["You learn {s:2383:inv_misc_flower_02:Find Herbs} together with Herbalism, but it's not turned on by default:"] = "Você aprende {s:2383:inv_misc_flower_02:Find Herbs} junto com Herborismo, mas não vem ativado por padrão:",
  ["Click Find Herbs in the Herbalism box. {b}I recommend dragging it to your action bar, close to the buffs you use after you die.{/b} This way you make a habit out of it and you are less likely to forget it."] = "Clique em Encontrar Ervas no quadro de Herborismo. {b}Recomendo arrastá-lo para a sua barra de ações, perto dos bônus que você usa depois de morrer.{/b} Assim você cria o hábito e tem menos chance de esquecer.",
  ["The Find Herbs buff shows up next to your minimap. {b}Your tracking turns off every time you die, so don't forget to turn it back on!{/b}"] = "O bônus Encontrar Ervas aparece ao lado do minimapa. {b}O rastreamento desliga toda vez que você morre, então não se esqueça de ligá-lo de novo!{/b}",
  ["Herbalism Skill Bonuses"] = "Bônus de perícia de Herborismo",
  ["You don't need these, but they help when you are stuck between two herbs. With +5 you can pick Kingsblood from 120 instead of 125, so you can move on earlier."] = "Você não precisa deles, mas ajudam quando você está preso entre duas ervas. Com +5 você pode colher Sangue-real a partir de 120 em vez de 125, então pode avançar mais cedo.",
  ["Herbalism"] = "Herborismo",
  ["A world drop, check the Auction House"] = "Um drop do mundo; confira a casa de leilões",
  ["Henry Stern in Razorfen Downs teaches the recipe, it {b}requires Cooking 175{/b}. Take the left path at the start of the instance and go all the way to the end, to the stables, knock down the walls and talk to him."] = "Henry Stern, no Urzal dos Mortos, ensina a receita, que {b}exige Culinária 175{/b}. Pegue o caminho da esquerda no início da instância e vá até o fim, até os estábulos, derrube as paredes e fale com ele.",
  ["can be very handy when you find a herb you can't pick yet and you are only a few points short. It will probably be pretty expensive early on because of the Goldthorn prices, but it's worth keeping a few with you while you level Herbalism."] = "pode ser muito útil quando você encontra uma erva que ainda não pode colher e está a poucos pontos de distância. Provavelmente vai ser bem caro no começo por causa dos preços do Espinheira-dourada, mas vale a pena levar alguns com você enquanto sobe Herborismo.",
  ["Every starting zone is full of herbs, so it doesn't really matter which one you choose. The respawn rate is so fast that without a mount you often can't even finish a full lap, you just run around in circles and pick the herbs as you see them."] = "Toda zona inicial está cheia de ervas, então não importa muito qual você escolher. O reaparecimento é tão rápido que, sem montaria, muitas vezes você nem consegue terminar uma volta completa: você só anda em círculos e colhe as ervas conforme as vê.",
  ["Herbs in these zones: {i:2447:inv_misc_flower_02:Peacebloom}, {i:765:inv_misc_herb_10:Silverleaf}, {i:2449:inv_misc_herb_07:Earthroot}"] = "Ervas nestas zonas: {i:2447:inv_misc_flower_02:Peacebloom}, {i:765:inv_misc_herb_10:Silverleaf}, {i:2449:inv_misc_herb_07:Earthroot}",
  ["Earthroot requires Herbalism 15."] = "Raiz-da-terra exige Herborismo 15.",
  ["Herbalism route in Durotar"] = "Rota de Herborismo em Durotar",
  ["Herbalism route in Mulgore"] = "Rota de Herborismo em Mulgore",
  ["Herbalism route in Tirisfal Glades"] = "Rota de Herborismo nas Clareiras de Tirisfal",
  ["{q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} as your reward, it teaches you Herbalism."] = "{q:93552::Harvesting Windstones} é uma das primeiras missões que você recebe em Thendal Village. Escolha {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} como recompensa; ele ensina Herborismo.",
  ["Herbalism route on Zephras Isle"] = "Rota de Herborismo em Zephras Isle",
  ["Herbalism route in Elwynn Forest"] = "Rota de Herborismo na Floresta de Elwynn",
  ["Herbalism route in Dun Morogh"] = "Rota de Herborismo em Dun Morogh",
  ["Herbalism route in Teldrassil"] = "Rota de Herborismo em Teldrassil",
  ["Visit your trainer and learn Journeyman Herbalism, it requires Herbalism 50. The new Junior Herbalism Trainers in the starting areas won't teach you Journeyman Herbalism."] = "Visite seu instrutor e aprenda Herborismo Artífice; exige Herborismo 50. Os novos Instrutores Júnior de Herborismo nas áreas iniciais não ensinam Herborismo Artífice.",
  ["Herbs in these zones: {i:785:inv_jewelry_talisman_03:Mageroyal}, {i:2450:inv_misc_root_01:Briarthorn}, {i:3820:inv_misc_herb_11:Stranglekelp}"] = "Ervas nestas zonas: {i:785:inv_jewelry_talisman_03:Mageroyal}, {i:2450:inv_misc_root_01:Briarthorn}, {i:3820:inv_misc_herb_11:Stranglekelp}",
  ["Stranglekelp requires Herbalism 85, so you can't pick it right away."] = "Alga-estranguladora exige Herborismo 85, então você não pode colhê-la logo de cara.",
  ["The respawn rate in the lower part of Silverpine Forest is fast enough that you can basically run in small circles in the marked area. I tested this without a mount, so with a mount it might be different, but then running up and down the main road to the loop should work fine as well."] = "O reaparecimento na parte de baixo da Floresta de Pinhaprata é rápido o bastante para você basicamente correr em pequenos círculos na área marcada. Testei isto sem montaria; com montaria pode ser diferente, mas aí correr para cima e para baixo pela estrada principal até o circuito também deve funcionar bem.",
  ["Herbalism route in Silverpine Forest"] = "Rota de Herborismo na Floresta de Pinhaprata",
  ["A very easy route to follow, but there might be a bit fewer herbs than in Darkshore."] = "Uma rota muito fácil de seguir, mas pode haver um pouco menos de ervas que na Costa Negra.",
  ["Herbalism route in Loch Modan"] = "Rota de Herborismo em Loch Modan",
  ["Darkshore has herbs everywhere. I used this loop, but you can also expand it to the upper part of the map. The respawn rate is fast, so you can do smaller circles in different areas. I just found this route pretty easy and chill to follow."] = "A Costa Negra tem ervas por todo lado. Usei este circuito, mas você também pode estendê-lo para a parte de cima do mapa. O reaparecimento é rápido, então você pode fazer círculos menores em áreas diferentes. Só achei esta rota bem fácil e tranquila de seguir.",
  ["Herbalism route in Darkshore"] = "Rota de Herborismo na Costa Negra",
  ["To train past 150, visit your trainer and learn Expert Herbalism, it requires Herbalism 125."] = "Para treinar acima de 150, visite seu instrutor e aprenda Herborismo Especialista; exige Herborismo 125.",
  ["Herbs in these zones: {i:2453:inv_misc_herb_01:Bruiseweed}, {i:3355:inv_misc_flower_01:Wild Steelbloom}, {i:3820:inv_misc_herb_11:Stranglekelp}, {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}"] = "Ervas nestas zonas: {i:2453:inv_misc_herb_01:Bruiseweed}, {i:3355:inv_misc_flower_01:Wild Steelbloom}, {i:3820:inv_misc_herb_11:Stranglekelp}, {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}",
  ["Kingsblood requires Herbalism 125 and Liferoot 150, so you can't pick them right away."] = "Sangue-real exige Herborismo 125 e Raiz-da-vida, 150, então você não pode colhê-las logo de cara.",
  ["Running this loop in Hillsbrad Foothills gives the herbs enough time to respawn, but I tested it without a mount, so with a mount it might be different."] = "Fazer este circuito no Contraforte de Eira dos Montes dá tempo suficiente para as ervas reaparecerem, mas testei sem montaria; com montaria pode ser diferente.",
  ["Herbalism route in Hillsbrad Foothills"] = "Rota de Herborismo no Contraforte de Eira dos Montes",
  ["All three areas are good here:"] = "As três áreas aqui são boas:",
  ["The mobs here are only around level 14-15, so this is the lowest level area where you can safely farm these herbs."] = "Os monstros aqui são só de nível 14-15, mais ou menos, então esta é a área de nível mais baixo onde você pode coletar estas ervas com segurança.",
  ["A good alternative if someone is already farming the first area. The mobs are higher level here, around 25."] = "Uma boa alternativa se alguém já estiver coletando na primeira área. Os monstros aqui são de nível mais alto, por volta de 25.",
  ["This area is usually pretty crowded and full of mobs. {b}I only recommend it if you are over 125 already{/b}, because there is more Kingsblood here."] = "Esta área costuma estar bem cheia de gente e de monstros. {b}Só a recomendo se você já estiver acima de 125{/b}, porque aqui há mais Sangue-real.",
  ["Herbalism route in Stonetalon Mountains"] = "Rota de Herborismo na Cordilheira das Torres de Pedra",
  ["From this point the guide follows the standard Classic Herbalism routes. The beta cap was 30, so I couldn't test the higher level routes. I'll revise this section once I level my character higher on live, but the main change is the herb respawn rate, so most routes should work."] = "A partir daqui o guia segue as rotas padrão de Herborismo do Classic. O nível máximo do beta era 30, então não consegui testar as rotas de nível mais alto. Vou revisar esta seção quando subir meu personagem no servidor oficial, mas a principal mudança é a velocidade de reaparecimento das ervas, então a maioria das rotas deve funcionar.",
  ["Herbs in these zones: {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}, {i:3818:inv_misc_herb_12:Fadeleaf}, {i:3821:inv_misc_herb_15:Goldthorn}, {i:3358:inv_misc_herb_08:Khadgar's Whisker}"] = "Ervas nestas zonas: {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}, {i:3818:inv_misc_herb_12:Fadeleaf}, {i:3821:inv_misc_herb_15:Goldthorn}, {i:3358:inv_misc_herb_08:Khadgar's Whisker}",
  ["Khadgar's Whisker requires Herbalism 185, so you can't pick it right away."] = "Bigode-de-Khadgar exige Herborismo 185, então você não pode colhê-lo logo de cara.",
  ["Stranglethorn Vale"] = "Selva do Espinhaço",
  ["Herbalism route in Stranglethorn Vale"] = "Rota de Herborismo na Selva do Espinhaço",
  ["Herbalism route in Arathi Highlands"] = "Rota de Herborismo no Planalto Arathi",
  ["{b}Learn Artisan Herbalism before you leave for these zones{/b}, it requires Herbalism 200. There is no trainer in Tanaris or Searing Gorge, so if you skip it, you have to fly back at 225."] = "{b}Aprenda Herborismo Artesão antes de partir para estas zonas{/b}; exige Herborismo 200. Não há instrutor em Tanaris nem na Garganta Abrasadora, então se você pular isso, vai ter que voar de volta em 225.",
  ["Herbs in these zones: {i:8831:inv_misc_herb_17:Purple Lotus}, {i:4625:inv_misc_herb_19:Firebloom}"] = "Ervas nestas zonas: {i:8831:inv_misc_herb_17:Purple Lotus}, {i:4625:inv_misc_herb_19:Firebloom}",
  ["Searing Gorge"] = "Garganta Abrasadora",
  ["Herbalism route in Tanaris"] = "Rota de Herborismo em Tanaris",
  ["Herbalism route in Searing Gorge"] = "Rota de Herborismo na Garganta Abrasadora",
  ["Herbs in The Hinterlands: {i:8838:inv_misc_herb_18:Sungrass}, {i:8831:inv_misc_herb_17:Purple Lotus}, {i:8845:inv_mushroom_08:Ghost Mushroom}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}"] = "Ervas nas Terras Agrestes: {i:8838:inv_misc_herb_18:Sungrass}, {i:8831:inv_misc_herb_17:Purple Lotus}, {i:8845:inv_mushroom_08:Ghost Mushroom}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}",
  ["I marked a cave with a red X, there are a lot of Ghost Mushrooms in the cave, but you can only pick them with Herbalism 245."] = "Marquei uma caverna com um X vermelho. Há muitos Cogumelos-fantasma nela, mas você só pode colhê-los com Herborismo 245.",
  ["Herbalism route in The Hinterlands"] = "Rota de Herborismo nas Terras Agrestes",
  ["Herbs in Felwood: {i:8838:inv_misc_herb_18:Sungrass}, {i:8846:inv_misc_herb_16:Gromsblood}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}, {i:13463:inv_misc_herb_dreamfoil:Dreamfoil}, {i:13465:inv_misc_herb_mountainsilversage:Mountain Silversage}, {i:13466:inv_misc_herb_plaguebloom:Plaguebloom}"] = "Ervas na Selva Maleva: {i:8838:inv_misc_herb_18:Sungrass}, {i:8846:inv_misc_herb_16:Gromsblood}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}, {i:13463:inv_misc_herb_dreamfoil:Dreamfoil}, {i:13465:inv_misc_herb_mountainsilversage:Mountain Silversage}, {i:13466:inv_misc_herb_plaguebloom:Plaguebloom}",
  ["Herbalism route in Felwood"] = "Rota de Herborismo na Selva Maleva",
  ["This WoW Forever Skinning leveling guide will show you the fastest way to level Skinning from 1 to 300. You will also find every trainer location and the best places to skin for each skill range."] = "Este guia de Esfolamento do WoW Forever mostra a forma mais rápida de subir Esfolamento de 1 a 300. Você também encontra a localização de todos os instrutores e os melhores lugares para esfolar em cada faixa de perícia.",
  ["This guide is aimed at higher level players who want to switch their profession, but it's good for lower level players too. Leveling Skinning is easy but really boring, you will have to run around and skin hundreds of mobs. Skinning goes well with Leatherworking because you can use the leather you skin, so check out my Forever Leatherworking leveling guide if you want to level Leatherworking."] = "Este guia é voltado para jogadores de nível mais alto que querem trocar de profissão, mas também serve para jogadores de nível mais baixo. Subir Esfolamento é fácil, mas bem chato: você vai ter que correr por aí e esfolar centenas de monstros. Esfolamento combina bem com Couraria, porque você pode usar o couro que esfola, então confira meu guia de Couraria do Forever se quiser subir Couraria.",
  ["Skinning Trainer Locations"] = "Localização dos instrutores de Esfolamento",
  ["Every capital city has a Skinning trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "Toda capital tem um instrutor de Esfolamento. Você também pode perguntar a um guarda, e ele será marcado com uma bandeira vermelha no seu mapa.",
  ["Undercity: {n:0:horde:Killian Hagey}"] = "Cidade Baixa: {n:0:horde:Killian Hagey}",
  ["Thunder Bluff: {n:0:horde:Mooranta}"] = "Penhasco do Trovão: {n:0:horde:Mooranta}",
  ["{n:0:horde:Kagil} in the Valley of Trials (only up to 75) {n:0:horde:Thuwd} in Orgrimmar"] = "{n:0:horde:Kagil} no Vale das Provações (só até 75) {n:0:horde:Thuwd} em Orgrimmar",
  ["{n:0:horde:Nawka Wildsong} in Camp Narache (only up to 75) {n:0:horde:Yonn Deepcut} in Bloodhoof Village"] = "{n:0:horde:Nawka Wildsong} no Acampamento Narache (só até 75) {n:0:horde:Yonn Deepcut} na Aldeia Casco Sangrento",
  ["{n:0:horde:Margaret Weaver} in Deathknell (only up to 75) {n:0:horde:Rand Rhobart} in Tirisfal Glades"] = "{n:0:horde:Margaret Weaver} em Plangemortis (só até 75) {n:0:horde:Rand Rhobart} nas Clareiras de Tirisfal",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247846:inv_10_specialization_professionbook_skinning_color1:Pelt Collecting for Beginners} as your reward, it teaches you Skinning. The trainers on the island are {n:0::Ishlee Breezewhisper} in Valanaar and {n:0::Mendalass Tattermend} in Shen'dar Village."] = "Não há instrutor em Thendal Village, onde você começa, mas você não precisa de um. {q:93552::Harvesting Windstones} é uma das primeiras missões que você recebe em Thendal Village. Escolha {i:247846:inv_10_specialization_professionbook_skinning_color1:Pelt Collecting for Beginners} como recompensa; ele ensina Esfolamento. Os instrutores da ilha são {n:0::Ishlee Breezewhisper} em Valanaar e {n:0::Mendalass Tattermend} em Shen'dar Village.",
  ["Stormwind City: {n:0:alliance:Maris Granger}"] = "Ventobravo: {n:0:alliance:Maris Granger}",
  ["Ironforge: {n:0:alliance:Balthus Stoneflayer}"] = "Altaforja: {n:0:alliance:Balthus Stoneflayer}",
  ["{n:0:alliance:Riley Peltskinner} in Northshire Valley (only up to 75) {n:0:alliance:Helene Peltskinner} in Goldshire"] = "{n:0:alliance:Riley Peltskinner} no Vale de Vila Norte (só até 75) {n:0:alliance:Helene Peltskinner} em Vila d'Ouro",
  ["{n:0:alliance:Brighid Stormflayer} (only up to 75) {n:0:alliance:Balthus Stoneflayer} in Ironforge"] = "{n:0:alliance:Brighid Stormflayer} (só até 75) {n:0:alliance:Balthus Stoneflayer} em Altaforja",
  ["{n:0:alliance:Terunne Bearshaper} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Radnaal Maneweaver} in Teldrassil"] = "{n:0:alliance:Terunne Bearshaper} em Aldrassil, no Vale Umbroso (só até 75) {n:0:alliance:Radnaal Maneweaver} em Teldrassil",
  ["You can find every Skinning trainer for Horde and Alliance on my WoW Forever Skinning Trainers page."] = "Você encontra todos os instrutores de Esfolamento da Horda e da Aliança na minha página de instrutores de Esfolamento do WoW Forever.",
  ["Skinning Skill Requirements"] = "Requisitos de perícia de Esfolamento",
  ["You need 5 times the mob's level in Skinning to skin it, so a level 30 mob needs Skinning 150. Below level 20 it's less, if you follow the guide you don't have to worry about this."] = "Você precisa de 5 vezes o nível do monstro em Esfolamento para esfolá-lo, então um monstro de nível 30 exige Esfolamento 150. Abaixo do nível 20 é menos; se você seguir o guia, não precisa se preocupar com isso.",
  ["Mob level"] = "Nível do monstro",
  ["Skinning needed"] = "Esfolamento necessário",
  ["10 for a level 11 mob, 10 more for every level (level 15 needs 50, level 19 needs 90)"] = "10 para um monstro de nível 11, mais 10 para cada nível (nível 15 exige 50, nível 19 exige 90)",
  ["20 and up"] = "20 ou mais",
  ["5 times the level"] = "5 vezes o nível",
  ["If you enchant your gloves with {s:13698:spell_holy_greaterheal:Enchant Gloves - Skinning}, you can skin mobs 1 level higher than normal."] = "Se você encantar suas luvas com {s:13698:spell_holy_greaterheal:Enchant Gloves - Skinning}, pode esfolar monstros 1 nível acima do normal.",
  ["Horde players can also pick the {i:269716:inv_weapon_shortblade_05:Keen Skinning Knife} (+3 Skinning) as a reward from Unwelcome Guests in The Barrens."] = "Jogadores da Horda também podem escolher a {i:269716:inv_weapon_shortblade_05:Keen Skinning Knife} (+3 em Esfolamento) como recompensa de Unwelcome Guests, nos Sertões.",
  ["In WoW Forever you can skin the mobs in the starting areas, and they give skill points all the way up to 75."] = "No WoW Forever você pode esfolar os monstros das áreas iniciais, e eles dão pontos de perícia até 75.",
  ["{b}Any starting zone is good{/b} for this. If you are leveling a new character, you can skin any mob in your starting zone, so you don't need a recommendation until around level 10, when you leave the zone. The two places below are for players who already have a higher level character and want to catch up on Skinning. A lot of players will be leveling new characters there, so there is always something to skin."] = "{b}Qualquer zona inicial serve{/b} para isso. Se você estiver subindo um personagem novo, pode esfolar qualquer monstro da sua zona inicial, então não precisa de recomendação até mais ou menos o nível 10, quando sai da zona. Os dois lugares abaixo são para jogadores que já têm um personagem de nível mais alto e querem recuperar o atraso em Esfolamento. Muitos jogadores estarão subindo personagens novos ali, então sempre há algo para esfolar.",
  ["{b}Don't forget to buy a {i:7005:inv_weapon_shortblade_01:Skinning Knife}!{/b} The Leatherworking Supply vendors near your trainer and most General Goods vendors sell it. You don't have to equip it, but you can't skin without one in your bags."] = "{b}Não se esqueça de comprar uma {i:7005:inv_weapon_shortblade_01:Skinning Knife}!{/b} Os vendedores de suprimentos de Couraria perto do seu instrutor e a maioria dos vendedores de mercadorias gerais a vendem. Você não precisa equipá-la, mas não consegue esfolar sem uma nas bolsas.",
  ["Skin the {n:3098::Mottled Boars} in the Valley of Trials in Durotar."] = "Esfole os {n:3098::Mottled Boars} no Vale das Provações, em Durotar.",
  ["{b}Mob level:{/b} 1-2"] = "{b}Nível dos monstros:{/b} 1-2",
  ["The Mottled Boars in the Valley of Trials in Durotar"] = "Os Javalis Malhados no Vale das Provações, em Durotar",
  ["Skin the {n:299::Young Wolves} and {n:69::Timber Wolves} in Northshire Valley in Elwynn Forest."] = "Esfole os {n:299::Young Wolves} e os {n:69::Timber Wolves} no Vale de Vila Norte, na Floresta de Elwynn.",
  ["The wolves in Northshire Valley in Elwynn Forest"] = "Os lobos no Vale de Vila Norte, na Floresta de Elwynn",
  ["Visit your trainer and learn Journeyman Skinning if you haven't yet, it requires Skinning 50. The new Junior Skinning Trainers in the starting areas won't teach you Journeyman Skinning."] = "Visite seu instrutor e aprenda Esfolamento Artífice se ainda não tiver aprendido; exige Esfolamento 50. Os novos Instrutores Júnior de Esfolamento nas áreas iniciais não ensinam Esfolamento Artífice.",
  ["To train past 150, visit your trainer again and learn Expert Skinning when you reach 125."] = "Para treinar acima de 150, visite seu instrutor de novo e aprenda Esfolamento Especialista quando chegar a 125.",
  ["Kill and skin {n:3256::Sunscale Scytheclaw}, {n:3426::Zhevra Charger}, {n:3245::Ornery Plainstrider}."] = "Mate e esfole {n:3256::Sunscale Scytheclaw}, {n:3426::Zhevra Charger}, {n:3245::Ornery Plainstrider}.",
  ["Go to the small raptor camp just west of Northwatch Hold. Skin the level 16-17 ones until 80, from 80 you can skin the level 18 ones too. Stay here until 150, the last 10 points are green but the respawn is fast."] = "Vá até o pequeno acampamento de raptores logo a oeste da Fortaleza Vigianorte. Esfole os de nível 16-17 até 80; a partir de 80 você também pode esfolar os de nível 18. Fique aqui até 150; os últimos 10 pontos ficam verdes, mas o reaparecimento é rápido.",
  ["{b}Mob level:{/b} 16-18"] = "{b}Nível dos monstros:{/b} 16-18",
  ["The Sunscale Scytheclaws west of Northwatch Hold in the Barrens"] = "Os Gadanhas Escama-solar a oeste da Fortaleza Vigianorte, nos Sertões",
  ["Kill and skin {n:1192::Elder Mountain Boar}, {n:1189::Black Bear Patriarch}."] = "Mate e esfole {n:1192::Elder Mountain Boar}, {n:1189::Black Bear Patriarch}.",
  ["{n:1693::Loch Crocolisk} are also skinnable, make sure to pull them when you get to the shore."] = "{n:1693::Loch Crocolisk} também podem ser esfolados, então puxe-os quando chegar à margem.",
  ["Stay here until around 125, then head north to the Wetlands, it is on the way to Hillsbrad."] = "Fique aqui até mais ou menos 125, depois siga para o norte até o Pantanal, que fica no caminho para Eira dos Montes.",
  ["{b}Mob level:{/b} 16-17"] = "{b}Nível dos monstros:{/b} 16-17",
  ["Skinning spot in Loch Modan"] = "Local de esfolamento em Loch Modan",
  ["125-150 Wetlands"] = "125-150 Pantanal",
  ["Kill and skin {n:1022::Mottled Scytheclaw}, {n:1023::Mottled Razormaw}."] = "Mate e esfole {n:1022::Mottled Scytheclaw}, {n:1023::Mottled Razormaw}.",
  ["There are always a few of them at Whelgar's Excavation Site, so you never run out of mobs to kill."] = "Sempre há alguns deles no Sítio de Escavação de Whelgar, então nunca faltam monstros para matar.",
  ["{b}Mob level:{/b} 25-27"] = "{b}Nível dos monstros:{/b} 25-27",
  ["Whelgar's Excavation Site in the Wetlands"] = "Sítio de Escavação de Whelgar, no Pantanal",
  ["From 150, go to the Foothill Caverns in Hillsbrad Foothills, the yeti cave on the border of Alterac Mountains, or to the Rotting Orchard in Duskwood."] = "A partir de 150, vá para as Cavernas do Contraforte no Contraforte de Eira dos Montes, a caverna dos yetis na divisa com as Montanhas de Alterac, ou para o Pomar Podre no Bosque do Corvo.",
  ["Duskwood"] = "Bosque do Corvo",
  ["Both factions can get there, Horde from Tarren Mill and Alliance from Southshore."] = "As duas facções podem chegar lá: a Horda pela Serraria Tarren e a Aliança pela Costa Sul.",
  ["Kill and skin {n:2248::Cave Yeti}, {n:2249::Ferocious Yeti}."] = "Mate e esfole {n:2248::Cave Yeti}, {n:2249::Ferocious Yeti}.",
  ["The yetis respawn so fast that you can stay inside the cave the whole time."] = "Os yetis reaparecem tão rápido que você pode ficar dentro da caverna o tempo todo.",
  ["{b}Mob level:{/b} 30-32"] = "{b}Nível dos monstros:{/b} 30-32",
  ["The Foothill Caverns in Hillsbrad Foothills"] = "As Cavernas do Contraforte no Contraforte de Eira dos Montes",
  ["Duskwood is an Alliance zone, but Grom'gol is close, so Horde players can get there too."] = "O Bosque do Corvo é uma zona da Aliança, mas Grom'gol fica perto, então jogadores da Horda também podem chegar lá.",
  ["Kill and skin {n:898::Nightbane Worgen}, {n:533::Nightbane Shadow Weaver}, {n:205::Nightbane Dark Runner}."] = "Mate e esfole {n:898::Nightbane Worgen}, {n:533::Nightbane Shadow Weaver}, {n:205::Nightbane Dark Runner}.",
  ["Start at the area marked with 1, clear the mobs outside and inside Roland's Doom cave, then go to the Rotting Orchard until the mobs respawn."] = "Comece na área marcada com 1, limpe os monstros do lado de fora e dentro da caverna Ruína de Roland, depois vá para o Pomar Podre até os monstros reaparecerem.",
  ["{b}Mob level:{/b} 26-29"] = "{b}Nível dos monstros:{/b} 26-29",
  ["Roland's Doom and the Rotting Orchard in Duskwood"] = "A Ruína de Roland e o Pomar Podre no Bosque do Corvo",
  ["Visit your trainer and learn Artisan Skinning, it requires Skinning 200."] = "Visite seu instrutor e aprenda Esfolamento Artesão; exige Esfolamento 200.",
  ["Mount up and go to the yeti cave at Feral Scar Vale in the south of Feralas. Both factions can get there, Horde from Camp Mojache and Alliance from Feathermoon Stronghold."] = "Monte e vá até a caverna dos yetis no Vale da Cicatriz Feral, no sul de Feralas. As duas facções podem chegar lá: a Horda pelo Acampamento Mojache e a Aliança pela Fortaleza Plumaluna.",
  ["Kill and skin {n:5292::Feral Scar Yeti}, {n:5295::Enraged Feral Scar}, {n:5293::Hulking Feral Scar}."] = "Mate e esfole {n:5292::Feral Scar Yeti}, {n:5295::Enraged Feral Scar}, {n:5293::Hulking Feral Scar}.",
  ["{b}Mob level:{/b} 43-46"] = "{b}Nível dos monstros:{/b} 43-46",
  ["The yeti cave at Feral Scar Vale in Feralas"] = "A caverna dos yetis no Vale da Cicatriz Feral, em Feralas",
  ["From 280, fly to Marshal's Refuge and skin the dinosaurs in the western part of Un'Goro Crater."] = "A partir de 280, voe até o Refúgio do Marechal e esfole os dinossauros na parte oeste da Cratera Un'Goro.",
  ["Kill and skin {n:9163::Diemetradon}, {n:9166::Pterrordax}, {n:9164::Elder Diemetradon}, {n:9167::Frenzied Pterrordax}."] = "Mate e esfole {n:9163::Diemetradon}, {n:9166::Pterrordax}, {n:9164::Elder Diemetradon}, {n:9167::Frenzied Pterrordax}.",
  ["{b}Mob level:{/b} 50-55"] = "{b}Nível dos monstros:{/b} 50-55",
  ["The dinosaur area in the west of Un'Goro Crater"] = "A área dos dinossauros no oeste da Cratera Un'Goro",
  ["This WoW Forever Fishing and Cooking leveling guide will show you the fastest way to level Fishing and Cooking together from 1 to 300."] = "Este guia de Pesca e Culinária do WoW Forever mostra a forma mais rápida de subir Pesca e Culinária juntas de 1 a 300.",
  ["Leveling Fishing takes a long time, so it's best to level these two together, because every fish you catch is also a Cooking recipe and your Cooking goes up for free while you fish. You will still need a lot of patience because you have to catch a lot of fish to get from start to finish. If you only want one of them, use my Fishing guide or my Cooking guide instead."] = "Subir Pesca leva muito tempo, então é melhor subir as duas juntas, porque todo peixe que você pesca também é uma receita de Culinária, e sua Culinária sobe de graça enquanto você pesca. Você ainda vai precisar de muita paciência, porque precisa pescar muitos peixes do começo ao fim. Se quiser só uma delas, use meu guia de Pesca ou meu guia de Culinária.",
  ["Level Fishing to 75"] = "Suba Pesca até 75",
  ["If you can choose, {b}level Fishing in Mulgore{/b}, because everything is close together there. {n:0::Harn Longcast} in Bloodhoof Village sells both recipes and the pole, and the Fishing trainer stands at Stonebull Lake. Thunder Bluff, where you fish after 75, is right next to it."] = "Se puder escolher, {b}suba Pesca em Mulgore{/b}, porque ali fica tudo perto. {n:0::Harn Longcast}, na Aldeia Casco Sangrento, vende as duas receitas e a vara, e o instrutor de Pesca fica no Lago Touro de Pedra. Penhasco do Trovão, onde você pesca depois de 75, fica logo ao lado.",
  ["If you haven't learned Fishing yet, learn it from {n:0::Lau'Tiki} on the coast south of Sen'jin Village."] = "Se ainda não aprendeu Pesca, aprenda com {n:0::Lau'Tiki} na costa ao sul da Vila Sen'jin.",
  ["Buy {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} from {n:0::Zansoa} in Sen'jin Village. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Compre {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} com {n:0::Zansoa} na Vila Sen'jin. Compre também uma {i:6256:inv_fishingpole_02:Fishing Pole} e uma {i:6529:inv_misc_orb_03:Shiny Bauble} ali. (Compre qualquer {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que encontrar e guarde para depois.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish on the coast next to {n:0::Lau'Tiki}, south of Sen'jin Village, until your Fishing skill reaches 75. Almost everything you catch there is {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}, about 70 of them."] = "Equipe sua vara de pescar, prenda uma {i:6529:inv_misc_orb_03:Shiny Bauble} e pesque na costa ao lado de {n:0::Lau'Tiki}, ao sul da Vila Sen'jin, até sua perícia em Pesca chegar a 75. Quase tudo o que você pesca ali é {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}, cerca de 70.",
  ["Learn Journeyman Fishing from {n:0::Lau'Tiki}, it requires level 10."] = "Aprenda Pesca Artífice com {n:0::Lau'Tiki}; exige nível 10.",
  ["The coast south of Sen'jin Village in Durotar, where to fish from 1 to 75"] = "A costa ao sul da Vila Sen'jin, em Durotar, onde pescar de 1 a 75",
  ["If you haven't learned Fishing yet, learn it from {n:0::Uthan Stillwater} at Stonebull Lake."] = "Se ainda não aprendeu Pesca, aprenda com {n:0::Uthan Stillwater} no Lago Touro de Pedra.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Harn Longcast} in Bloodhoof Village. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Compre {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} e {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} com {n:0::Harn Longcast} na Aldeia Casco Sangrento. Compre também uma {i:6256:inv_fishingpole_02:Fishing Pole} e uma {i:6529:inv_misc_orb_03:Shiny Bauble} ali. (Compre qualquer {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que encontrar e guarde para depois.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Stonebull Lake until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Equipe sua vara de pescar, prenda uma {i:6529:inv_misc_orb_03:Shiny Bauble} e pesque no Lago Touro de Pedra até sua perícia em Pesca chegar a 75. Você vai pescar cerca de 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} e 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Uthan Stillwater}, it requires level 10."] = "Aprenda Pesca Artífice com {n:0::Uthan Stillwater}; exige nível 10.",
  ["Stonebull Lake around Bloodhoof Village in Mulgore, where to fish from 1 to 75"] = "O Lago Touro de Pedra, perto da Aldeia Casco Sangrento, em Mulgore, onde pescar de 1 a 75",
  ["If you haven't learned Fishing yet, learn it from {n:0::Clyde Kellen} at Brightwater Lake."] = "Se ainda não aprendeu Pesca, aprenda com {n:0::Clyde Kellen} no Lago Águas Claras.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Martine Tramblay} at the Death's Watch Waystation, south-east of Brill. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Compre {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} com {n:0::Martine Tramblay} no Posto de Vigília da Morte, a sudeste de Montalvo. Compre também uma {i:6256:inv_fishingpole_02:Fishing Pole} e uma {i:6529:inv_misc_orb_03:Shiny Bauble} ali. (Compre qualquer {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que encontrar e guarde para depois.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Brightwater Lake until your Fishing skill reaches 75. You will catch about 30 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 20 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, plus some {i:6299:inv_misc_fish_28:Sickly Looking Fish} and junk."] = "Equipe sua vara de pescar, prenda uma {i:6529:inv_misc_orb_03:Shiny Bauble} e pesque no Lago Águas Claras até sua perícia em Pesca chegar a 75. Você vai pescar cerca de 30 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} e 20 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, além de alguns {i:6299:inv_misc_fish_28:Sickly Looking Fish} e lixo.",
  ["Learn Journeyman Fishing from {n:0::Clyde Kellen}, it requires level 10."] = "Aprenda Pesca Artífice com {n:0::Clyde Kellen}; exige nível 10.",
  ["Brightwater Lake east of Brill in Tirisfal Glades, where to fish from 1 to 75"] = "O Lago Águas Claras, a leste de Montalvo, nas Clareiras de Tirisfal, onde pescar de 1 a 75",
  ["If you haven't learned Fishing yet, learn it from {n:0::Fenn Fairweather} in Shen'dar Village or {n:0::Baelann Swiftcurrent} in Valanaar."] = "Se ainda não aprendeu Pesca, aprenda com {n:0::Fenn Fairweather} em Shen'dar Village ou {n:0::Baelann Swiftcurrent} em Valanaar.",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} from {n:0::Belandiel Farflight} in Shen'dar Village or {n:0::Baelann Swiftcurrent} in Valanaar. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Compre uma {i:6256:inv_fishingpole_02:Fishing Pole} e uma {i:6529:inv_misc_orb_03:Shiny Bauble} com {n:0::Belandiel Farflight} em Shen'dar Village ou {n:0::Baelann Swiftcurrent} em Valanaar. (Compre qualquer {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que encontrar e guarde para depois.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in any lake or river on Zephras Isle until your Fishing skill reaches 75, for example next to the Fishing trainers in Shen'dar Village and Valanaar. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}. Keep all the fish you catch."] = "Equipe sua vara de pescar, prenda uma {i:6529:inv_misc_orb_03:Shiny Bauble} e pesque em qualquer lago ou rio de Zephras Isle até sua perícia em Pesca chegar a 75, por exemplo ao lado dos instrutores de Pesca em Shen'dar Village e Valanaar. Você vai pescar cerca de 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} e 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}. Guarde todos os peixes que pescar.",
  ["Learn Journeyman Fishing from {n:0::Fenn Fairweather} or {n:0::Baelann Swiftcurrent}, it requires level 10."] = "Aprenda Pesca Artífice com {n:0::Fenn Fairweather} ou {n:0::Baelann Swiftcurrent}; exige nível 10.",
  ["When you get to Thunder Bluff, buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Sewa Mistrunner} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Naal Mistrunner}. They stand next to each other."] = "Quando chegar a Penhasco do Trovão, compre {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} com {n:0::Sewa Mistrunner} e {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} com {n:0::Naal Mistrunner}. Eles ficam um ao lado do outro.",
  ["The water at Shen'dar Village and Valanaar on Zephras Isle, where to fish from 1 to 75"] = "A água em Shen'dar Village e Valanaar, em Zephras Isle, onde pescar de 1 a 75",
  ["If you can choose, {b}level Fishing in Elwynn Forest{/b}, because everything is close together there. {n:0::Tharynn Bouden} in Goldshire sells both recipes and the pole, and the Fishing trainer stands at Crystal Lake. Stormwind City, where you fish after 75, is right next to it."] = "Se puder escolher, {b}suba Pesca na Floresta de Elwynn{/b}, porque ali fica tudo perto. {n:0::Tharynn Bouden}, em Vila d'Ouro, vende as duas receitas e a vara, e o instrutor de Pesca fica no Lago de Cristal. Ventobravo, onde você pesca depois de 75, fica logo ao lado.",
  ["If you haven't learned Fishing yet, learn it from {n:0::Lee Brown} at Crystal Lake."] = "Se ainda não aprendeu Pesca, aprenda com {n:0::Lee Brown} no Lago de Cristal.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Tharynn Bouden} in Goldshire. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Compre {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} e {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} com {n:0::Tharynn Bouden} em Vila d'Ouro. Compre também uma {i:6256:inv_fishingpole_02:Fishing Pole} e uma {i:6529:inv_misc_orb_03:Shiny Bauble} ali. (Compre qualquer {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que encontrar e guarde para depois.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Crystal Lake, east of Goldshire, until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Equipe sua vara de pescar, prenda uma {i:6529:inv_misc_orb_03:Shiny Bauble} e pesque no Lago de Cristal, a leste de Vila d'Ouro, até sua perícia em Pesca chegar a 75. Você vai pescar cerca de 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} e 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Lee Brown}, it requires level 10."] = "Aprenda Pesca Artífice com {n:0::Lee Brown}; exige nível 10.",
  ["Crystal Lake east of Goldshire in Elwynn Forest, where to fish from 1 to 75"] = "O Lago de Cristal, a leste de Vila d'Ouro, na Floresta de Elwynn, onde pescar de 1 a 75",
  ["If you haven't learned Fishing yet, learn it from {n:0::Paxton Ganter} at Iceflow Lake."] = "Se ainda não aprendeu Pesca, aprenda com {n:0::Paxton Ganter} no Lago Fluxo de Gelo.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Gretta Ganter} at Iceflow Lake. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Compre {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} com {n:0::Gretta Ganter} no Lago Fluxo de Gelo. Compre também uma {i:6256:inv_fishingpole_02:Fishing Pole} e uma {i:6529:inv_misc_orb_03:Shiny Bauble} ali. (Compre qualquer {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que encontrar e guarde para depois.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Iceflow Lake until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Equipe sua vara de pescar, prenda uma {i:6529:inv_misc_orb_03:Shiny Bauble} e pesque no Lago Fluxo de Gelo até sua perícia em Pesca chegar a 75. Você vai pescar cerca de 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} e 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Paxton Ganter}, it requires level 10."] = "Aprenda Pesca Artífice com {n:0::Paxton Ganter}; exige nível 10.",
  ["Iceflow Lake in Dun Morogh, where to fish from 1 to 75"] = "O Lago Fluxo de Gelo, em Dun Morogh, onde pescar de 1 a 75",
  ["Learn Fishing from {n:0::Astaia} in Darnassus. There is no Fishing trainer in Dolanaar."] = "Aprenda Pesca com {n:0::Astaia} em Darnassus. Não há instrutor de Pesca em Dolanaar.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Nyoma} in Dolanaar."] = "Compre {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} e {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} com {n:0::Nyoma} em Dolanaar.",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} from {n:0::Narret Shadowgrove} in Dolanaar. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Compre uma {i:6256:inv_fishingpole_02:Fishing Pole} e uma {i:6529:inv_misc_orb_03:Shiny Bauble} com {n:0::Narret Shadowgrove} em Dolanaar. (Compre qualquer {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que encontrar e guarde para depois.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Lake Al'Ameth, south of Dolanaar, until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Equipe sua vara de pescar, prenda uma {i:6529:inv_misc_orb_03:Shiny Bauble} e pesque no Lago Al'Ameth, ao sul de Dolanaar, até sua perícia em Pesca chegar a 75. Você vai pescar cerca de 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} e 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Astaia} in Darnassus, it requires level 10."] = "Aprenda Pesca Artífice com {n:0::Astaia} em Darnassus; exige nível 10.",
  ["Lake Al'Ameth south of Dolanaar in Teldrassil, where to fish from 1 to 75"] = "O Lago Al'Ameth, ao sul de Dolanaar, em Teldrassil, onde pescar de 1 a 75",
  ["When you get to Stormwind City, buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Tharynn Bouden} in Goldshire, right outside the city."] = "Quando chegar a Ventobravo, compre {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} e {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} com {n:0::Tharynn Bouden} em Vila d'Ouro, logo fora da cidade.",
  ["Fishing (75-130) and Cooking (1-100)"] = "Pesca (75-130) e Culinária (1-100)",
  ["Fishing"] = "Pesca",
  ["Fish in the capital city closest to you until your Fishing skill reaches 130. From 75 no fish gets away in any of them. You should catch about 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Pesque na capital mais próxima de você até sua perícia em Pesca chegar a 130. A partir de 75, nenhum peixe escapa em nenhuma delas. Você deve pescar cerca de 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} e 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["{b}Thunder Bluff:{/b} the pond near the Auction House."] = "{b}Penhasco do Trovão:{/b} a lagoa perto da casa de leilões.",
  ["{b}Undercity:{/b} the canals. About a third of what you catch here is junk, so you get fewer fish."] = "{b}Cidade Baixa:{/b} os canais. Cerca de um terço do que você pesca aqui é lixo, então você consegue menos peixes.",
  ["{b}Orgrimmar:{/b} the pond in the Valley of Honor, where the Fishing trainer stands."] = "{b}Orgrimmar:{/b} a lagoa no Vale da Honra, onde fica o instrutor de Pesca.",
  ["Recipes to buy"] = "Receitas para comprar",
  ["Buy {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} from {n:0::Naal Mistrunner} in Thunder Bluff or {n:0::Ronald Burch} in Undercity, you need it in the next part."] = "Compre {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} com {n:0::Naal Mistrunner} em Penhasco do Trovão ou {n:0::Ronald Burch} na Cidade Baixa; você vai precisar dela na próxima parte.",
  ["If you don't have {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} yet, buy it from {n:0::Naal Mistrunner} in Thunder Bluff or {n:0::Lizbeth Cromwell} in Undercity."] = "Se ainda não tiver {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}, compre com {n:0::Naal Mistrunner} em Penhasco do Trovão ou {n:0::Lizbeth Cromwell} na Cidade Baixa.",
  ["Nobody sells them in Orgrimmar, so buy them on the Auction House or in Thunder Bluff."] = "Ninguém as vende em Orgrimmar, então compre-as na casa de leilões ou em Penhasco do Trovão.",
  ["Cooking"] = "Culinária",
  ["If you haven't learned Cooking yet, learn it from {n:0::Aska Mistrunner} in Thunder Bluff, {n:0::Eunice Burch} in Undercity or {n:0::Zamja} in Orgrimmar. Then learn {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and cook all your {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} into {s:7751:inv_misc_fish_07:Brilliant Smallfish}. If you caught {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel} in your starting zone, learn {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} and cook them into {s:7752:inv_misc_fish_24:Slitherskin Mackerel} instead. This should take your Cooking skill to 50."] = "Se ainda não aprendeu Culinária, aprenda com {n:0::Aska Mistrunner} em Penhasco do Trovão, {n:0::Eunice Burch} na Cidade Baixa ou {n:0::Zamja} em Orgrimmar. Depois aprenda {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} e cozinhe todos os seus {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} em {s:7751:inv_misc_fish_07:Brilliant Smallfish}. Se você pescou {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel} na sua zona inicial, aprenda {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} e cozinhe-os em {s:7752:inv_misc_fish_24:Slitherskin Mackerel}. Isso deve levar sua perícia em Culinária a 50.",
  ["If you are a few points short of 50, catch and cook a few more."] = "Se ficar alguns pontos abaixo de 50, pesque e cozinhe mais alguns.",
  ["Learn Journeyman Cooking from the same trainer. Then learn {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} and cook all your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Your Cooking skill should go above 100."] = "Aprenda Culinária Artífice com o mesmo instrutor. Depois aprenda {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} e cozinhe todos os seus {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} em {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Sua perícia em Culinária deve passar de 100.",
  ["Don't worry if you don't reach 100 Cooking with Longjaw Mud Snapper, you will catch more Raw Longjaw Mud Snapper later."] = "Não se preocupe se não chegar a 100 em Culinária com o Lutjano-de-mandíbula-longa; você vai pescar mais Lutjanos-de-mandíbula-longa crus depois.",
  ["Fish in the canals of Stormwind City until your skill reaches 130. You should catch about 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, and 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Pesque nos canais de Ventobravo até sua perícia chegar a 130. Você deve pescar cerca de 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} e 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["Find {n:0::Catherine Leland} in Stormwind City and buy {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}. If you don't have {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} yet, buy it from {n:0::Tharynn Bouden} in Goldshire."] = "Encontre {n:0::Catherine Leland} em Ventobravo e compre {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}. Se ainda não tiver {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}, compre com {n:0::Tharynn Bouden} em Vila d'Ouro.",
  ["You should also find {n:0::Ben Trias} and buy 20 {i:8932:inv_misc_food_37:Alterac Swiss} from him. You will need these later for the Artisan Cooking quest."] = "Você também deve encontrar {n:0::Ben Trias} e comprar 20 {i:8932:inv_misc_food_37:Alterac Swiss} com ele. Você vai precisar deles depois para a missão de Culinária Artesão.",
  ["Learn Cooking from {n:0::Stephen Ryback} if you haven't yet. Then learn {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and cook all your {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} into {s:7751:inv_misc_fish_07:Brilliant Smallfish}. This should take your Cooking skill to 50."] = "Aprenda Culinária com {n:0::Stephen Ryback} se ainda não aprendeu. Depois aprenda {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} e cozinhe todos os seus {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} em {s:7751:inv_misc_fish_07:Brilliant Smallfish}. Isso deve levar sua perícia em Culinária a 50.",
  ["Learn Journeyman Cooking from {n:0::Stephen Ryback} in Stormwind City. Then learn {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} and cook all your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Your Cooking skill should go above 100."] = "Aprenda Culinária Artífice com {n:0::Stephen Ryback} em Ventobravo. Depois aprenda {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} e cozinhe todos os seus {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} em {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Sua perícia em Culinária deve passar de 100.",
  ["Fishing (130-205) and Cooking (100-175)"] = "Pesca (130-205) e Culinária (100-175)",
  ["Expert Fishing needs {b}level 20{/b} and {b}Fishing 125{/b}, Expert Cooking needs {b}Cooking 125{/b}."] = "Pesca Especialista exige {b}nível 20{/b} e {b}Pesca 125{/b}; Culinária Especialista exige {b}Culinária 125{/b}.",
  ["Booty Bay"] = "Angra do Butim",
  ["Go to Ratchet in The Barrens and take the boat to Booty Bay in Stranglethorn Vale."] = "Vá até Vila Catraca, nos Sertões, e pegue o barco para a Angra do Butim, na Selva do Espinhaço.",
  ["Find {n:0::Old Man Heming} in Booty Bay, buy {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} from him and read it."] = "Encontre {n:0::Old Man Heming} na Angra do Butim, compre {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} com ele e leia.",
  ["Find {n:0::Kelsey Yance} and buy these two recipes: {i:17062:inv_scroll_03:Recipe: Mithril Head Trout}, {i:13941:inv_scroll_03:Recipe: Filet of Redgill}."] = "Encontre {n:0::Kelsey Yance} e compre estas duas receitas: {i:17062:inv_scroll_03:Recipe: Mithril Head Trout}, {i:13941:inv_scroll_03:Recipe: Filet of Redgill}.",
  ["Go back to The Barrens, then fly from Ratchet to Sun Rock Retreat in Stonetalon Mountains and buy 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0::Kulwia}. You need 2 until 150, keep the other 5 for later."] = "Volte para os Sertões, depois voe de Vila Catraca até o Retiro da Rocha do Sol, na Cordilheira das Torres de Pedra, e compre 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} com {n:0::Kulwia}. Você precisa de 2 até 150; guarde os outros 5 para depois.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the open water until your Fishing skill reaches 205. You will catch about 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Prenda uma {i:6530:inv_misc_monstertail_03:Nightcrawler} e pesque em águas abertas até sua perícia em Pesca chegar a 205. Você vai pescar cerca de 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} e 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["Fly to Shadowprey Village in Desolace."] = "Voe até a Aldeia Presa Sombria, em Desolação.",
  ["Find {n:0::Wulan} and buy the {i:16072:inv_misc_book_08:Expert Cookbook}. He is on the top floor of the eastern-most building in the village."] = "Encontre {n:0::Wulan} e compre o {i:16072:inv_misc_book_08:Expert Cookbook}. Ele fica no último andar do prédio mais a leste da aldeia.",
  ["Buy 20 {i:8932:inv_misc_food_37:Alterac Swiss} from {n:0::Innkeeper Sikewa}. You will need them for the Artisan Cooking quest."] = "Compre 20 {i:8932:inv_misc_food_37:Alterac Swiss} com {n:0::Innkeeper Sikewa}. Você vai precisar deles para a missão de Culinária Artesão.",
  ["Leveling Cooking to 175"] = "Subindo Culinária até 175",
  ["Cook your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper} if your Cooking skill is still below 100."] = "Cozinhe seus {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} em {s:7753:inv_misc_fish_32:Longjaw Mud Snapper} se sua perícia em Culinária ainda estiver abaixo de 100.",
  ["{b}Read the {i:16072:inv_misc_book_08:Expert Cookbook} as soon as you reach 125{/b}, especially if you go AFK while cooking. Without it you stop getting skill points at 150 and keep cooking for nothing."] = "{b}Leia o {i:16072:inv_misc_book_08:Expert Cookbook} assim que chegar a 125{/b}, principalmente se você ficar AFK enquanto cozinha. Sem ele, você para de ganhar pontos de perícia em 150 e continua cozinhando à toa.",
  ["Learn {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} and cook all your {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} into {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}. Your Cooking skill will hopefully get close to 175."] = "Aprenda {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} e cozinhe todos os seus {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} em {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}. Com sorte, sua perícia em Culinária vai chegar perto de 175.",
  ["Don't worry if you don't reach 175 Cooking with Bristle Whisker Catfish, you will catch more Raw Bristle Whisker Catfish later."] = "Não se preocupe se não chegar a 175 em Culinária com o Bagre-de-bigode-eriçado; você vai pescar mais Bagres-de-bigode-eriçado crus depois.",
  ["Go to Booty Bay in Stranglethorn Vale."] = "Vá até a Angra do Butim, na Selva do Espinhaço.",
  ["Go to The Barrens, then fly from Ratchet to Astranaar in Ashenvale. Ride south-east to Mystral Lake and buy the {i:16072:inv_misc_book_08:Expert Cookbook} and 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0::Shandrina}. You need 2 until 150, keep the other 5 for later."] = "Vá até os Sertões, depois voe de Vila Catraca até Astranaar, no Vale Gris. Siga a sudeste até o Lago Mystral e compre o {i:16072:inv_misc_book_08:Expert Cookbook} e 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} com {n:0::Shandrina}. Você precisa de 2 até 150; guarde os outros 5 para depois.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the open water of Mystral Lake until your Fishing skill reaches 205. You will catch about 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Prenda uma {i:6530:inv_misc_monstertail_03:Nightcrawler} e pesque em águas abertas do Lago Mystral até sua perícia em Pesca chegar a 205. Você vai pescar cerca de 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} e 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["Artisan Fishing Quest"] = "Missão de Pesca Artesão",
  ["If you have no {i:6530:inv_misc_monstertail_03:Nightcrawlers} left, buy 5 from {n:0::Kilxx} in The Barrens or {n:0:alliance:Helenia Olden} in Dustwallow Marsh."] = "Se não tiver mais {i:6530:inv_misc_monstertail_03:Nightcrawlers}, compre 5 com {n:0::Kilxx} nos Sertões ou {n:0:alliance:Helenia Olden} no Pântano Vadeoso.",
  ["Go to Dustwallow Marsh and {b}fish anywhere in the swamp until your skill reaches 225{/b}. {b}Don't fish in the ocean.{/b} Keep a {i:6530:inv_misc_monstertail_03:Nightcrawler} on your pole until 225, otherwise a few fish get away."] = "Vá até o Pântano Vadeoso e {b}pesque em qualquer lugar do pântano até sua perícia chegar a 225{/b}. {b}Não pesque no oceano.{/b} Mantenha uma {i:6530:inv_misc_monstertail_03:Nightcrawler} na vara até 225; caso contrário, alguns peixes escapam.",
  ["Find {n:0::Nat Pagle} and accept the quest {q:6607::Nat Pagle, Angler Extreme}. It requires {b}level 35{/b} and {b}Fishing 225{/b}, and you need it to learn Artisan Fishing."] = "Encontre {n:0::Nat Pagle} e aceite a missão {q:6607::Nat Pagle, Angler Extreme}. Ela exige {b}nível 35{/b} e {b}Pesca 225{/b}, e você precisa dela para aprender Pesca Artesão.",
  ["Tidefury Cove, Dustwallow Marsh"] = "Enseada da Fúria das Marés, Pântano Vadeoso",
  ["To complete the quest you have to catch 4 quest fish in four different zones:"] = "Para completar a missão, você precisa pescar 4 peixes de missão em quatro zonas diferentes:",
  ["{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Feralas (attach the {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you kept, or {i:6532:inv_misc_gem_variety_02:Bright Baubles} from {n:0::Sheendra Tallgrass} / {n:0::Vivianna} in Feralas, otherwise most of them get away)"] = "{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Feralas (prenda o {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que você guardou, ou {i:6532:inv_misc_gem_variety_02:Bright Baubles} de {n:0::Sheendra Tallgrass} / {n:0::Vivianna} em Feralas; caso contrário, a maioria escapa)",
  ["{i:16970:inv_misc_fish_21:Misty Reed Mahi Mahi} - Swamp of Sorrows"] = "{i:16970:inv_misc_fish_21:Misty Reed Mahi Mahi} - Pântano das Mágoas",
  ["{i:16968:inv_misc_fish_32:Sar'theris Striker} - Desolace"] = "{i:16968:inv_misc_fish_32:Sar'theris Striker} - Desolação",
  ["{i:16969:inv_misc_fish_08:Savage Coast Blue Sailfin} - Stranglethorn Vale"] = "{i:16969:inv_misc_fish_08:Savage Coast Blue Sailfin} - Selva do Espinhaço",
  ["Nat Pagle, Angler Extreme Quest Fishes"] = "Peixes da missão Nat Pagle, Angler Extreme",
  ["Where to catch the four Nat Pagle quest fish"] = "Onde pescar os quatro peixes da missão de Nat Pagle",
  ["Leveling Fishing to 255 and Cooking to 225"] = "Subindo Pesca até 255 e Culinária até 225",
  ["After you completed the quest, {b}keep fishing in the swamp in Dustwallow Marsh until your Fishing skill reaches 255.{/b} {b}Don't fish in the ocean{/b}, because there you catch Raw Rockscale Cod instead of the Raw Mithril Head Trout you cook next."] = "Depois de completar a missão, {b}continue pescando no pântano do Pântano Vadeoso até sua perícia em Pesca chegar a 255.{/b} {b}Não pesque no oceano{/b}, porque ali você pesca Bacalhau Escamarrocha Cru em vez da Truta Cabeça-de-mithril Crua que você vai cozinhar em seguida.",
  ["Go back to Brackenwall Village (Horde) / Theramore Isle (Alliance) to cook your fish, or put down a campfire if you have one."] = "Volte para a Aldeia Muralha de Samambaia (Horda) / Ilha Theramore (Aliança) para cozinhar seus peixes, ou acenda uma fogueira se tiver uma.",
  ["Cook your {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} into {s:7755:inv_misc_fish_30:Bristle Whisker Catfish} if your Cooking skill is still below 175."] = "Cozinhe seus {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} em {s:7755:inv_misc_fish_30:Bristle Whisker Catfish} se sua perícia em Culinária ainda estiver abaixo de 175.",
  ["Learn {i:17062:inv_scroll_03:Recipe: Mithril Head Trout} and cook your {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} into {s:20916:inv_misc_fish_02:Mithril Headed Trout} until 225. Keep the rest, you cook them after the Artisan Cooking quest."] = "Aprenda {i:17062:inv_scroll_03:Recipe: Mithril Head Trout} e cozinhe suas {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} em {s:20916:inv_misc_fish_02:Mithril Headed Trout} até 225. Guarde o resto; você vai cozinhá-las depois da missão de Culinária Artesão.",
  ["Artisan Cooking Quest"] = "Missão de Culinária Artesão",
  ["Fly to Gadgetzan in Tanaris and pick up the quest {q:6610::Clamlette Surprise} from {n:0::Dirge Quikcleave}. The reward is Artisan Cooking. The quest requires {b}level 35{/b} and {b}Cooking 225{/b}. You will need these to complete the quest:"] = "Voe até Geringontzan, em Tanaris, e pegue a missão {q:6610::Clamlette Surprise} com {n:0::Dirge Quikcleave}. A recompensa é Culinária Artesão. A missão exige {b}nível 35{/b} e {b}Culinária 225{/b}. Você vai precisar disto para completá-la:",
  ["12x {i:12207:inv_egg_03:Giant Egg} - dropped by the {n:5428::Rocs}, {n:5429::Fire Rocs} and {n:5430::Searing Rocs} in Tanaris."] = "12x {i:12207:inv_egg_03:Giant Egg} - deixados pelos {n:5428::Rocs}, {n:5429::Fire Rocs} e {n:5430::Searing Rocs} em Tanaris.",
  ["10x {i:7974:inv_misc_food_51:Zesty Clam Meat} - from Big-mouth Clams, dropped by {n:14123::Steeljaw Snappers} and {n:5431::Surf Gliders} in Tanaris."] = "10x {i:7974:inv_misc_food_51:Zesty Clam Meat} - dos Mariscos Bocudos, deixados pelos {n:14123::Steeljaw Snappers} e {n:5431::Surf Gliders} em Tanaris.",
  ["20x {i:8932:inv_misc_food_37:Alterac Swiss} - you bought these earlier."] = "20x {i:8932:inv_misc_food_37:Alterac Swiss} - você já os comprou antes.",
  ["Find {n:0::Gikkix} at Steamwheedle Port in Tanaris and buy {i:13945:inv_scroll_03:Recipe: Nightfin Soup}."] = "Encontre {n:0::Gikkix} no Porto Bondebico, em Tanaris, e compre {i:13945:inv_scroll_03:Recipe: Nightfin Soup}.",
  ["Fishing to 300 in Feralas"] = "Pesca até 300 em Feralas",
  ["Fly to Camp Mojache (Horde) / Feathermoon Stronghold (Alliance) in Feralas."] = "Voe até o Acampamento Mojache (Horda) / Fortaleza Plumaluna (Aliança), em Feralas.",
  ["Buy 12 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0:horde:Sheendra Tallgrass} / {n:0:alliance:Vivianna}."] = "Compre 12 {i:6530:inv_misc_monstertail_03:Nightcrawlers} com {n:0:horde:Sheendra Tallgrass} / {n:0:alliance:Vivianna}.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the marked lake until you reach Fishing 300, use a new one every 10 minutes. Any other lake or river in Feralas works too, {b}except Jademir Lake{/b}."] = "Prenda uma {i:6530:inv_misc_monstertail_03:Nightcrawler} e pesque no lago marcado até chegar a Pesca 300; use uma nova a cada 10 minutos. Qualquer outro lago ou rio de Feralas também serve, {b}exceto o Lago Jademir{/b}.",
  ["Where to fish in Feralas from 255 to 300"] = "Onde pescar em Feralas de 255 a 300",
  ["Leveling Cooking to 300"] = "Subindo Culinária até 300",
  ["Cook your remaining {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} into {s:20916:inv_misc_fish_02:Mithril Headed Trout} until 250."] = "Cozinhe as {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} restantes em {s:20916:inv_misc_fish_02:Mithril Headed Trout} até 250.",
  ["Learn {i:13941:inv_scroll_03:Recipe: Filet of Redgill} and cook your {i:13758:inv_misc_fish_06:Raw Redgill} into {s:18241:inv_misc_fish_06:Filet of Redgill} until 285."] = "Aprenda {i:13941:inv_scroll_03:Recipe: Filet of Redgill} e cozinhe seus {i:13758:inv_misc_fish_06:Raw Redgill} em {s:18241:inv_misc_fish_06:Filet of Redgill} até 285.",
  ["Learn {i:13945:inv_scroll_03:Recipe: Nightfin Soup} and cook all your {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} into {s:18243:inv_drink_17:Nightfin Soup}. You also need a {i:159:inv_drink_07:Refreshing Spring Water} for each soup, buy 20 from the innkeeper."] = "Aprenda {i:13945:inv_scroll_03:Recipe: Nightfin Soup} e cozinhe todos os seus {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} em {s:18243:inv_drink_17:Nightfin Soup}. Você também precisa de uma {i:159:inv_drink_07:Refreshing Spring Water} para cada sopa; compre 20 com o estalajadeiro.",
  ["{i:13759:inv_misc_fish_23:Raw Nightfin Snapper} don't bite in the afternoon (12:00-18:00 game time). If you fished in the afternoon, you will probably not have enough, so cook the rest of your {i:13758:inv_misc_fish_06:Raw Redgill} into {s:18241:inv_misc_fish_06:Filet of Redgill} too, you might reach 300 with them."] = "{i:13759:inv_misc_fish_23:Raw Nightfin Snapper} não morde a isca à tarde (12:00-18:00, horário do jogo). Se você pescou à tarde, provavelmente não vai ter o suficiente, então cozinhe também o resto dos seus {i:13758:inv_misc_fish_06:Raw Redgill} em {s:18241:inv_misc_fish_06:Filet of Redgill}; talvez você chegue a 300 com eles.",
  ["If you still don't reach 300, fish a bit more outside the afternoon, or buy a few {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} on the Auction House."] = "Se ainda assim não chegar a 300, pesque mais um pouco fora do período da tarde, ou compre alguns {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} na casa de leilões.",
  ["This WoW Forever Cooking leveling guide will show you the fastest way to level your Cooking skill from 1 to 300 as cheaply as possible. You will also find every trainer location, how the campfire works in Forever and where to train Cooking past 150 and 225."] = "Este guia de Culinária do WoW Forever mostra a forma mais rápida de subir sua perícia de Culinária de 1 a 300, gastando o mínimo possível. Você também encontra a localização de todos os instrutores, como a fogueira funciona no Forever e onde treinar Culinária acima de 150 e 225.",
  ["Cooking doesn't take up one of your two profession slots, so every character can learn it. Most of the recipes below only need the meat or fish that drops while you level, so the guide lists a few recipes for every skill range and you can make the one you have the ingredients for. If you also want to level Fishing but haven't leveled it yet, use my Fishing and Cooking leveling guide instead:"] = "Culinária não ocupa um dos seus dois espaços de profissão, então todo personagem pode aprendê-la. A maioria das receitas abaixo só precisa da carne ou do peixe que cai enquanto você sobe de nível, então o guia lista algumas receitas para cada faixa de perícia e você pode fazer aquela para a qual tiver os ingredientes. Se também quiser subir Pesca e ainda não a subiu, use meu guia de Pesca e Culinária:",
  ["You need level 35 to go past 225, so I split the list in two. Buy this part first."] = "Você precisa de nível 35 para passar de 225, então dividi a lista em duas. Compre esta parte primeiro.",
  ["The Giant Eggs and the Zesty Clam Meat are for the Artisan Cooking quest."] = "Os Ovos Gigantes e a Carne de Marisco Picante são para a missão de Culinária Artesão.",
  ["Cooking Trainer Locations"] = "Localização dos instrutores de Culinária",
  ["Apprentice Cooking has no level requirement, so you can learn it on a fresh character. Every trainer also teaches Journeyman Cooking, so you don't have to find a different trainer at 50."] = "Culinária Aprendiz não tem requisito de nível, então você pode aprendê-la com um personagem recém-criado. Todo instrutor também ensina Culinária Artífice, então você não precisa procurar outro instrutor em 50.",
  ["Undercity: {n:0:horde:Eunice Burch}"] = "Cidade Baixa: {n:0:horde:Eunice Burch}",
  ["Thunder Bluff: {n:0:horde:Aska Mistrunner}"] = "Penhasco do Trovão: {n:0:horde:Aska Mistrunner}",
  ["Every starting zone has a Cooking trainer, most of them are inside the inn."] = "Toda zona inicial tem um instrutor de Culinária; a maioria fica dentro da estalagem.",
  ["{n:0:horde:Cook Torka} in Razor Hill"] = "{n:0:horde:Cook Torka} no Monte da Navalha",
  ["{n:0:horde:Pyall Silentstride} inside the big tent in Bloodhoof Village"] = "{n:0:horde:Pyall Silentstride} dentro da tenda grande na Aldeia Casco Sangrento",
  ["{n:0:horde:William Pickman} inside the inn in Brill"] = "{n:0:horde:William Pickman} dentro da estalagem de Montalvo",
  ["{n:0::Nyalah Brightfire} in Valanaar, {n:0::Zerril Softbreeze} in Shen'dar Village"] = "{n:0::Nyalah Brightfire} em Valanaar, {n:0::Zerril Softbreeze} em Shen'dar Village",
  ["Stormwind City: {n:0:alliance:Stephen Ryback}"] = "Ventobravo: {n:0:alliance:Stephen Ryback}",
  ["Ironforge: {n:0:alliance:Daryl Riknussun}"] = "Altaforja: {n:0:alliance:Daryl Riknussun}",
  ["{n:0:alliance:Tomas} in the kitchen of the inn in Goldshire"] = "{n:0:alliance:Tomas} na cozinha da estalagem de Vila d'Ouro",
  ["{n:0:alliance:Gremlock Pilsnor} in the Thunderbrew Distillery in Kharanos"] = "{n:0:alliance:Gremlock Pilsnor} na Cervejaria Cervaforte, em Kharanos",
  ["{n:0:alliance:Zarrin} in Dolanaar"] = "{n:0:alliance:Zarrin} em Dolanaar",
  ["You can find every Cooking trainer for Horde and Alliance on my WoW Forever Cooking Trainers page."] = "Você encontra todos os instrutores de Culinária da Horda e da Aliança na minha página de instrutores de Culinária do WoW Forever.",
  ["Campfire"] = "Fogueira",
  ["You need a campfire to cook. There is often one burning next to the Cooking trainer, so look around before you make your own."] = "Você precisa de uma fogueira para cozinhar. Muitas vezes há uma acesa ao lado do instrutor de Culinária, então olhe em volta antes de fazer a sua.",
  ["In Forever the campfire is an item. You learn the {s:1229737:inv_camelot_camping_welcomingcampfire:Basic Campfire Kit} together with Cooking and place the fire from your bags, so you can make a stack of kits in advance. Other players can add their own camp items to your fire, you can read about the whole camping system in my WoW Forever Camping Guide."] = "No Forever a fogueira é um item. Você aprende o {s:1229737:inv_camelot_camping_welcomingcampfire:Basic Campfire Kit} junto com Culinária e coloca a fogueira a partir das bolsas, então pode fazer uma pilha de kits com antecedência. Outros jogadores podem adicionar seus próprios itens de acampamento à sua fogueira; você pode ler sobre todo o sistema de acampamento no meu Guia de Acampamento do WoW Forever.",
  ["To craft the kits you need {i:4470:inv_tradeskillitem_01:Simple Wood} and a {i:4471:inv_stone_11:Flint and Tinder}. The Flint and Tinder is only for crafting the kits, you don't need it to place the fire. Open your faction below to see who sells them near your trainer:"] = "Para criar os kits você precisa de {i:4470:inv_tradeskillitem_01:Simple Wood} e de uma {i:4471:inv_stone_11:Flint and Tinder}. A Pederneira e Isca só serve para criar os kits; você não precisa dela para colocar a fogueira. Abra sua facção abaixo para ver quem os vende perto do seu instrutor:",
  ["{n:0:horde:Xen'to}, next to the trainer"] = "{n:0:horde:Xen'to}, ao lado do instrutor",
  ["{n:0:horde:Ronald Burch}, next to the trainer"] = "{n:0:horde:Ronald Burch}, ao lado do instrutor",
  ["{n:0:horde:Naal Mistrunner}, next to the trainer"] = "{n:0:horde:Naal Mistrunner}, ao lado do instrutor",
  ["{n:0:horde:Jark} in the Razor Hill barracks"] = "{n:0:horde:Jark} no quartel do Monte da Navalha",
  ["{n:0:horde:Moorat Longstride} in Bloodhoof Village"] = "{n:0:horde:Moorat Longstride} na Aldeia Casco Sangrento",
  ["{n:0:horde:Mrs. Winters} in Brill"] = "{n:0:horde:Mrs. Winters} em Montalvo",
  ["{n:0::Antelariaa Cloudgaze} in Valanaar {n:0::Zerril Softbreeze}, the Cooking trainer in Shen'dar Village"] = "{n:0::Antelariaa Cloudgaze} em Valanaar {n:0::Zerril Softbreeze}, o instrutor de Culinária em Shen'dar Village",
  ["{n:0:alliance:Erika Tate}, next to the trainer"] = "{n:0:alliance:Erika Tate}, ao lado do instrutor",
  ["{n:0:alliance:Emrul Riknussun}, next to the trainer"] = "{n:0:alliance:Emrul Riknussun}, ao lado do instrutor",
  ["{n:0:alliance:Fyldan}, next to the trainer"] = "{n:0:alliance:Fyldan}, ao lado do instrutor",
  ["{n:0:alliance:Brog Hamfist} in Goldshire"] = "{n:0:alliance:Brog Hamfist} em Vila d'Ouro",
  ["{n:0:alliance:Kreg Bilmn} in the Thunderbrew Distillery"] = "{n:0:alliance:Kreg Bilmn} na Cervejaria Cervaforte",
  ["{n:0:alliance:Nyoma} in Dolanaar"] = "{n:0:alliance:Nyoma} em Dolanaar",
  ["Apprentice Cooking (1-50)"] = "Culinária Aprendiz (1-50)",
  ["{b}These are sold by Cooking Supply vendors near your trainer, don't buy them from the Auction House:{/b}"] = "{b}Estes são vendidos pelos vendedores de suprimentos de Culinária perto do seu instrutor; não os compre na casa de leilões:{/b}",
  ["Make around 55 from one of these recipes. The two fish are usually the cheapest."] = "Faça cerca de 55 de uma destas receitas. Os dois peixes costumam ser os mais baratos.",
  ["Food"] = "Comida",
  ["Ingredients"] = "Ingredientes",
  ["Recipe Source"] = "Origem da receita",
  ["Mulgore: {n:0:horde:Harn Longcast} Thunder Bluff: {n:0:horde:Sewa Mistrunner} Tirisfal Glades: {n:0:horde:Martine Tramblay} Undercity: {n:0:horde:Lizbeth Cromwell} Dun Morogh: {n:0:alliance:Gretta Ganter} Elwynn Forest: {n:0:alliance:Tharynn Bouden} Loch Modan: {n:0:alliance:Khara Deepwater} Stormwind City: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nyoma}"] = "Mulgore: {n:0:horde:Harn Longcast} Penhasco do Trovão: {n:0:horde:Sewa Mistrunner} Clareiras de Tirisfal: {n:0:horde:Martine Tramblay} Cidade Baixa: {n:0:horde:Lizbeth Cromwell} Dun Morogh: {n:0:alliance:Gretta Ganter} Floresta de Elwynn: {n:0:alliance:Tharynn Bouden} Loch Modan: {n:0:alliance:Khara Deepwater} Ventobravo: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nyoma}",
  ["Durotar: {n:0:horde:Zansoa} Tirisfal Glades: {n:0:horde:Martine Tramblay} Ironforge: {n:0:alliance:Tansy Puddlefizz} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone}"] = "Durotar: {n:0:horde:Zansoa} Clareiras de Tirisfal: {n:0:horde:Martine Tramblay} Altaforja: {n:0:alliance:Tansy Puddlefizz} Teldrassil: {n:0:alliance:Nessa Shadowsong} Cerro Oeste: {n:0:alliance:Kriggon Talsone}",
  ["Trainer"] = "Instrutor",
  ["(Horde only) Make {s:15935:inv_misc_food_46:Crispy Bat Wing} if you have some {i:12223:inv_misc_pelt_bear_ruin_05:Meaty Bat Wing}. The recipe is sold by {n:0:horde:Abigail Shiel} in Tirisfal Glades."] = "(Só Horda) Faça {s:15935:inv_misc_food_46:Crispy Bat Wing} se tiver algumas {i:12223:inv_misc_pelt_bear_ruin_05:Meaty Bat Wing}. A receita é vendida por {n:0:horde:Abigail Shiel} nas Clareiras de Tirisfal.",
  ["(Horde only) Make {s:6413:inv_misc_food_10:Scorpid Surprise} if you have some {i:5466:spell_nature_nullifypoison:Scorpid Stinger}. The recipe is sold by {n:0:horde:Grimtak} in Durotar."] = "(Só Horda) Faça {s:6413:inv_misc_food_10:Scorpid Surprise} se tiver alguns {i:5466:spell_nature_nullifypoison:Scorpid Stinger}. A receita é vendida por {n:0:horde:Grimtak} em Durotar.",
  ["(Alliance only) Make {s:6412:inv_misc_food_68:Kaldorei Spider Kabob} if you have some {i:5465:inv_misc_monsterspidercarapace_01:Small Spider Leg}. The recipe is a reward from {q:4161::Recipe of the Kaldorei}. You can get the quest from {n:0:alliance:Zarrin} in Teldrassil."] = "(Só Aliança) Faça {s:6412:inv_misc_food_68:Kaldorei Spider Kabob} se tiver algumas {i:5465:inv_misc_monsterspidercarapace_01:Small Spider Leg}. A receita é recompensa de {q:4161::Recipe of the Kaldorei}. Você pode pegar a missão com {n:0:alliance:Zarrin} em Teldrassil.",
  ["Journeyman Cooking (50-150)"] = "Culinária Artífice (50-150)",
  ["{b}Visit your trainer again and learn Journeyman Cooking{/b}, it requires Cooking 50."] = "{b}Visite seu instrutor de novo e aprenda Culinária Artífice{/b}; exige Culinária 50.",
  ["{b}Make sure to learn Journeyman Cooking before you start the next part{/b}, especially if you go AFK while cooking. Without it you stop getting skill points at 75 and keep cooking for nothing."] = "{b}Não deixe de aprender Culinária Artífice antes de começar a próxima parte{/b}, principalmente se você ficar AFK enquanto cozinha. Sem ela, você para de ganhar pontos de perícia em 75 e continua cozinhando à toa.",
  ["Make around 55 from any of the recipes below. The two fish are usually the cheapest. {s:8607:inv_misc_food_13:Smoked Bear Meat} turns yellow sooner than the rest, so make more of it, or cook it first if you have more than one type of meat."] = "Faça cerca de 55 de qualquer uma das receitas abaixo. Os dois peixes costumam ser os mais baratos. {s:8607:inv_misc_food_13:Smoked Bear Meat} fica amarela antes das outras, então faça mais dela, ou cozinhe-a primeiro se tiver mais de um tipo de carne.",
  ["Mulgore: {n:0:horde:Harn Longcast} Silverpine Forest: {n:0:horde:Killian Sanatha} Thunder Bluff: {n:0:horde:Naal Mistrunner} Undercity: {n:0:horde:Lizbeth Cromwell} Elwynn Forest: {n:0:alliance:Tharynn Bouden} Ironforge: {n:0:alliance:Tansy Puddlefizz} Loch Modan: {n:0:alliance:Khara Deepwater} Teldrassil: {n:0:alliance:Nyoma}"] = "Mulgore: {n:0:horde:Harn Longcast} Floresta de Pinhaprata: {n:0:horde:Killian Sanatha} Penhasco do Trovão: {n:0:horde:Naal Mistrunner} Cidade Baixa: {n:0:horde:Lizbeth Cromwell} Floresta de Elwynn: {n:0:alliance:Tharynn Bouden} Altaforja: {n:0:alliance:Tansy Puddlefizz} Loch Modan: {n:0:alliance:Khara Deepwater} Teldrassil: {n:0:alliance:Nyoma}",
  ["Durotar: {n:0:horde:Zansoa} Orgrimmar: {n:0:horde:Shankys} Silverpine Forest: {n:0:horde:Killian Sanatha} Undercity: {n:0:horde:Ronald Burch} Darkshore: {n:0:alliance:Heldan Galesong} Stormwind City: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone} Wetlands: {n:0:alliance:Stuart Fleming} The Barrens: {n:0::Kilxx}"] = "Durotar: {n:0:horde:Zansoa} Orgrimmar: {n:0:horde:Shankys} Floresta de Pinhaprata: {n:0:horde:Killian Sanatha} Cidade Baixa: {n:0:horde:Ronald Burch} Costa Negra: {n:0:alliance:Heldan Galesong} Ventobravo: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nessa Shadowsong} Cerro Oeste: {n:0:alliance:Kriggon Talsone} Pantanal: {n:0:alliance:Stuart Fleming} Sertões: {n:0::Kilxx}",
  ["Silverpine Forest: {n:0:horde:Andrew Hilbert} Loch Modan: {n:0:alliance:Drac Roughcut}"] = "Floresta de Pinhaprata: {n:0:horde:Andrew Hilbert} Loch Modan: {n:0:alliance:Drac Roughcut}",
  ["55x {i:5469:inv_misc_food_16:Strider Meat} 55x {i:4536:inv_misc_food_19:Shiny Red Apple} (Vendor)"] = "55x {i:5469:inv_misc_food_16:Strider Meat} 55x {i:4536:inv_misc_food_19:Shiny Red Apple} (vendedor)",
  ["The Barrens: {n:0:horde:Tari'qa} (Horde only) Reward from {q:2178::Easy Strider Living} (Alliance only)"] = "Sertões: {n:0:horde:Tari'qa} (só Horda) Recompensa de {q:2178::Easy Strider Living} (só Aliança)",
  ["Make around 30-35 from one of these two."] = "Faça cerca de 30-35 de uma destas duas.",
  ["30x {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} (buy around 55, you will need 25 more at 130-150)"] = "30x {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} (compre cerca de 55; você vai precisar de mais 25 em 130-150)",
  ["Hillsbrad Foothills: {n:0:horde:Derak Nightfall} Thunder Bluff: {n:0:horde:Naal Mistrunner} Thunder Bluff: {n:0:horde:Sewa Mistrunner} Undercity: {n:0:horde:Ronald Burch} Hillsbrad Foothills: {n:0:alliance:Lindea Rabonne} Stormwind City: {n:0:alliance:Catherine Leland} The Barrens: {n:0::Kilxx}"] = "Contraforte de Eira dos Montes: {n:0:horde:Derak Nightfall} Penhasco do Trovão: {n:0:horde:Naal Mistrunner} Penhasco do Trovão: {n:0:horde:Sewa Mistrunner} Cidade Baixa: {n:0:horde:Ronald Burch} Contraforte de Eira dos Montes: {n:0:alliance:Lindea Rabonne} Ventobravo: {n:0:alliance:Catherine Leland} Sertões: {n:0::Kilxx}",
  ["Stormwind City: {n:0:alliance:Kendor Kabonka} (Alliance only)"] = "Ventobravo: {n:0:alliance:Kendor Kabonka} (só Aliança)",
  ["Make around 20-25 from any of the recipes below."] = "Faça cerca de 20-25 de qualquer uma das receitas abaixo.",
  ["See above"] = "Veja acima",
  ["Stormwind City: {n:0:alliance:Kendor Kabonka} (Alliance) Arathi Highlands: {n:0:horde:Keena} (Horde)"] = "Ventobravo: {n:0:alliance:Kendor Kabonka} (Aliança) Planalto Arathi: {n:0:horde:Keena} (Horda)",
  ["The Barrens: {n:0:horde:Zargh} (Horde only)"] = "Sertões: {n:0:horde:Zargh} (só Horda)",
  ["Expert Cooking (150-225)"] = "Culinária Especialista (150-225)",
  ["To learn Expert Cooking you need to reach Cooking 125, then buy the {i:16072:inv_misc_book_08:Expert Cookbook} from {n:0:horde:Wulan} (Horde) in Desolace at Shadowprey Village or from {n:0:alliance:Shandrina} (Alliance) in Ashenvale at Mystral Lake."] = "Para aprender Culinária Especialista você precisa chegar a Culinária 125 e depois comprar o {i:16072:inv_misc_book_08:Expert Cookbook} com {n:0:horde:Wulan} (Horda) na Aldeia Presa Sombria, em Desolação, ou com {n:0:alliance:Shandrina} (Aliança) no Lago Mystral, no Vale Gris.",
  ["Make around 25-30 from one of these three."] = "Faça cerca de 25-30 de uma destas três.",
  ["You can also keep making {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}, but it's green from 160, so you need around 90 of them for these 25 points."] = "Você também pode continuar fazendo {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}, mas ele fica verde a partir de 160, então você precisa de cerca de 90 para estes 25 pontos.",
  ["Make around 55 from one of these. The Roast Raptor is usually the cheapest."] = "Faça cerca de 55 de uma destas. O Raptor Assado costuma ser o mais barato.",
  ["Arathi Highlands: {n:0:alliance:Hammon Karwn} Arathi Highlands: {n:0:horde:Keena} Dustwallow Marsh: {n:0:horde:Ogg'marr}"] = "Planalto Arathi: {n:0:alliance:Hammon Karwn} Planalto Arathi: {n:0:horde:Keena} Pântano Vadeoso: {n:0:horde:Ogg'marr}",
  ["Ashenvale: {n:0:horde:Wik'Tar} Orgrimmar: {n:0:horde:Shankys} Stranglethorn Vale: {n:0::Kelsey Yance} Undercity: {n:0:horde:Lizbeth Cromwell} Ironforge: {n:0:alliance:Tansy Puddlefizz} Wetlands: {n:0:alliance:Stuart Fleming} Desolace: {n:0:horde:Wulan} Darkshore: {n:0:alliance:Heldan Galesong} Hillsbrad Foothills: {n:0:alliance:Lindea Rabonne}"] = "Vale Gris: {n:0:horde:Wik'Tar} Orgrimmar: {n:0:horde:Shankys} Selva do Espinhaço: {n:0::Kelsey Yance} Cidade Baixa: {n:0:horde:Lizbeth Cromwell} Altaforja: {n:0:alliance:Tansy Puddlefizz} Pantanal: {n:0:alliance:Stuart Fleming} Desolação: {n:0:horde:Wulan} Costa Negra: {n:0:alliance:Heldan Galesong} Contraforte de Eira dos Montes: {n:0:alliance:Lindea Rabonne}",
  ["Reward from a quest in Hillsbrad Foothills NPC: {n:0:horde:Christoph Jeffcoat}, quest: {q:7321::Soothing Turtle Bisque} NPC: {n:0:alliance:Chef Jessen}, quest: {q:555::Soothing Turtle Bisque}"] = "Recompensa de uma missão no Contraforte de Eira dos Montes PNJ: {n:0:horde:Christoph Jeffcoat}, missão: {q:7321::Soothing Turtle Bisque} PNJ: {n:0:alliance:Chef Jessen}, missão: {q:555::Soothing Turtle Bisque}",
  ["Artisan Cooking (225-300)"] = "Culinária Artesão (225-300)",
  ["Artisan Cooking is the reward of the {q:6610::Clamlette Surprise} quest. You need {b}level 35{/b} and {b}Cooking 225{/b} for it."] = "Culinária Artesão é a recompensa da missão {q:6610::Clamlette Surprise}. Você precisa de {b}nível 35{/b} e {b}Culinária 225{/b} para ela.",
  ["Pick up the quest that sends you to Gadgetzan: Horde players take {q:6611::To Gadgetzan You Go!} from {n:0:horde:Zamja} in Orgrimmar, Alliance players take {q:6612::I Know A Guy...} from {n:0:alliance:Daryl Riknussun} in Ironforge."] = "Pegue a missão que manda você para Geringontzan: jogadores da Horda pegam {q:6611::To Gadgetzan You Go!} com {n:0:horde:Zamja} em Orgrimmar, e jogadores da Aliança pegam {q:6612::I Know A Guy...} com {n:0:alliance:Daryl Riknussun} em Altaforja.",
  ["Collect 12x {i:12207:inv_egg_03:Giant Egg}, 10x {i:7974:inv_misc_food_51:Zesty Clam Meat} and 20x {i:8932:inv_misc_food_37:Alterac Swiss}. {b}Don't go to Gadgetzan before you have all of them{/b}, otherwise you make the trip twice."] = "Junte 12x {i:12207:inv_egg_03:Giant Egg}, 10x {i:7974:inv_misc_food_51:Zesty Clam Meat} e 20x {i:8932:inv_misc_food_37:Alterac Swiss}. {b}Não vá para Geringontzan antes de ter tudo{/b}, senão você faz a viagem duas vezes.",
  ["Find {n:0::Dirge Quikcleave} in Gadgetzan, take Clamlette Surprise from him and hand in the three items. He teaches you Artisan Cooking on the spot. While you are in Tanaris, go to Steamwheedle Port and {b}buy {i:13939:inv_scroll_03:Recipe: Spotted Yellowtail} from {n:0::Gikkix}{/b}, you need it in the next step."] = "Encontre {n:0::Dirge Quikcleave} em Geringontzan, pegue Clamlette Surprise com ele e entregue os três itens. Ele ensina Culinária Artesão na hora. Enquanto estiver em Tanaris, vá até o Porto Bondebico e {b}compre {i:13939:inv_scroll_03:Recipe: Spotted Yellowtail} com {n:0::Gikkix}{/b}; você vai precisar dela na próxima etapa.",
  ["Make around 140 from one of these two, buy the fish that is cheaper."] = "Faça cerca de 140 de uma destas duas; compre o peixe que estiver mais barato.",
  ["Stranglethorn Vale: {n:0::Kelsey Yance}"] = "Selva do Espinhaço: {n:0::Kelsey Yance}",
  ["This WoW Forever First Aid leveling guide will show you the fastest way to level your First Aid skill from 1 to 300. You will also find every trainer location and where to train First Aid past 150 and 225."] = "Este guia de Primeiros Socorros do WoW Forever mostra a forma mais rápida de subir sua perícia de Primeiros Socorros de 1 a 300. Você também encontra a localização de todos os instrutores e onde treinar Primeiros Socorros acima de 150 e 225.",
  ["First Aid does not take up one of your two profession slots, so every character can learn it. Bandages heal you between fights, and in Forever First Aid also makes the healing potions that used to be Alchemy recipes, so it's worth leveling on every character. Below you will find the shopping list, the First Aid trainers by starting zone and capital city, and the cheapest recipes for every skill range."] = "Primeiros Socorros não ocupa um dos seus dois espaços de profissão, então todo personagem pode aprendê-lo. As ataduras curam você entre os combates e, no Forever, Primeiros Socorros também faz as poções de cura que antes eram receitas de Alquimia, então vale a pena subir em todos os personagens. Abaixo você encontra a lista de compras, os instrutores de Primeiros Socorros por zona inicial e capital, e as receitas mais baratas para cada faixa de perícia.",
  ["First Aid Trainer Locations"] = "Localização dos instrutores de Primeiros Socorros",
  ["Apprentice First Aid has no level requirement, so you can learn it on a fresh character. Every trainer also teaches Journeyman First Aid, so you don't have to find a different trainer at 50."] = "Primeiros Socorros Aprendiz não tem requisito de nível, então você pode aprendê-lo com um personagem recém-criado. Todo instrutor também ensina Primeiros Socorros Artífice, então você não precisa procurar outro instrutor em 50.",
  ["Undercity: {n:0:horde:Mary Edras}"] = "Cidade Baixa: {n:0:horde:Mary Edras}",
  ["Thunder Bluff: {n:0:horde:Pand Stonebinder}"] = "Penhasco do Trovão: {n:0:horde:Pand Stonebinder}",
  ["Every starting zone has a First Aid trainer, most of them are inside the inn."] = "Toda zona inicial tem um instrutor de Primeiros Socorros; a maioria fica dentro da estalagem.",
  ["{n:0:horde:Rawrk} in the barracks in Razor Hill"] = "{n:0:horde:Rawrk} no quartel do Monte da Navalha",
  ["{n:0:horde:Vira Younghoof} inside the inn in Bloodhoof Village"] = "{n:0:horde:Vira Younghoof} dentro da estalagem da Aldeia Casco Sangrento",
  ["{n:0:horde:Nurse Neela} inside the inn in Brill"] = "{n:0:horde:Nurse Neela} dentro da estalagem de Montalvo",
  ["{n:0::Melasa Fairmend} in Valanaar, {n:0::Naleeia Tattermend} in Shen'dar Village"] = "{n:0::Melasa Fairmend} em Valanaar, {n:0::Naleeia Tattermend} em Shen'dar Village",
  ["Stormwind City: {n:0:alliance:Shaina Fuller}"] = "Ventobravo: {n:0:alliance:Shaina Fuller}",
  ["Ironforge: {n:0:alliance:Nissa Firestone}"] = "Altaforja: {n:0:alliance:Nissa Firestone}",
  ["{n:0:alliance:Michelle Belle} upstairs in the inn in Goldshire"] = "{n:0:alliance:Michelle Belle} no andar de cima da estalagem de Vila d'Ouro",
  ["{n:0:alliance:Thamner Pol} in the Thunderbrew Distillery in Kharanos"] = "{n:0:alliance:Thamner Pol} na Cervejaria Cervaforte, em Kharanos",
  ["{n:0:alliance:Byancie} in Dolanaar, in the building north of the inn"] = "{n:0:alliance:Byancie} em Dolanaar, no prédio ao norte da estalagem",
  ["You can find every First Aid trainer for Horde and Alliance on my WoW Forever First Aid Trainers page."] = "Você encontra todos os instrutores de Primeiros Socorros da Horda e da Aliança na minha página de instrutores de Primeiros Socorros do WoW Forever.",
  ["Apprentice First Aid (1-75)"] = "Primeiros Socorros Aprendiz (1-75)",
  ["If you have Linen Cloth or bought some, pick the {b}Bandages{/b} tab. If you bought herbs, pick the {b}Healing Potions{/b} tab."] = "Se você tem Tecido de Linho ou comprou algum, escolha a aba {b}Ataduras{/b}. Se comprou ervas, escolha a aba {b}Poções de Cura{/b}.",
  ["Bandages"] = "Ataduras",
  ["Healing Potions"] = "Poções de Cura",
  ["86x {s:1244431:inv_potion_49:Minor Healing Potion} - 86 Peacebloom, 86 Mild Spices, 86 Empty Vial"] = "86x {s:1244431:inv_potion_49:Minor Healing Potion} - 86 Flor-da-paz, 86 Temperos Suaves, 86 Frasco Vazio",
  ["{i:2678:inv_misc_food_wheat_02:Mild Spices} are sold by Cooking supply vendors, {i:3371:inv_potion_84:Empty Vial} by Alchemy supply vendors. Open your faction below to see who sells them near your trainer:"] = "{i:2678:inv_misc_food_wheat_02:Mild Spices} são vendidos pelos vendedores de suprimentos de Culinária, e {i:3371:inv_potion_84:Empty Vial} pelos vendedores de suprimentos de Alquimia. Abra sua facção abaixo para ver quem os vende perto do seu instrutor:",
  ["spices: {n:0:horde:Xen'to} vials: {n:0:horde:Kor'geld}"] = "temperos: {n:0:horde:Xen'to} frascos: {n:0:horde:Kor'geld}",
  ["{n:0:horde:Felicia Doan} in the Trade Quarter"] = "{n:0:horde:Felicia Doan} no Bairro do Comércio",
  ["spices: {n:0:horde:Naal Mistrunner} vials: {n:0:horde:Mani Winterhoof}"] = "temperos: {n:0:horde:Naal Mistrunner} frascos: {n:0:horde:Mani Winterhoof}",
  ["{n:0:horde:Wunna Darkmane} in Bloodhoof Village"] = "{n:0:horde:Wunna Darkmane} na Aldeia Casco Sangrento",
  ["{n:0:horde:Abigail Shiel} in Brill"] = "{n:0:horde:Abigail Shiel} em Montalvo",
  ["{n:0::Iallion Featherfall} in Valanaar {n:0::Belandiel Farflight} in Shen'dar Village"] = "{n:0::Iallion Featherfall} em Valanaar {n:0::Belandiel Farflight} em Shen'dar Village",
  ["{n:0:alliance:Edna Mullby} in the Trade District"] = "{n:0:alliance:Edna Mullby} no Distrito Comercial",
  ["spices: {n:0:alliance:Emrul Riknussun} vials: {n:0:alliance:Gwina Stonebranch}, right next to the trainer"] = "temperos: {n:0:alliance:Emrul Riknussun} frascos: {n:0:alliance:Gwina Stonebranch}, bem ao lado do instrutor",
  ["{n:0:alliance:Golorn Frostbeard} in Kharanos"] = "{n:0:alliance:Golorn Frostbeard} em Kharanos",
  ["{n:0:alliance:Narret Shadowgrove} in Dolanaar"] = "{n:0:alliance:Narret Shadowgrove} em Dolanaar",
  ["50x {s:3275:inv_misc_bandage_15:Linen Bandage} - 50 Linen Cloth"] = "50x {s:3275:inv_misc_bandage_15:Linen Bandage} - 50 Tecido de Linho",
  ["49x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 98 Linen Cloth"] = "49x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 98 Tecido de Linho",
  ["Journeyman First Aid (75-150)"] = "Primeiros Socorros Artífice (75-150)",
  ["To train past 75, visit your trainer and learn Journeyman First Aid, it requires First Aid 50."] = "Para treinar acima de 75, visite seu instrutor e aprenda Primeiros Socorros Artífice; exige Primeiros Socorros 50.",
  ["16x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 32 Linen Cloth"] = "16x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 32 Tecido de Linho",
  ["12x {s:3277:inv_misc_bandage_14:Wool Bandage} - 12 Wool Cloth"] = "12x {s:3277:inv_misc_bandage_14:Wool Bandage} - 12 Tecido de Lã",
  ["If you have Wool Cloth, pick the {b}Bandages{/b} tab. If you have to buy everything, the {b}Healing Potions{/b} tab is cheaper."] = "Se você tem Tecido de Lã, escolha a aba {b}Ataduras{/b}. Se precisar comprar tudo, a aba {b}Poções de Cura{/b} sai mais barata.",
  ["43x {s:3277:inv_misc_bandage_14:Wool Bandage} - 43 Wool Cloth"] = "43x {s:3277:inv_misc_bandage_14:Wool Bandage} - 43 Tecido de Lã",
  ["54x {s:3278:inv_misc_bandage_17:Heavy Wool Bandage} - 108 Wool Cloth"] = "54x {s:3278:inv_misc_bandage_17:Heavy Wool Bandage} - 108 Tecido de Lã",
  ["For this tab you need 54 {i:2678:inv_misc_food_wheat_02:Mild Spices}, 31 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}, 31 {i:3372:inv_potion_85:Leaded Vial} and 54 {i:2723:inv_drink_10:Bottle of Dalaran Noir}. Spices are sold by Cooking supply vendors, vials by Alchemy supply vendors and the bottles by barkeeps. The starting zone vendors don't sell Hot Spices or Leaded Vials, so buy them in a capital city. Open your faction below to see who sells them:"] = "Para esta aba você precisa de 54 {i:2678:inv_misc_food_wheat_02:Mild Spices}, 31 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}, 31 {i:3372:inv_potion_85:Leaded Vial} e 54 {i:2723:inv_drink_10:Bottle of Dalaran Noir}. Os temperos são vendidos pelos vendedores de suprimentos de Culinária, os frascos pelos vendedores de suprimentos de Alquimia e as garrafas pelos taberneiros. Os vendedores das zonas iniciais não vendem Temperos Picantes nem Frascos com Chumbo, então compre-os em uma capital. Abra sua facção abaixo para ver quem os vende:",
  ["{i:2678:inv_misc_food_wheat_02:Mild Spices} and {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}"] = "{i:2678:inv_misc_food_wheat_02:Mild Spices} e {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}",
  ["Orgrimmar: {n:0:horde:Xen'to} Undercity: {n:0:horde:Felicia Doan} Thunder Bluff: {n:0:horde:Naal Mistrunner}"] = "Orgrimmar: {n:0:horde:Xen'to} Cidade Baixa: {n:0:horde:Felicia Doan} Penhasco do Trovão: {n:0:horde:Naal Mistrunner}",
  ["Orgrimmar: {n:0:horde:Kor'geld} Undercity: {n:0:horde:Felicia Doan} Thunder Bluff: {n:0:horde:Mani Winterhoof}"] = "Orgrimmar: {n:0:horde:Kor'geld} Cidade Baixa: {n:0:horde:Felicia Doan} Penhasco do Trovão: {n:0:horde:Mani Winterhoof}",
  ["Orgrimmar: {n:5611::Barkeep Morag} Booty Bay: {n:2832::Nixxrax Fillamug}"] = "Orgrimmar: {n:5611::Barkeep Morag} Angra do Butim: {n:2832::Nixxrax Fillamug}",
  ["Stormwind City: {n:0:alliance:Edna Mullby} Ironforge: {n:0:alliance:Emrul Riknussun} Darnassus: {n:0:alliance:Mythrin'dir}"] = "Ventobravo: {n:0:alliance:Edna Mullby} Altaforja: {n:0:alliance:Emrul Riknussun} Darnassus: {n:0:alliance:Mythrin'dir}",
  ["Stormwind City: {n:0:alliance:Edna Mullby} Ironforge: {n:0:alliance:Gwina Stonebranch} Darnassus: {n:0:alliance:Mythrin'dir}"] = "Ventobravo: {n:0:alliance:Edna Mullby} Altaforja: {n:0:alliance:Gwina Stonebranch} Darnassus: {n:0:alliance:Mythrin'dir}",
  ["Stormwind City: {n:277::Roberto Pupellyverbos} and {n:1328::Elly Langston} Ironforge: {n:5570::Bruuk Barleybeard} Booty Bay: {n:2832::Nixxrax Fillamug}"] = "Ventobravo: {n:277::Roberto Pupellyverbos} e {n:1328::Elly Langston} Altaforja: {n:5570::Bruuk Barleybeard} Angra do Butim: {n:2832::Nixxrax Fillamug}",
  ["54x {s:1259342:inv_10_alchemy2_quenchingfluid_color2:Simple Poultice} - 54 Spider Ichor, 54 Mild Spices, 54 Bottle of Dalaran Noir"] = "54x {s:1259342:inv_10_alchemy2_quenchingfluid_color2:Simple Poultice} - 54 Icor de Aranha, 54 Temperos Suaves, 54 Garrafa de Dalaran Noir",
  ["31x {s:1244433:inv_potion_51:Healing Potion} - 31 Bruiseweed, 31 Hot Spices, 31 Leaded Vial"] = "31x {s:1244433:inv_potion_51:Healing Potion} - 31 Ervamostarda, 31 Temperos Picantes, 31 Frasco com Chumbo",
  ["Expert First Aid (150-225)"] = "Primeiros Socorros Especialista (150-225)",
  ["{b}Learn {s:7928:inv_misc_bandage_01:Silk Bandage} from your trainer before you leave{/b}, it's the last recipe the trainers teach."] = "{b}Aprenda {s:7928:inv_misc_bandage_01:Silk Bandage} com seu instrutor antes de partir{/b}; é a última receita que os instrutores ensinam.",
  ["How to learn Expert First Aid"] = "Como aprender Primeiros Socorros Especialista",
  ["To train past 150, buy the {i:16084:inv_misc_book_08:Expert First Aid - Under Wraps} book from {n:0:alliance:Deneb Walker} (Alliance) in Arathi Highlands or {n:0:horde:Balai Lok'Wein} (Horde) in Dustwallow Marsh. The book has {b}no level requirement{/b}, you only need First Aid 125."] = "Para treinar acima de 150, compre o livro {i:16084:inv_misc_book_08:Expert First Aid - Under Wraps} com {n:0:alliance:Deneb Walker} (Aliança) no Planalto Arathi ou com {n:0:horde:Balai Lok'Wein} (Horda) no Pântano Vadeoso. O livro {b}não tem requisito de nível{/b}; você só precisa de Primeiros Socorros 125.",
  ["They also sell the next two manuals, so {b}buy all three{/b} while you are there, or get them from the Auction House if you are low level:"] = "Eles também vendem os próximos dois manuais, então {b}compre os três{/b} enquanto estiver lá, ou pegue-os na casa de leilões se tiver nível baixo:",
  ["47x {s:7928:inv_misc_bandage_01:Silk Bandage} - 47 Silk Cloth"] = "47x {s:7928:inv_misc_bandage_01:Silk Bandage} - 47 Tecido de Seda",
  ["47x {s:7929:inv_misc_bandage_02:Heavy Silk Bandage} - 94 Silk Cloth"] = "47x {s:7929:inv_misc_bandage_02:Heavy Silk Bandage} - 94 Tecido de Seda",
  ["Use the Manual: Heavy Silk Bandage first to learn the recipe."] = "Use antes o Manual: Atadura de Seda Grossa para aprender a receita.",
  ["19x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 19 Mageweave Cloth"] = "19x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 19 Tecido Mágico",
  ["Use the Manual: Mageweave Bandage first to learn the recipe."] = "Use antes o Manual: Atadura de Tecido Mágico para aprender a receita.",
  ["Artisan First Aid (225-300)"] = "Primeiros Socorros Artesão (225-300)",
  ["You can train First Aid past 225 by completing the Triage quest. It requires {b}First Aid 225{/b} and {b}level 35{/b}, even though the quest itself is level 45."] = "Você pode treinar Primeiros Socorros acima de 225 completando a missão Triagem. Ela exige {b}Primeiros Socorros 225{/b} e {b}nível 35{/b}, embora a missão em si seja de nível 45.",
  ["{b}Bring everything you need in order to skill up to 275{/b}, as you will learn the next two bandages from the same doctor, so bring around 90 Mageweave Cloth and 20 Runecloth with you."] = "{b}Leve tudo o que precisa para subir até 275{/b}, porque você vai aprender as próximas duas ataduras com o mesmo médico; então leve cerca de 90 Tecidos Mágicos e 20 Tecidos Rúnicos.",
  ["The {q:6622::Triage} quest is given by {n:0:horde:Doctor Gregory Victor} in Arathi Highlands at Hammerfall."] = "A missão {q:6622::Triage} é dada por {n:0:horde:Doctor Gregory Victor} em Queda do Martelo, no Planalto Arathi.",
  ["Hammerfall, Arathi Highlands"] = "Queda do Martelo, Planalto Arathi",
  ["The {q:6624::Triage} quest is given by {n:0:alliance:Doctor Gustaf VanHowzen} in Dustwallow Marsh at Theramore."] = "A missão {q:6624::Triage} é dada por {n:0:alliance:Doctor Gustaf VanHowzen} em Theramore, no Pântano Vadeoso.",
  ["Foothold Citadel, Dustwallow Marsh"] = "Cidadela Ponto de Apoio, Pântano Vadeoso",
  ["You get a stack of triage bandages and have to save 15 patients, heal the critically injured ones first."] = "Você recebe uma pilha de ataduras de triagem e precisa salvar 15 pacientes; cure primeiro os feridos em estado crítico.",
  ["How to complete the Triage quest"] = "Como completar a missão Triagem",
  ["Make sure you have about 10 minutes of spare time to do this with no interruptions."] = "Reserve cerca de 10 minutos livres para fazer isto sem interrupções.",
  ["Press CTRL + V to show the health bars over the patients, or turn on \"Show NPC names\" in the interface options."] = "Pressione CTRL + V para mostrar as barras de vida sobre os pacientes, ou ative \"Mostrar nomes de PNJs\" nas opções de interface.",
  ["Zoom the camera out to third person, so you see as much of the room as you can."] = "Afaste a câmera para a terceira pessoa, para ver o máximo possível da sala.",
  ["Put the Triage Bandages the doctor gave you on your action bar and use those, not your own bandages."] = "Coloque as Ataduras de Triagem que o médico deu na sua barra de ações e use-as, não as suas próprias ataduras.",
  ["Stand in the middle of the room."] = "Fique no meio da sala.",
  ["When you see another patient, left-click on them to pre-select them, and as soon as your current heal has finished click the bandages in your action bar and the pre-selected one will begin to heal. Saves valuable seconds this way."] = "Quando vir outro paciente, clique nele com o botão esquerdo para pré-selecioná-lo e, assim que sua cura atual terminar, clique nas ataduras da barra de ações: o paciente pré-selecionado começará a ser curado. Assim você economiza segundos valiosos.",
  ["When you have saved 15 patients, {b}turn in the quest immediately{/b}. I failed it on my druid because I waited, six patients died in the meantime and the quest went from completed to failed."] = "Quando tiver salvado 15 pacientes, {b}entregue a missão imediatamente{/b}. Falhei com meu druida porque esperei: seis pacientes morreram nesse meio-tempo e a missão passou de completa para fracassada.",
  ["29x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 29 Mageweave Cloth"] = "29x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 29 Tecido Mágico",
  ["30x {s:10841:inv_misc_bandage_20:Heavy Mageweave Bandage} - 60 Mageweave Cloth"] = "30x {s:10841:inv_misc_bandage_20:Heavy Mageweave Bandage} - 60 Tecido Mágico",
  ["The doctor teaches it at 240."] = "O médico ensina esta em 240.",
  ["20x {s:18629:inv_misc_bandage_11:Runecloth Bandage} - 20 Runecloth"] = "20x {s:18629:inv_misc_bandage_11:Runecloth Bandage} - 20 Tecido Rúnico",
  ["The doctor teaches it at 260."] = "O médico ensina esta em 260.",
  ["30x {s:1244436:inv_potion_54:Major Healing Potion} - 30 Golden Sansam, 90 Soothing Spices, 30 Crystal Vial"] = "30x {s:1244436:inv_potion_54:Major Healing Potion} - 30 Sansam Dourado, 90 Temperos Calmantes, 30 Frasco de Cristal",
  ["The recipe is {i:255729:inv_misc_book_03:Manual: Major Healing Potion}. Check the Auction House first, and buy it there if it costs less than 8g."] = "A receita é {i:255729:inv_misc_book_03:Manual: Major Healing Potion}. Confira primeiro a casa de leilões e compre lá se custar menos de 8 ouros.",
  ["If it costs more, you can buy it from {n:0::Pexmit} in Mount Hyjal for 8g, but he can be tricky to find."] = "Se custar mais, você pode comprá-la com {n:0::Pexmit} no Monte Hyjal por 8 ouros, mas ele pode ser difícil de encontrar.",
  ["Horde players can also get it from Ortak Lomgok in Elderwild, Mount Hyjal, as the reward for {q:96622::A Rest Without Pain}. You have to complete his {q:96616::Herbs for the Bruised and Weary} quest first."] = "Jogadores da Horda também podem obtê-la com Ortak Lomgok em Elderwild, no Monte Hyjal, como recompensa de {q:96622::A Rest Without Pain}. Você precisa completar antes a missão dele {q:96616::Herbs for the Bruised and Weary}.",
  ["This WoW Forever Fishing leveling guide will show you the fastest way to level Fishing from 1 to 300. Fishing takes a lot of patience, you will have to catch a lot of fish to get from start to finish, but you don't need any materials, only a Fishing Pole and a few lures."] = "Este guia de Pesca do WoW Forever mostra a forma mais rápida de subir Pesca de 1 a 300. Pescar exige muita paciência, você vai ter que pescar muitos peixes do começo ao fim, mas não precisa de nenhum material, só de uma Vara de Pescar e de algumas iscas.",
  ["Below you will find every Fishing trainer by starting zone and capital city, where to fish for each skill range, and how to learn Expert and Artisan Fishing. If you haven't leveled Cooking yet, use my Fishing and Cooking leveling guide instead, because the fish you catch will level your Cooking at the same time:"] = "Abaixo você encontra todos os instrutores de Pesca por zona inicial e capital, onde pescar em cada faixa de perícia e como aprender Pesca Especialista e Artesão. Se ainda não subiu Culinária, use meu guia de Pesca e Culinária, porque os peixes que você pescar vão subir sua Culinária ao mesmo tempo:",
  ["Fishing Trainer Locations"] = "Localização dos instrutores de Pesca",
  ["Apprentice Fishing has no level requirement in Forever, so you can learn it on a fresh character. Every trainer also teaches Journeyman Fishing, so you don't have to find a different trainer at 50."] = "No Forever, Pesca Aprendiz não tem requisito de nível, então você pode aprendê-la com um personagem recém-criado. Todo instrutor também ensina Pesca Artífice, então você não precisa procurar outro instrutor em 50.",
  ["Undercity: {n:0:horde:Armand Cromwell}"] = "Cidade Baixa: {n:0:horde:Armand Cromwell}",
  ["Thunder Bluff: {n:0:horde:Kah Mistrunner}"] = "Penhasco do Trovão: {n:0:horde:Kah Mistrunner}",
  ["Every starting zone has a Fishing trainer, and they all stand next to water, so you can start fishing right away."] = "Toda zona inicial tem um instrutor de Pesca, e todos ficam perto da água, então você pode começar a pescar na hora.",
  ["{n:0:horde:Lau'Tiki} on the coast at Sen'jin Village"] = "{n:0:horde:Lau'Tiki} na costa da Vila Sen'jin",
  ["{n:0:horde:Uthan Stillwater} at Stonebull Lake, next to Bloodhoof Village"] = "{n:0:horde:Uthan Stillwater} no Lago Touro de Pedra, ao lado da Aldeia Casco Sangrento",
  ["{n:0:horde:Clyde Kellen} at Brightwater Lake, east of Brill"] = "{n:0:horde:Clyde Kellen} no Lago Águas Claras, a leste de Montalvo",
  ["{n:0::Baelann Swiftcurrent} in Valanaar, {n:0::Fenn Fairweather} in Shen'dar Village"] = "{n:0::Baelann Swiftcurrent} em Valanaar, {n:0::Fenn Fairweather} em Shen'dar Village",
  ["Stormwind City: {n:0:alliance:Arnold Leland}"] = "Ventobravo: {n:0:alliance:Arnold Leland}",
  ["Ironforge: {n:0:alliance:Grimnur Stonebrand}"] = "Altaforja: {n:0:alliance:Grimnur Stonebrand}",
  ["{n:0:alliance:Lee Brown} at Crystal Lake, east of Goldshire"] = "{n:0:alliance:Lee Brown} no Lago de Cristal, a leste de Vila d'Ouro",
  ["{n:0:alliance:Paxton Ganter} at Iceflow Lake, on the way to Gnomeregan"] = "{n:0:alliance:Paxton Ganter} no Lago Fluxo de Gelo, no caminho para Gnomeregan",
  ["{n:0:alliance:Androl Oakhand} in Rut'theran Village, on the shore next to the dock"] = "{n:0:alliance:Androl Oakhand} na Vila Rut'theran, na margem ao lado do cais",
  ["You can find every Fishing trainer for Horde and Alliance on my WoW Forever Fishing Trainers page."] = "Você encontra todos os instrutores de Pesca da Horda e da Aliança na minha página de instrutores de Pesca do WoW Forever.",
  ["How to Fish in WoW Forever (1-75)"] = "Como pescar no WoW Forever (1-75)",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a few {i:6529:inv_misc_orb_03:Shiny Bauble} from a Fishing Supply or Trade Supply vendor. In the capital cities they stand next to the trainer, for every other zone open your faction below:"] = "Compre uma {i:6256:inv_fishingpole_02:Fishing Pole} e algumas {i:6529:inv_misc_orb_03:Shiny Bauble} com um vendedor de suprimentos de Pesca ou de mercadorias. Nas capitais, eles ficam ao lado do instrutor; para as outras zonas, abra sua facção abaixo:",
  ["{n:0:horde:Zansoa} in Sen'jin Village"] = "{n:0:horde:Zansoa} na Vila Sen'jin",
  ["{n:0:horde:Martine Tramblay} at the Death's Watch Waystation, south-east of Brill"] = "{n:0:horde:Martine Tramblay} no Posto de Vigília da Morte, a sudeste de Montalvo",
  ["{n:0::Baelann Swiftcurrent} in Valanaar, {n:0::Belandiel Farflight} in Shen'dar Village"] = "{n:0::Baelann Swiftcurrent} em Valanaar, {n:0::Belandiel Farflight} em Shen'dar Village",
  ["{n:0:horde:Shankys}, next to the Fishing trainer"] = "{n:0:horde:Shankys}, ao lado do instrutor de Pesca",
  ["{n:0:horde:Lizbeth Cromwell}, next to the Fishing trainer"] = "{n:0:horde:Lizbeth Cromwell}, ao lado do instrutor de Pesca",
  ["{n:0:horde:Sewa Mistrunner}, next to the Fishing trainer"] = "{n:0:horde:Sewa Mistrunner}, ao lado do instrutor de Pesca",
  ["{n:0:horde:Wik'Tar} in Zoram'gar Outpost"] = "{n:0:horde:Wik'Tar} no Posto Avançado de Zoram'gar",
  ["{n:0:horde:Katoom the Angler}, the Fishing trainer in Revantusk Village"] = "{n:0:horde:Katoom the Angler}, o instrutor de Pesca na Aldeia Presacurva",
  ["{n:0:alliance:Gretta Ganter} at Iceflow Lake"] = "{n:0:alliance:Gretta Ganter} no Lago Fluxo de Gelo",
  ["{n:0:alliance:Nessa Shadowsong} in Rut'theran Village"] = "{n:0:alliance:Nessa Shadowsong} na Vila Rut'theran",
  ["{n:0:alliance:Catherine Leland}, next to the Fishing trainer"] = "{n:0:alliance:Catherine Leland}, ao lado do instrutor de Pesca",
  ["{n:0:alliance:Tansy Puddlefizz}, next to the Fishing trainer"] = "{n:0:alliance:Tansy Puddlefizz}, ao lado do instrutor de Pesca",
  ["{n:0:alliance:Voloren}, next to the Fishing trainer"] = "{n:0:alliance:Voloren}, ao lado do instrutor de Pesca",
  ["{n:0:alliance:Khara Deepwater} at the Loch"] = "{n:0:alliance:Khara Deepwater} no Loch",
  ["{n:0:alliance:Stuart Fleming} in Menethil Harbor"] = "{n:0:alliance:Stuart Fleming} no Porto de Menethil",
  ["Redridge Mountains"] = "Montanhas Cristarrubra",
  ["{n:0:alliance:Vernon Hale} at Lake Everstill"] = "{n:0:alliance:Vernon Hale} no Lago Sempremanso",
  ["{n:0:alliance:Lindea Rabonne} in Southshore"] = "{n:0:alliance:Lindea Rabonne} na Costa Sul",
  ["Open the Professions window."] = "Abra a janela de Profissões.",
  ["Click on the {b}hammer button{/b} in the row of buttons on the right side of your screen, {b}NOT the Fishing tab{/b}."] = "Clique no {b}botão do martelo{/b} na fileira de botões do lado direito da tela, {b}NÃO na aba de Pesca{/b}.",
  ["Drag the {s:7731:trade_fishing:Fishing} button from the Fishing box to your action bar."] = "Arraste o botão {s:7731:trade_fishing:Fishing} do quadro de Pesca para a sua barra de ações.",
  ["Equip your Fishing Pole and apply the {i:6529:inv_misc_orb_03:Shiny Bauble} lure."] = "Equipe sua Vara de Pescar e aplique a isca {i:6529:inv_misc_orb_03:Shiny Bauble}.",
  ["Go to any starting zone and look for a lake, pond or river. Stand in front of the water and press the fishing button."] = "Vá para qualquer zona inicial e procure um lago, uma lagoa ou um rio. Fique de frente para a água e aperte o botão de pesca.",
  ["Mouse over the bobber in the water, and when it splashes, right-click on it."] = "Passe o mouse sobre a boia na água e, quando ela espirrar água, clique nela com o botão direito.",
  ["Fish until you reach Fishing 75."] = "Pesque até chegar a Pesca 75.",
  ["{b}Starting zones:{/b} Dun Morogh, Durotar, Elwynn Forest, Mulgore, Teldrassil, Tirisfal Glades, Zephras Isle"] = "{b}Zonas iniciais:{/b} Dun Morogh, Durotar, Floresta de Elwynn, Mulgore, Teldrassil, Clareiras de Tirisfal, Zephras Isle",
  ["{b}Remember, starting zones do not include capital cities!{/b}"] = "{b}Lembre-se: as zonas iniciais não incluem as capitais!{/b}",
  ["If you can't find the Fishing button, I show it with pictures in my how to fish in WoW Forever guide."] = "Se não encontrar o botão de Pesca, eu o mostro com imagens no meu guia de como pescar no WoW Forever.",
  ["Go back to your trainer and learn Journeyman Fishing. It requires {b}Fishing 50{/b} and {b}level 10{/b}."] = "Volte ao seu instrutor e aprenda Pesca Artífice. Exige {b}Pesca 50{/b} e {b}nível 10{/b}.",
  ["Fish until 150 in one of the capital cities:"] = "Pesque até 150 em uma das capitais:",
  ["You can fish in any of these zones too: The Barrens, Darkshore, Ironforge, Loch Modan, Silverpine Forest, Westfall."] = "Você também pode pescar em qualquer uma destas zonas: Sertões, Costa Negra, Altaforja, Loch Modan, Floresta de Pinhaprata, Cerro Oeste.",
  ["If the fish keep getting away, buy {i:6530:inv_misc_monstertail_03:Nightcrawlers} from a Fishing Supply vendor. They need Fishing 50."] = "Se os peixes continuarem escapando, compre {i:6530:inv_misc_monstertail_03:Nightcrawlers} com um vendedor de suprimentos de Pesca. Elas exigem Pesca 50.",
  ["You can learn Expert Fishing from the {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} book (requires {b}level 20{/b} and {b}Fishing 125{/b}) sold by {n:0::Old Man Heming} at Booty Bay in Stranglethorn Vale. He is in the middle of Booty Bay at the very bottom, near the fishing sign. You can also buy the book from the Auction House."] = "Você pode aprender Pesca Especialista com o livro {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} (exige {b}nível 20{/b} e {b}Pesca 125{/b}), vendido por {n:0::Old Man Heming} na Angra do Butim, na Selva do Espinhaço. Ele fica no meio da Angra do Butim, bem lá embaixo, perto da placa de pesca. Você também pode comprar o livro na casa de leilões.",
  ["Buy a bunch of {i:6532:inv_misc_gem_variety_02:Bright Baubles} from Old Man Heming before you leave."] = "Compre um monte de {i:6532:inv_misc_gem_variety_02:Bright Baubles} com o Velho Heming antes de ir embora.",
  ["Go to {b}Dustwallow Marsh{/b}, apply {i:6532:inv_misc_gem_variety_02:Bright Baubles} to your Fishing Pole and fish until 225."] = "Vá até o {b}Pântano Vadeoso{/b}, aplique {i:6532:inv_misc_gem_variety_02:Bright Baubles} na sua Vara de Pescar e pesque até 225.",
  ["I recommend fishing in Dustwallow because the Artisan Fishing quest starts there, but you can fish in these zones too: Alterac Mountains, Arathi Highlands, Desolace, Stranglethorn Vale, Swamp of Sorrows, and Thousand Needles."] = "Recomendo pescar no Pântano Vadeoso porque a missão de Pesca Artesão começa ali, mas você também pode pescar nestas zonas: Montanhas de Alterac, Planalto Arathi, Desolação, Selva do Espinhaço, Pântano das Mágoas e Mil Agulhas.",
  ["Learning Artisan Fishing"] = "Aprendendo Pesca Artesão",
  ["To train Fishing past 225, you must complete the quest {q:6607::Nat Pagle, Angler Extreme} from {n:0::Nat Pagle} in Dustwallow Marsh."] = "Para treinar Pesca acima de 225, você precisa completar a missão {q:6607::Nat Pagle, Angler Extreme} de {n:0::Nat Pagle} no Pântano Vadeoso.",
  ["It requires {b}level 35{/b} and {b}Fishing 225{/b}."] = "Ela exige {b}nível 35{/b} e {b}Pesca 225{/b}.",
  ["To complete the quest, you have to catch 4 quest fish in four different zones:"] = "Para completar a missão, você precisa pescar 4 peixes de missão em quatro zonas diferentes:",
  ["Use {i:6532:inv_misc_gem_variety_02:Bright Baubles} when you are fishing in {b}Feralas{/b} to stop the fish from getting away. You don't need any lures in the other zones because your Fishing skill is high enough by then."] = "Use {i:6532:inv_misc_gem_variety_02:Bright Baubles} quando estiver pescando em {b}Feralas{/b} para impedir que os peixes escapem. Você não precisa de iscas nas outras zonas, porque a essa altura sua perícia em Pesca já é alta o bastante.",
  ["Nat Pagle, Angler Extreme quest"] = "Missão Nat Pagle, Angler Extreme",
  ["After you completed the quest, fish in any of these zones:"] = "Depois de completar a missão, pesque em qualquer uma destas zonas:",
  ["Western Plaguelands"] = "Terras Pestilentas Ocidentais",
  ["You will have to use {i:6532:inv_misc_gem_variety_02:Bright Baubles} in these zones to stop the fish from getting away!"] = "Você vai precisar usar {i:6532:inv_misc_gem_variety_02:Bright Baubles} nestas zonas para impedir que os peixes escapem!",
  ["This WoW Forever Lockpicking leveling guide will show you the fastest way to level Lockpicking from 1 to 300, with the best place to pick locks for each skill range."] = "Este guia de Arrombamento do WoW Forever mostra a forma mais rápida de subir Arrombamento de 1 a 300, com o melhor lugar para arrombar fechaduras em cada faixa de perícia.",
  ["Max Lockpicking Skill by Level"] = "Perícia máxima de Arrombamento por nível",
  ["{b}Your Lockpicking skill can't go higher than 5 times your level{/b}, so you have to level your character to level Lockpicking. This is the level you need for each part of the guide:"] = "{b}Sua perícia de Arrombamento não pode passar de 5 vezes o seu nível{/b}, então você precisa subir o nível do personagem para subir Arrombamento. Este é o nível de que você precisa para cada parte do guia:",
  ["Your level"] = "Seu nível",
  ["Max Lockpicking skill"] = "Perícia máxima de Arrombamento",
  ["I originally made this guide with my rogue in Classic. In WoW Forever I'm leveling a hunter, so a friend of mine checks the spots on his rogue, and he confirmed the Horde 1-100 part. Readers told me where they leveled from 150 to 300. I'm assuming the rest is the same as in Classic, but I will confirm it later. If something looks off, send me feedback."] = "Originalmente fiz este guia com meu ladino no Classic. No WoW Forever estou subindo um caçador, então um amigo confere os locais com o ladino dele, e ele confirmou a parte 1-100 da Horda. Leitores me contaram onde subiram de 150 a 300. Estou supondo que o resto é igual ao Classic, mas vou confirmar depois. Se algo parecer errado, me mande seu feedback.",
  ["Go to the ship near Ratchet in The Barrens. The Buccaneer's Strongboxes there respawn after a few seconds, so even two rogues can skill up there at the same time. {b}They are inside the ship{/b}, at the spot marked on the map below."] = "Vá até o navio perto de Vila Catraca, nos Sertões. As Caixas-fortes de Bucaneiro ali reaparecem depois de alguns segundos, então até dois ladinos podem subir ali ao mesmo tempo. {b}Elas ficam dentro do navio{/b}, no local marcado no mapa abaixo.",
  ["There is another chest at the bottom of the ship called The Jewel of the Southsea. Don't open it if you are low level, because it spawns a mob that will kill you."] = "Há outro baú no fundo do navio chamado A Joia dos Mares do Sul. Não o abra se tiver nível baixo, porque ele faz surgir um monstro que vai matar você.",
  ["There are a bunch of Practice Lockboxes in Redridge Mountains, north of Lake Everstill. They respawn really fast, so you can get to 100 there easily."] = "Há várias Caixas de Treino nas Montanhas Cristarrubra, ao norte do Lago Sempremanso. Elas reaparecem muito rápido, então você chega a 100 ali facilmente.",
  ["Go to Zoram Strand in Ashenvale and look for Waterlogged Footlockers along the shore, on land."] = "Vá até a Praia de Zoram, no Vale Gris, e procure Baús Encharcados ao longo da margem, em terra firme.",
  ["Go to Angor Fortress in Badlands. There are two kinds of footlockers there, the Battered Footlockers upstairs need 150, and the Dented Footlockers downstairs need {b}175{/b}."] = "Vá até a Fortaleza de Angor, nos Ermos. Há dois tipos de baús ali: os Baús Surrados no andar de cima exigem 150, e os Baús Amassados no andar de baixo exigem {b}175{/b}.",
  ["The footlockers downstairs give a skill point every time until 215, so you can stay here until 225."] = "Os baús do andar de baixo dão um ponto de perícia toda vez até 215, então você pode ficar aqui até 225.",
  ["Don't bother pickpocketing the mobs there, because their boxes are too low level to give any skill."] = "Não perca tempo batendo carteiras dos monstros dali, porque as caixas deles têm nível baixo demais para dar perícia.",
  ["Go to The Slag Pit, the cave in the middle of Searing Gorge, and pick the footlockers there. The ones on the upper part give skill points all the way to 300. They stay yellow until 290 and turn green after that, so the last 10 points take longer."] = "Vá até o Poço de Escória, a caverna no meio da Garganta Abrasadora, e arrombe os baús de lá. Os da parte de cima dão pontos de perícia até 300. Eles ficam amarelos até 290 e depois ficam verdes, então os últimos 10 pontos demoram mais.",
  ["{b}There are two kinds of Dented Footlockers in the Slag Pit{/b}, with the same name. The ones on the lower part need 200 and the ones on the upper part need 225. Pick both until the lower ones stop giving skill points, then stay on the upper part."] = "{b}Há dois tipos de Baús Amassados no Poço de Escória{/b}, com o mesmo nome. Os da parte de baixo exigem 200 e os da parte de cima exigem 225. Arrombe os dois até os de baixo pararem de dar pontos de perícia e depois fique na parte de cima.",
  ["Don't bother pickpocketing the mobs there, because their boxes are too low level to give much skill."] = "Não perca tempo batendo carteiras dos monstros dali, porque as caixas deles têm nível baixo demais para dar muita perícia.",
  ["This WoW Forever camping guide will show you how camping works, how to make a campfire and every camp item and buff of every profession."] = "Este guia de acampamento do WoW Forever mostra como o acampamento funciona, como fazer uma fogueira e todos os itens e bônus de acampamento de cada profissão.",
  ["Three night elves sitting at a campfire in Dolanaar, Teldrassil, in WoW Forever"] = "Três elfos noturnos sentados ao redor de uma fogueira em Dolanaar, Teldrassil, no WoW Forever",
  ["How Camping Works"] = "Como o acampamento funciona",
  ["Someone puts down a campfire, and everyone around it can place a camp item of their own profession. {b}Sit (/sit) next to the fire for a minute{/b}, you will see a buff start counting down. Then you get Camp Benefits, one buff with everything the camp items give, for an hour."] = "Alguém coloca uma fogueira, e todos ao redor podem colocar um item de acampamento da sua própria profissão. {b}Sente-se (/sit) ao lado da fogueira por um minuto{/b} e você verá um bônus começar a contagem regressiva. Depois você recebe Benefícios do Acampamento, um único bônus com tudo o que os itens de acampamento dão, por uma hora.",
  ["{b}Each player can place one camp item{/b}, and it puts all your camp items on a 1 hour cooldown. A campfire holds 3, 5 or 10 camp items, depending on how big it is (see How to Make a Campfire below). The buffs are weaker class buffs and don't stack with them."] = "{b}Cada jogador pode colocar um item de acampamento{/b}, e isso põe todos os seus itens de acampamento em recarga de 1 hora. Uma fogueira comporta 3, 5 ou 10 itens de acampamento, dependendo do tamanho (veja Como fazer uma fogueira abaixo). Os bônus são versões mais fracas dos bônus de classe e não se acumulam com eles.",
  ["The intro quests in the starting zones, The Great Outdoors and Camping 101, are optional, the buffs work without them. The quest givers' fires always give the Camp Tent's rested experience."] = "As missões introdutórias nas zonas iniciais, The Great Outdoors e Camping 101, são opcionais; os bônus funcionam sem elas. As fogueiras dos personagens que dão as missões sempre concedem a experiência descansada da Barraca de Acampamento.",
  ["How to Make a Campfire"] = "Como fazer uma fogueira",
  ["Learn Cooking from any Cooking trainer, the Basic Campfire Kit comes with it at skill 1. {i:4470:inv_tradeskillitem_01:Simple Wood} is sold by the trade and general goods vendors in most towns. Open your Professions window (the hammer and pick button in the menu bar), craft the kit from 1 Simple Wood under Cooking, then use it from your bags to place the campfire."] = "Aprenda Culinária com qualquer instrutor de Culinária; o Kit de Fogueira Básica vem junto, com perícia 1. {i:4470:inv_tradeskillitem_01:Simple Wood} é vendida pelos vendedores de mercadorias e de mercadorias gerais na maioria das cidades. Abra a janela de Profissões (o botão de martelo e picareta na barra de menu), crie o kit com 1 Madeira Simples em Culinária e depois use-o a partir das bolsas para colocar a fogueira.",
  ["{b}Tip:{/b} you don't have to carry Flint and Tinder and wood around any more, craft a stack of Basic Campfire Kits at home and carry only those, they take one bag slot. You can also hand them to others."] = "{b}Dica:{/b} você não precisa mais carregar Pederneira e Isca e madeira por aí: crie uma pilha de Kits de Fogueira Básica em casa e carregue só eles, que ocupam um espaço na bolsa. Você também pode dá-los a outros jogadores.",
  ["The bigger campfires hold more camp items, but they need a Blueprint."] = "As fogueiras maiores comportam mais itens de acampamento, mas exigem uma Planta.",
  ["The Expert Campfire Kit needs more Cooking to use than to learn (220 against 200). It's usually the other way around, so maybe it's a bug."] = "O Kit de Fogueira Especialista exige mais Culinária para usar do que para aprender (220 contra 200). Normalmente é o contrário, então talvez seja um bug.",
  ["Learn at"] = "Aprende com",
  ["Use at"] = "Usa com",
  ["Camp items"] = "Itens de acampamento",
  ["Made from"] = "Feito com",
  ["Comes with Cooking"] = "Vem com Culinária",
  ["{i:273087:inv_garrison_blueprints3:Blueprint: Journeyman Campfire} Dropped by: {n:3673::Lord Serpentis} in Wailing Caverns"] = "{i:273087:inv_garrison_blueprints3:Blueprint: Journeyman Campfire} Cai de: {n:3673::Lord Serpentis} na Caverna Ululante",
  ["{i:273101:inv_garrison_blueprints3:Blueprint: Expert Campfire} I don't know yet where it drops"] = "{i:273101:inv_garrison_blueprints3:Blueprint: Expert Campfire} Ainda não sei onde cai",
  ["Camp Items"] = "Itens de acampamento",
  ["Every profession has three camp items, at skill 20, 140 and 300 (Cooking has two), and each one replaces the one before. The tier 1 item comes from your profession trainer, {b}tier 2 and 3 need a Blueprint{/b}, a recipe item. The tier 2 and 3 blueprints drop from bosses, most of them in dungeons, the tabs show which one. Only the Herbalism one at 300 is not known yet."] = "Cada profissão tem três itens de acampamento, com perícia 20, 140 e 300 (Culinária tem dois), e cada um substitui o anterior. O item de nível 1 vem do instrutor da profissão; {b}os de nível 2 e 3 exigem uma Planta{/b}, um item de receita. As plantas de nível 2 e 3 caem de chefes, a maioria em masmorras; as abas mostram qual. Só a de Herborismo em 300 ainda é desconhecida.",
  ["{b}Every item also gives the buff of the tier 1 item of its profession{/b}, so you never have to choose between a buff and a crafting station. A Master Forge still gives the Strength buff of the Sharpening Wheel. Whether a tier 3 item also gives what the tier 2 item gives (an anvil from a Master Forge) is not confirmed yet. The tabs only list what each tier adds."] = "{b}Todo item também dá o bônus do item de nível 1 da sua profissão{/b}, então você nunca precisa escolher entre um bônus e uma estação de criação. Uma Forja Mestra continua dando o bônus de Força da Roda de Afiar. Ainda não foi confirmado se um item de nível 3 também dá o que o item de nível 2 dá (uma bigorna, no caso da Forja Mestra). As abas só listam o que cada nível acrescenta.",
  ["Alchemy"] = "Alquimia",
  ["Blacksmithing"] = "Ferraria",
  ["Enchanting"] = "Encantamento",
  ["Engineering"] = "Engenharia",
  ["Leatherworking"] = "Couraria",
  ["Tailoring"] = "Alfaiataria",
  ["Skinning"] = "Esfolamento",
  ["First Aid"] = "Primeiros Socorros",
  ["Camp Item"] = "Item de acampamento",
  ["What It Does"] = "O que faz",
  ["Mana regeneration buff, doesn't stack with Blessing of Wisdom"] = "Bônus de regeneração de mana; não se acumula com Bênção da Sabedoria",
  ["Trainer or the Camping 101 quest"] = "Instrutor ou a missão Camping 101",
  ["A Fermenter, needed for a few Alchemy recipes"] = "Um Fermentador, necessário para algumas receitas de Alquimia",
  ["{i:273085:inv_garrison_blueprints3:Blueprint: Fermenter} Dropped by: {n:250657::Rath'mael} in the Ruins of Lordaeron"] = "{i:273085:inv_garrison_blueprints3:Blueprint: Fermenter} Cai de: {n:250657::Rath'mael} nas Ruínas de Lordaeron",
  ["An Alchemy Lab, needed for some Alchemy recipes"] = "Um Laboratório de Alquimia, necessário para algumas receitas de Alquimia",
  ["{i:273112:inv_garrison_blueprints3:Blueprint: Alchemy Laboratory} Dropped by: {n:10508::Ras Frostwhisper} in Scholomance"] = "{i:273112:inv_garrison_blueprints3:Blueprint: Alchemy Laboratory} Cai de: {n:10508::Ras Frostwhisper} em Scolomântia",
  ["Strength buff, doesn't stack with Strength of Earth Totem"] = "Bônus de Força; não se acumula com Totem de Força da Terra",
  ["An anvil"] = "Uma bigorna",
  ["{i:273086:inv_garrison_blueprints3:Blueprint: Anvil} Dropped by: {n:1763::Gilnid} in The Deadmines"] = "{i:273086:inv_garrison_blueprints3:Blueprint: Anvil} Cai de: {n:1763::Gilnid} nas Minas Mortas",
  ["A Master Forge, needed for many Blacksmithing recipes"] = "Uma Forja Mestra, necessária para muitas receitas de Ferraria",
  ["{i:273113:inv_garrison_blueprints3:Blueprint: Master Forge} Dropped by: {n:8983::Golem Lord Argelmach} in Blackrock Depths"] = "{i:273113:inv_garrison_blueprints3:Blueprint: Master Forge} Cai de: {n:8983::Golem Lord Argelmach} no Abismo Rocha Negra",
  ["Armor, all stats and resistances buff, doesn't stack with Mark of the Wild"] = "Bônus de armadura, todos os atributos e resistências; não se acumula com Marca do Indomado",
  ["Better disenchanting"] = "Desencantamento melhor",
  ["{i:273103:inv_garrison_blueprints3:Blueprint: Arcane Salvager} Dropped by: {n:246020::Shade of the Archmage} in the City of Dalaran"] = "{i:273103:inv_garrison_blueprints3:Blueprint: Arcane Salvager} Cai de: {n:246020::Shade of the Archmage} na Cidade de Dalaran",
  ["An Arcane Forge, needed for some Enchanting recipes"] = "Uma Forja Arcana, necessária para algumas receitas de Encantamento",
  ["{i:273116:inv_garrison_blueprints3:Blueprint: Arcane Forge} Dropped by: {n:261809::Nanaya} in Kalimdor"] = "{i:273116:inv_garrison_blueprints3:Blueprint: Arcane Forge} Cai de: {n:261809::Nanaya} em Kalimdor",
  ["Summons the {n:242498::Reagent Bot}, a vendor with class reagents and profession supplies for everyone at the camp"] = "Invoca o {n:242498::Reagent Bot}, um vendedor com reagentes de classe e suprimentos de profissão para todos no acampamento",
  ["Repairs for everyone at the camp"] = "Reparos para todos no acampamento",
  ["{i:273092:inv_garrison_blueprints3:Blueprint: Repair Bot} Dropped by: {n:643::Sneed} in The Deadmines"] = "{i:273092:inv_garrison_blueprints3:Blueprint: Repair Bot} Cai de: {n:643::Sneed} nas Minas Mortas",
  ["An Anarchist's Workbench, needed for some Engineering recipes"] = "Uma Bancada do Anarquista, necessária para algumas receitas de Engenharia",
  ["{i:273117:inv_garrison_blueprints3:Blueprint: Anarchist's Workbench} Dropped by: {n:11058::Ezra Grimm} in Stratholme"] = "{i:273117:inv_garrison_blueprints3:Blueprint: Anarchist's Workbench} Cai de: {n:11058::Ezra Grimm} em Stratholme",
  ["Rested experience up to 5% of a level, once an hour (a debuff blocks it until then)"] = "Experiência descansada de até 5% de um nível, uma vez por hora (uma penalidade bloqueia até lá)",
  ["A Tanning Rack, needed for many Leatherworking recipes"] = "Um Cavalete de Curtume, necessário para muitas receitas de Couraria",
  ["{i:273096:inv_garrison_blueprints3:Blueprint: Tanning Rack} Dropped by: {n:3886::Razorclaw the Butcher} in Shadowfang Keep"] = "{i:273096:inv_garrison_blueprints3:Blueprint: Tanning Rack} Cai de: {n:3886::Razorclaw the Butcher} na Bastilha Presa Negra",
  ["A Sewing Machine, needed for many Leatherworking recipes"] = "Uma Máquina de Costura, necessária para muitas receitas de Couraria",
  ["{i:273121:inv_garrison_blueprints3:Blueprint: Sewing Machine} Dropped by: {n:10432::Vectus} in Scholomance"] = "{i:273121:inv_garrison_blueprints3:Blueprint: Sewing Machine} Cai de: {n:10432::Vectus} em Scolomântia",
  ["Spirit buff for players of your faction, doesn't stack with Divine Spirit. Horde and Alliance each have their own banner"] = "Bônus de Espírito para jogadores da sua facção; não se acumula com Espírito Divino. Horda e Aliança têm cada uma seu próprio estandarte",
  ["A Spinning Wheel, needed for many Tailoring recipes"] = "Uma Roca, necessária para muitas receitas de Alfaiataria",
  ["{i:273099:inv_garrison_blueprints3:Blueprint: Spinning Wheel} Dropped by: {n:246017::Unstable Sentinel} in the City of Dalaran"] = "{i:273099:inv_garrison_blueprints3:Blueprint: Spinning Wheel} Cai de: {n:246017::Unstable Sentinel} na Cidade de Dalaran",
  ["A Loom, needed for many Tailoring recipes"] = "Um Tear, necessário para muitas receitas de Alfaiataria",
  ["{i:273124:inv_garrison_blueprints3:Blueprint: Loom} Dropped by: {n:10436::Baroness Anastari} in Stratholme"] = "{i:273124:inv_garrison_blueprints3:Blueprint: Loom} Cai de: {n:10436::Baroness Anastari} em Stratholme",
  ["Intellect buff, doesn't stack with Arcane Intellect"] = "Bônus de Intelecto; não se acumula com Intelecto Arcano",
  ["A Greenhouse that grows herbs from seeds you plant"] = "Uma Estufa que cultiva ervas a partir das sementes que você planta",
  ["{i:273106:inv_garrison_blueprints3:Blueprint: Greenhouse} Dropped by: {n:260325::Shadetooth} in Excavation Site: Wetlands"] = "{i:273106:inv_garrison_blueprints3:Blueprint: Greenhouse} Cai de: {n:260325::Shadetooth} em Excavation Site: Wetlands",
  ["A Seed Hybridizer that multiplies seeds or combines them into rarer ones"] = "Um Hibridizador de Sementes que multiplica sementes ou as combina em sementes mais raras",
  ["Melee Attack Power buff, doesn't stack with Blessing of Might"] = "Bônus de Poder de Ataque corpo a corpo; não se acumula com Bênção do Poder",
  ["Spawns a common mining node over time, and gives the Lodestone buff too"] = "Faz surgir um nódulo de mineração comum com o tempo e também dá o bônus Magnetita",
  ["{i:273097:inv_garrison_blueprints3:Blueprint: Rock Garden} Dropped by: {n:260326::Relic Guardian} in Excavation Site: Wetlands"] = "{i:273097:inv_garrison_blueprints3:Blueprint: Rock Garden} Cai de: {n:260326::Relic Guardian} em Excavation Site: Wetlands",
  ["A Molten Foundry, needed for Smelt Heavy Thorium"] = "Uma Fundição Derretida, necessária para Fundir Tório Pesado",
  ["{i:273122:inv_garrison_blueprints3:Blueprint: Molten Foundry} Dropped by: {n:9156::Ambassador Flamelash} in Blackrock Depths"] = "{i:273122:inv_garrison_blueprints3:Blueprint: Molten Foundry} Cai de: {n:9156::Ambassador Flamelash} no Abismo Rocha Negra",
  ["+2% crit chance, doesn't stack with Moonkin Aura"] = "+2% de chance de acerto crítico; não se acumula com Aura de Luniscante",
  ["A book anyone can read to learn Track Beasts"] = "Um livro que qualquer um pode ler para aprender Rastrear Feras",
  ["{i:273098:inv_garrison_blueprints3:Blueprint: Field Guide} Dropped by: {n:3671::Lady Anacondra} in Wailing Caverns"] = "{i:273098:inv_garrison_blueprints3:Blueprint: Field Guide} Cai de: {n:3671::Lady Anacondra} na Caverna Ululante",
  ["A workbench with 1 trap"] = "Uma bancada com 1 armadilha",
  ["{i:273109:inv_garrison_blueprints3:Blueprint: Trapper's Workbench} Dropped by: {n:10430::The Beast} in Upper Blackrock Spire and {n:3974::Houndmaster Loksey} in Scarlet Monastery"] = "{i:273109:inv_garrison_blueprints3:Blueprint: Trapper's Workbench} Cai de: {n:10430::The Beast} no Pico da Rocha Negra Superior e de {n:3974::Houndmaster Loksey} no Monastério Escarlate",
  ["Cooking has no tier 1 camp item, its first one is the campfire (see How to Make a Campfire above)."] = "Culinária não tem item de acampamento de nível 1; o primeiro é a fogueira (veja Como fazer uma fogueira acima).",
  ["Stamina food for everyone at the camp"] = "Comida de Vigor para todos no acampamento",
  ["{i:273102:inv_garrison_blueprints3:Blueprint: Cookie's Feast} Dropped by: {n:645::Cookie} in The Deadmines"] = "{i:273102:inv_garrison_blueprints3:Blueprint: Cookie's Feast} Cai de: {n:645::Cookie} nas Minas Mortas",
  ["An Iron Oven, needed for the most advanced Cooking recipes"] = "Um Forno de Ferro, necessário para as receitas de Culinária mais avançadas",
  ["{i:273115:inv_garrison_blueprints3:Blueprint: Iron Oven} Dropped by: {n:9736::Quartermaster Zigris} in Lower Blackrock Spire"] = "{i:273115:inv_garrison_blueprints3:Blueprint: Iron Oven} Cai de: {n:9736::Quartermaster Zigris} no Pico da Rocha Negra Inferior",
  ["Stamina buff, doesn't stack with Power Word: Fortitude"] = "Bônus de Vigor; não se acumula com Palavra de Poder: Fortitude",
  ["Healing potions and anti-venom"] = "Poções de cura e antídoto",
  ["{i:273105:inv_garrison_blueprints3:Blueprint: Toxin Study} Dropped by: {n:4278::Commander Springvale} in Shadowfang Keep"] = "{i:273105:inv_garrison_blueprints3:Blueprint: Toxin Study} Cai de: {n:4278::Commander Springvale} na Bastilha Presa Negra",
  ["Healing potions and poultices"] = "Poções de cura e cataplasmas",
  ["{i:273118:inv_garrison_blueprints3:Blueprint: Plague Doctor's Laboratory} Dropped by: {n:11261::Doctor Theolen Krastinov} in Scholomance"] = "{i:273118:inv_garrison_blueprints3:Blueprint: Plague Doctor's Laboratory} Cai de: {n:11261::Doctor Theolen Krastinov} em Scolomântia",
  ["+8% all stats, doesn't stack with Blessing of Kings"] = "+8% em todos os atributos; não se acumula com Bênção dos Reis",
  ["Uncommon fish for 1 hour and Fishing lures"] = "Peixes incomuns por 1 hora e iscas de Pesca",
  ["{i:273141:inv_garrison_blueprints3:Blueprint: Fishing Rack} Dropped by: {n:6243::Gelihast} in Blackfathom Deeps"] = "{i:273141:inv_garrison_blueprints3:Blueprint: Fishing Rack} Cai de: {n:6243::Gelihast} nas Profundezas Negras",
  ["Rare fish for 1 hour and Fishing lures"] = "Peixes raros por 1 hora e iscas de Pesca",
  ["{i:273119:inv_garrison_blueprints3:Blueprint: Fishing Hut} Dropped by: {n:5710::Jammal'an the Prophet} in the Sunken Temple"] = "{i:273119:inv_garrison_blueprints3:Blueprint: Fishing Hut} Cai de: {n:5710::Jammal'an the Prophet} no Templo Submerso",
  ["Crafting Stations: Tanning Rack, Loom and More"] = "Estações de criação: Cavalete de Curtume, Tear e mais",
  ["A lot of recipes in WoW Forever need a crafting station nearby, like a Tanning Rack, a Spinning Wheel or a Loom. {b}I haven't found any of them out in the world{/b}, they only come from camps, so for a lot of higher level crafting you need a camp. The easiest way is a camp that already has the station, anyone at the fire can use it."] = "Muitas receitas no WoW Forever precisam de uma estação de criação por perto, como um Cavalete de Curtume, uma Roca ou um Tear. {b}Não encontrei nenhuma delas pelo mundo{/b}; elas só vêm de acampamentos, então para boa parte da criação de nível mais alto você precisa de um acampamento. O jeito mais fácil é um acampamento que já tenha a estação; qualquer um junto à fogueira pode usá-la.",
  ["To place one yourself:"] = "Para colocar uma você mesmo:",
  ["Get your profession to the skill in the table below."] = "Leve sua profissão até a perícia indicada na tabela abaixo.",
  ["Get the station's Blueprint and learn it. The table shows where it drops, if we know it."] = "Consiga a Planta da estação e aprenda-a. A tabela mostra onde ela cai, se soubermos.",
  ["Craft the station, put down a campfire and use the station from your bags next to it."] = "Crie a estação, coloque uma fogueira e use a estação a partir das bolsas ao lado dela.",
  ["Station"] = "Estação",
  ["Profession"] = "Profissão",
  ["Blueprint"] = "Planta",
  ["Dropped by: {n:250657::Rath'mael} in the Ruins of Lordaeron"] = "Cai de: {n:250657::Rath'mael} nas Ruínas de Lordaeron",
  ["Dropped by: {n:10508::Ras Frostwhisper} in Scholomance"] = "Cai de: {n:10508::Ras Frostwhisper} em Scolomântia",
  ["Dropped by: {n:8983::Golem Lord Argelmach} in Blackrock Depths"] = "Cai de: {n:8983::Golem Lord Argelmach} no Abismo Rocha Negra",
  ["Dropped by: {n:261809::Nanaya} in Kalimdor"] = "Cai de: {n:261809::Nanaya} em Kalimdor",
  ["Dropped by: {n:11058::Ezra Grimm} in Stratholme"] = "Cai de: {n:11058::Ezra Grimm} em Stratholme",
  ["Dropped by: {n:3886::Razorclaw the Butcher} in Shadowfang Keep"] = "Cai de: {n:3886::Razorclaw the Butcher} na Bastilha Presa Negra",
  ["Dropped by: {n:10432::Vectus} in Scholomance"] = "Cai de: {n:10432::Vectus} em Scolomântia",
  ["Dropped by: {n:246017::Unstable Sentinel} in the City of Dalaran"] = "Cai de: {n:246017::Unstable Sentinel} na Cidade de Dalaran",
  ["Dropped by: {n:10436::Baroness Anastari} in Stratholme"] = "Cai de: {n:10436::Baroness Anastari} em Stratholme",
  ["Dropped by: {n:9156::Ambassador Flamelash} in Blackrock Depths"] = "Cai de: {n:9156::Ambassador Flamelash} no Abismo Rocha Negra",
  ["Dropped by: {n:9736::Quartermaster Zigris} in Lower Blackrock Spire"] = "Cai de: {n:9736::Quartermaster Zigris} no Pico da Rocha Negra Inferior",
  ["Merchant's Favor is a new currency in WoW Forever. You get it by filling Waylaid Crates with materials and handing them in at your faction's camp, Durotar Supply and Logistics for Horde and the Azeroth Commerce Authority for Alliance, and you spend it on the recipes, mount, pet, tabard and titles the camp vendors sell. Many recipes and the mount, pet and tabard also need reputation with the camp, which you get from Craftsman's Writs. This WoW Forever Merchant's Favor guide will show you where the camps are, how to earn Merchant's Favor and reputation, and every recipe the vendors sell."] = "Favor do Mercador é uma nova moeda no WoW Forever. Você a ganha enchendo Caixotes Extraviados com materiais e entregando-os no acampamento da sua facção, Durotar Supply and Logistics para a Horda e Azeroth Commerce Authority para a Aliança, e a gasta nas receitas, montaria, mascote, tabardo e títulos que os vendedores do acampamento vendem. Muitas receitas e a montaria, o mascote e o tabardo também exigem reputação com o acampamento, que você ganha com as Ordens de Artesão. Este guia de Favor do Mercador do WoW Forever mostra onde ficam os acampamentos, como ganhar Favor do Mercador e reputação, e todas as receitas que os vendedores vendem.",
  ["How It Works"] = "Como funciona",
  ["Waylaid Crates drop randomly in the open world and in dungeons, and you can also buy them on the Auction House. You fill a crate with the materials it asks for and hand it in at your camp. For that you get Merchant's Favor, the currency you buy the recipes with."] = "Os Caixotes Extraviados caem aleatoriamente no mundo aberto e em masmorras, e você também pode comprá-los na casa de leilões. Você enche um caixote com os materiais que ele pede e o entrega no seu acampamento. Em troca, recebe Favor do Mercador, a moeda com que compra as receitas.",
  ["Many recipes also need reputation with the camp. You earn reputation by doing Craftsman's Writs. You get a writ, craft the item it asks for and bring it to the customer."] = "Muitas receitas também exigem reputação com o acampamento. Você ganha reputação fazendo Ordens de Artesão: você recebe uma ordem, cria o item que ela pede e o leva ao cliente.",
  ["Where the Camps Are"] = "Onde ficam os acampamentos",
  ["The Horde camp belongs to Durotar Supply and Logistics, and the Alliance camp belongs to the Azeroth Commerce Authority. Each camp has a recipe vendor for every crafting profession and Cooking, and both camps sell the same recipes (see Recipes by Profession below)."] = "O acampamento da Horda pertence à Durotar Supply and Logistics, e o da Aliança pertence à Azeroth Commerce Authority. Cada acampamento tem um vendedor de receitas para cada profissão de criação e para Culinária, e os dois acampamentos vendem as mesmas receitas (veja Receitas por profissão abaixo).",
  ["Three Corners, Redridge Mountains"] = "Três Cantos, Montanhas Cristarrubra",
  ["How to Earn Merchant's Favor"] = "Como ganhar Favor do Mercador",
  ["You earn Merchant's Favor by filling Waylaid Crates with materials and bringing them to your camp."] = "Você ganha Favor do Mercador enchendo Caixotes Extraviados com materiais e levando-os ao seu acampamento.",
  ["Merchant's Favor is per character, so every character has to earn its own."] = "O Favor do Mercador é por personagem, então cada personagem precisa ganhar o seu.",
  ["Filling a Waylaid Crate"] = "Enchendo um Caixote Extraviado",
  ["{b}Find a Waylaid Crate.{/b} They drop randomly in the open world and in dungeons, and {b}you can also buy them on the Auction House{/b}. Each one asks for one kind of material, for example {i:248684:inv_crate_07:Waylaid Crate: Apprentice Textiles}."] = "{b}Encontre um Caixote Extraviado.{/b} Eles caem aleatoriamente no mundo aberto e em masmorras, e {b}você também pode comprá-los na casa de leilões{/b}. Cada um pede um tipo de material, por exemplo {i:248684:inv_crate_07:Waylaid Crate: Apprentice Textiles}.",
  ["Right-click it and fill it with one of the bundles it lists, for example 40 Linen Cloth or 20 Light Leather (see Waylaid Crates and Rewards below). You get a Sealed crate, and that one binds to you."] = "Clique nele com o botão direito e encha-o com um dos lotes que ele lista, por exemplo 40 Tecidos de Linho ou 20 Couros Leves (veja Caixotes Extraviados e recompensas abaixo). Você recebe um caixote Lacrado, que fica vinculado a você.",
  ["Bring the Sealed crate to {n:0::Dokimi} at the Horde camp or {n:0::Marcy Baker} at the Alliance camp. You get Merchant's Favor and some silver for it."] = "Leve o caixote Lacrado até {n:0::Dokimi} no acampamento da Horda ou {n:0::Marcy Baker} no acampamento da Aliança. Você recebe Favor do Mercador e algumas pratas por ele.",
  ["Waylaid Crates and Rewards"] = "Caixotes Extraviados e recompensas",
  ["When you fill a Waylaid Crate, it turns into a Sealed crate of the same rank and color. You hand that one in at your camp for the Merchant's Favor in the last column. There are also blue Sealed crates and a Sealed Elite Crate, but I don't know yet what they give."] = "Quando você enche um Caixote Extraviado, ele se transforma em um caixote Lacrado da mesma categoria e cor. Você o entrega no seu acampamento em troca do Favor do Mercador da última coluna. Também existem caixotes Lacrados azuis e um Caixote Lacrado de Elite, mas ainda não sei o que eles dão.",
  ["The Textiles, Ore, Herbs and Curiosities crates take raw materials, and the Fabrics, Ingots and Parts crates take crafted ones."] = "Os caixotes de Têxteis, Minério, Ervas e Curiosidades aceitam materiais brutos, e os de Tecidos, Lingotes e Peças aceitam materiais criados.",
  ["{b}A crate needs only one of the bundles in its row, not all of them.{/b}"] = "{b}Um caixote precisa de apenas um dos lotes da sua linha, não de todos.{/b}",
  ["Apprentice"] = "Aprendiz",
  ["Journeyman"] = "Artífice",
  ["Expert"] = "Especialista",
  ["Artisan"] = "Artesão",
  ["You need level 10 to open these."] = "Você precisa de nível 10 para abrir estes.",
  ["You also get {m:2:s:} {m:50:c:} for a white crate and {m:5:s:} for a green one."] = "Você também recebe {m:2:s:} {m:50:c:} por um caixote branco e {m:5:s:} por um verde.",
  ["Crate"] = "Caixote",
  ["Fill it with one of these"] = "Encha com um destes",
  ["Reward"] = "Recompensa",
  ["You also get {m:5:s:} for a white crate and {m:10:s:} for a green one."] = "Você também recebe {m:5:s:} por um caixote branco e {m:10:s:} por um verde.",
  ["You need level 20 to open these."] = "Você precisa de nível 20 para abrir estes.",
  ["You also get {m:7:s:} {m:50:c:} for a white crate and {m:15:s:} for a green one."] = "Você também recebe {m:7:s:} {m:50:c:} por um caixote branco e {m:15:s:} por um verde.",
  ["You need level 35 to open these."] = "Você precisa de nível 35 para abrir estes.",
  ["Not known yet"] = "Ainda desconhecido",
  ["How to Earn Durotar Supply and Azeroth Commerce Authority Reputation"] = "Como ganhar reputação com Durotar Supply e Azeroth Commerce Authority",
  ["{b}Handing in Sealed crates doesn't give reputation.{/b} Reputation with Durotar Supply and Logistics or the Azeroth Commerce Authority comes from Craftsman's Writs, crafting orders that you deliver to a customer somewhere in the world. After reaching Friendly, empty Waylaid Crates give reputation too (see Crate Returns after Friendly below)."] = "{b}Entregar caixotes Lacrados não dá reputação.{/b} A reputação com Durotar Supply and Logistics ou com Azeroth Commerce Authority vem das Ordens de Artesão, encomendas de criação que você entrega a um cliente em algum lugar do mundo. Depois de chegar a Amigável, Caixotes Extraviados vazios também dão reputação (veja Devolução de caixotes depois de Amigável abaixo).",
  ["The first time you fill a crate or start a writ, you also get a {i:280180:inv_misc_note_03:Shipping Label}. It starts a quest to your camp, which gives 2,000 reputation and 50 Merchant's Favor."] = "Na primeira vez que você enche um caixote ou começa uma ordem, também recebe uma {i:280180:inv_misc_note_03:Shipping Label}. Ela inicia uma missão até o seu acampamento, que dá 2.000 de reputação e 50 de Favor do Mercador.",
  ["Craftsman's Writs"] = "Ordens de Artesão",
  ["A Journeyman writ gives 75 reputation, an Expert writ 125 and an Artisan writ 200. {b}You can do each writ once a day{/b}, and as many different writs a day as you want."] = "Uma ordem Artífice dá 75 de reputação, uma Especialista dá 125 e uma Artesão dá 200. {b}Você pode fazer cada ordem uma vez por dia{/b}, e quantas ordens diferentes quiser por dia.",
  ["{b}Get a Craftsman's Writ.{/b} In the open world and in dungeons they drop as a {i:262888:inv_misc_note_02:Sealed Journeyman's Writ}, {i:262889:inv_misc_note_02:Sealed Expert's Writ} or {i:262890:inv_misc_note_02:Sealed Artisan's Writ}, an envelope with a random writ of that rank inside. {b}You can also buy writs on the Auction House.{/b}"] = "{b}Consiga uma Ordem de Artesão.{/b} No mundo aberto e em masmorras elas caem como {i:262888:inv_misc_note_02:Sealed Journeyman's Writ}, {i:262889:inv_misc_note_02:Sealed Expert's Writ} ou {i:262890:inv_misc_note_02:Sealed Artisan's Writ}, um envelope com uma ordem aleatória dessa categoria dentro. {b}Você também pode comprar ordens na casa de leilões.{/b}",
  ["Right-click the writ to start its quest, for example {i:264047:inv_misc_note_01:Craftsman's Writ: Lesser Wizard's Robe}."] = "Clique na ordem com o botão direito para iniciar a missão dela, por exemplo {i:264047:inv_misc_note_01:Craftsman's Writ: Lesser Wizard's Robe}.",
  ["Make the item it asks for or buy it on the Auction House. You don't need the profession yourself."] = "Faça o item que ela pede ou compre-o na casa de leilões. Você mesmo não precisa ter a profissão.",
  ["Bring the item to the customer, your map shows where. The customer takes the item and the writ, and you get the reputation and a Coin Pouch with some silver. Writs don't give Merchant's Favor. {b}On the beta, the customer had no question mark over their head.{/b} I think it was a bug, so if you don't see one, right-click them anyway and the window to hand in the writ opens."] = "Leve o item ao cliente; seu mapa mostra onde ele está. O cliente fica com o item e a ordem, e você recebe a reputação e uma Bolsa de Moedas com algumas pratas. As ordens não dão Favor do Mercador. {b}No beta, o cliente não tinha ponto de interrogação sobre a cabeça.{/b} Acho que era um bug, então se não vir um, clique nele com o botão direito mesmo assim e a janela para entregar a ordem vai abrir.",
  ["Crate Returns after Friendly"] = "Devolução de caixotes depois de Amigável",
  ["At Friendly, you unlock the Uncertified Scribe in your camp, {n:0:horde:Kurvelk Shadowhoof} at the Horde camp and {n:0:alliance:Dianne Softstep} at the Alliance camp. Both sell the same two items:"] = "Ao chegar a Amigável, você libera o Escriba Não Certificado no seu acampamento: {n:0:horde:Kurvelk Shadowhoof} no acampamento da Horda e {n:0:alliance:Dianne Softstep} no acampamento da Aliança. Os dois vendem os mesmos dois itens:",
  ["Reputation"] = "Reputação",
  ["What it does"] = "O que faz",
  ["Friendly"] = "Amigável",
  ["Turns an empty Waylaid Crate into 50 reputation, see the steps below."] = "Transforma um Caixote Extraviado vazio em 50 de reputação; veja os passos abaixo.",
  ["Honored"] = "Honrado",
  ["Turns a Craftsman's Writ into a random writ of the same rank."] = "Transforma uma Ordem de Artesão em uma ordem aleatória da mesma categoria.",
  ["{b}Buy a {i:262902:inv_10_inscription2_repcontracts_scroll_02_uprez_color5:Forged Delivery Receipt}{/b} from the Uncertified Scribe."] = "{b}Compre um {i:262902:inv_10_inscription2_repcontracts_scroll_02_uprez_color5:Forged Delivery Receipt}{/b} com o Escriba Não Certificado.",
  ["Buy a Waylaid Crate on the Auction House. The receipt seems to work on any of them, so buy the cheapest one."] = "Compre um Caixote Extraviado na casa de leilões. O recibo parece funcionar em qualquer um deles, então compre o mais barato.",
  ["Use the receipt on the crate. You get a {i:262917:inv_crate_01:Notarized Shipping Container}."] = "Use o recibo no caixote. Você recebe um {i:262917:inv_crate_01:Notarized Shipping Container}.",
  ["Hand the container to the same NPC who takes your Sealed crates. You get the reputation and 1 silver."] = "Entregue o contêiner ao mesmo PNJ que recebe seus caixotes Lacrados. Você recebe a reputação e 1 prata.",
  ["Recipes by Profession"] = "Receitas por profissão",
  ["Both camps, Durotar Supply and Logistics (Horde) and the Azeroth Commerce Authority (Alliance), sell the same recipes for Merchant's Favor. This is what each profession gets:"] = "Os dois acampamentos, Durotar Supply and Logistics (Horda) e Azeroth Commerce Authority (Aliança), vendem as mesmas receitas por Favor do Mercador. Isto é o que cada profissão recebe:",
  ["{b}Alchemy:{/b} potions and elixirs."] = "{b}Alquimia:{/b} poções e elixires.",
  ["{b}Blacksmithing:{/b} mail and plate sets for tanks, melee, healers and paladins, and three weapons."] = "{b}Ferraria:{/b} conjuntos de malha e placas para tanques, corpo a corpo, curandeiros e paladinos, e três armas.",
  ["{b}Cooking:{/b} six smoothies that give Spirit."] = "{b}Culinária:{/b} seis vitaminas que dão Espírito.",
  ["{b}Enchanting:{/b} necklace, weapon and armor enchants, relics (idols, totems and librams) and caster weapons (staves, off-hands and wands)."] = "{b}Encantamento:{/b} encantamentos de colar, arma e armadura, relíquias (ídolos, totens e tomos) e armas de lançadores (báculos, itens de mão secundária e varinhas).",
  ["{b}Engineering:{/b} bombs, thrown weapons, goggles, belts, trinkets and gadgets."] = "{b}Engenharia:{/b} bombas, armas de arremesso, óculos, cintos, berloques e engenhocas.",
  ["{b}Leatherworking:{/b} leather and mail sets for every role, and two armor kits."] = "{b}Couraria:{/b} conjuntos de couro e malha para todos os papéis, e dois kits de armadura.",
  ["{b}Tailoring:{/b} cloth sets for every spell school and for healers, and two reagent bags."] = "{b}Alfaiataria:{/b} conjuntos de tecido para cada escola de magia e para curandeiros, e duas bolsas de reagentes.",
  ["{b}The armor and weapons you craft from these recipes bind on pickup{/b}, so you can only make them for yourself."] = "{b}As armaduras e armas que você cria com estas receitas são vinculadas ao serem coletadas{/b}, então você só pode fazê-las para si mesmo.",
  ["{n:0:horde:Apothecary Durelle} at the Horde camp and {n:0:alliance:Nina Surefire} at the Alliance camp sell 28 Alchemy recipes."] = "{n:0:horde:Apothecary Durelle} no acampamento da Horda e {n:0:alliance:Nina Surefire} no acampamento da Aliança vendem 28 receitas de Alquimia.",
  ["Potions"] = "Poções",
  ["Elixirs"] = "Elixires",
  ["Req. Level"] = "Nível req.",
  ["Effect"] = "Efeito",
  ["Prof. Skill"] = "Perícia",
  ["+31 healing for 30 sec"] = "+31 de cura por 30 s",
  ["+16 spell damage for 30 sec"] = "+16 de dano mágico por 30 s",
  ["+28 attack power for 30 sec"] = "+28 de poder de ataque por 30 s",
  ["282 Fire damage in a cone in front of you, then 35 every 2 sec for 8 sec"] = "282 de dano de Fogo em um cone à sua frente e depois 35 a cada 2 s por 8 s",
  ["Thrown, a cloud for 12 sec that deals 31-36 Nature damage every second to enemies in it"] = "Arremessável: uma nuvem por 12 s que causa 31-36 de dano de Natureza por segundo aos inimigos dentro dela",
  ["10 doses for 20 sec. When you take Bleed damage, a dose moves to a nearby enemy and deals 325 Nature damage when it ends"] = "10 doses por 20 s. Quando você sofre dano de Sangramento, uma dose passa para um inimigo próximo e causa 325 de dano de Natureza quando termina",
  ["+88 healing for 30 sec"] = "+88 de cura por 30 s",
  ["+105 spell damage against Elementals for 5 min"] = "+105 de dano mágico contra Elementais por 5 min",
