  ["{n:0:horde:Gor'mak} at the Horde camp and {n:0:alliance:Stondry Darkhammer} at the Alliance camp sell 61 Blacksmithing recipes."] = "{n:0:horde:Gor'mak} no acampamento da Horda e {n:0:alliance:Stondry Darkhammer} no acampamento da Aliança vendem 61 receitas de Ferraria.",
  ["Tank"] = "Tanque",
